-- library-source: acsm_2009_progression sha256:73f420b8bca8bf68ead7ac0de8c88414cfa05877f540bedb2c4d52a9a49352d7
select private.library_replace_source(
$lib${"slug":"acsm_2009_progression","title":"Progression models in resistance training for healthy adults","authors":["American College of Sports Medicine"],"year":2009,"doi":"10.1249/MSS.0b013e3181915670","url":"https://doi.org/10.1249/MSS.0b013e3181915670","licence":"proprietary","region":["global"],"topics":["training","strength","hypertrophy","progression","frequency","rest","intensity"],"evidence_level":"position stand","kind":"position_stand"}$lib$::jsonb,
$lib$[{"ordinal":0,"section":"What the position stand covers","header":"Source: ACSM 2009, Progression models in resistance training for healthy adults. Section: What the position stand covers.","body":"This American College of Sports Medicine position stand lays out how resistance training should change as a healthy adult gets more experienced. Its core idea is that adaptation needs a stimulus that keeps moving upward, so a programme has to progress instead of repeating the same work.\n\nFor exercise choice it favours a mix: single-joint and multi-joint lifts, work on both sides together and one side at a time, and lifting and lowering phases as well as holds. When ordering exercises inside a session it suggests protecting the quality of the hard work: big muscle groups before small ones, multi-joint lifts before single-joint lifts, and heavier work before lighter work.","token_count":200},{"ordinal":1,"section":"Loads, rest and lifting speed","header":"Source: ACSM 2009, Progression models in resistance training for healthy adults. Section: Loads, rest and lifting speed.","body":"For beginners (people new to lifting, or back after several years away) it recommends loads that allow roughly 8 to 12 repetitions to failure. For intermediate lifters (about six months of steady training) and advanced lifters (years of training) it recommends a wider span, from 1 to 12 repetitions, varied over time in a planned way, with heavy work in the 1 to 6 range gaining emphasis for strength. Strength work uses long rests of about 3 to 5 minutes and a moderate lifting speed of roughly one to two seconds up and one to two seconds down.\n\nFor muscle size it keeps the same exercise choices and frequency advice, but puts the emphasis on loads in the 6 to 12 repetition range with shorter rests of about 1 to 2 minutes, and it calls for higher-volume, multiple-set work to maximise growth.","token_count":230},{"ordinal":2,"section":"When to add load, and how often to train","header":"Source: ACSM 2009, Progression models in resistance training for healthy adults. Section: When to add load, and how often to train.","body":"The progression rule is simple: when a lifter can do one or two repetitions more than the target at the current load, increase the load by about 2 to 10 percent.\n\nSuggested training frequency rises with experience: 2 to 3 days a week for beginners, 3 to 4 for intermediate lifters and 4 to 5 for advanced lifters.","token_count":112},{"ordinal":3,"section":"Practical reading and limits","header":"Source: ACSM 2009, Progression models in resistance training for healthy adults. Section: Practical reading and limits.","body":"This is a 2009 document and the college has since published an updated overview (see the ACSM 2026 entry), which found that many programme details matter less than once thought. Use this entry for the shape of progression by experience level and the double-progression style rule, not as proof that one rep range or one rest length is the only good choice. Tracend's own rules set the actual numbers in a plan.","token_count":133}]$lib$::jsonb
);

-- library-source: acsm_2026_resistance_prescription sha256:a1564445d4d339a6147c5b693809d116e212632b59827de865e6e5d05ac6a4eb
select private.library_replace_source(
$lib${"slug":"acsm_2026_resistance_prescription","title":"American College of Sports Medicine position stand: resistance training prescription for muscle function, hypertrophy, and physical performance in healthy adults: an overview of reviews","authors":["Currier BS","D'Souza AC","Singh MAF","Lowisz CV","Rawson ES","Schoenfeld BJ"],"year":2026,"doi":"10.1249/MSS.0000000000003897","url":"https://doi.org/10.1249/MSS.0000000000003897","licence":"CC-BY-NC-ND-4.0","region":["global"],"topics":["training","strength","hypertrophy","volume","intensity","progression","frequency"],"evidence_level":"position stand; overview of 137 systematic reviews","kind":"position_stand"}$lib$::jsonb,
$lib$[{"ordinal":0,"section":"What this position stand is","header":"Source: Currier et al. 2026 (ACSM), American College of Sports Medicine position stand: resistance training prescription for muscle function, hypertrophy, and physical performance in healthy adults: an overview of reviews. Section: What this position stand is.","body":"This 2026 American College of Sports Medicine position stand replaces its 2009 progression-models stand. Instead of reviewing individual trials it pooled 137 systematic reviews covering more than 30,000 healthy adults aged 18 and over. The reviews it used each compared resistance training lasting at least six weeks against either no exercise or a different training programme. The literature search ran to October 2024.","token_count":171},{"ordinal":1,"section":"What resistance training does","header":"Source: Currier et al. 2026 (ACSM), American College of Sports Medicine position stand: resistance training prescription for muscle function, hypertrophy, and physical performance in healthy adults: an overview of reviews. Section: What resistance training does.","body":"Compared with doing no exercise, resistance training clearly improved strength, muscle size, power and endurance, and it also improved contraction speed, walking speed, balance and several measures of everyday physical function. The headline conclusion is that healthy adults should do progressive resistance training, with the details varied in line with the findings below.","token_count":160},{"ordinal":2,"section":"Variables that did change results","header":"Source: Currier et al. 2026 (ACSM), American College of Sports Medicine position stand: resistance training prescription for muscle function, hypertrophy, and physical performance in healthy adults: an overview of reviews. Section: Variables that did change results.","body":"Strength improved more with heavier loads (80 percent of the one-repetition maximum or more), with a full range of motion, with 2 to 3 sets, with strength work placed early in the session, and with at least two sessions a week.\n\nMuscle size improved more with higher weekly volume (10 or more sets per week for the muscle) and with eccentric overload, meaning extra emphasis on the lowering phase.\n\nPower improved more with moderate loads (30 to 70 percent of the one-repetition maximum), low to moderate volume, Olympic-style lifts and deliberately fast lifting. Power training also improved physical function.","token_count":220},{"ordinal":3,"section":"Variables that did not consistently matter","header":"Source: Currier et al. 2026 (ACSM), American College of Sports Medicine position stand: resistance training prescription for muscle function, hypertrophy, and physical performance in healthy adults: an overview of reviews. Section: Variables that did not consistently matter.","body":"Across the reviews, these did not reliably change outcomes: training to momentary muscle failure, the type of equipment, how complex the exercise is, how sets are structured, time under tension, blood flow restriction, and periodisation.\n\nRead this carefully: it says the effect was not consistent across reviews, not that these things never help. More detailed analyses, such as the proximity-to-failure meta-regression elsewhere in this library, can still find small effects.","token_count":189},{"ordinal":4,"section":"Practical reading","header":"Source: Currier et al. 2026 (ACSM), American College of Sports Medicine position stand: resistance training prescription for muscle function, hypertrophy, and physical performance in healthy adults: an overview of reviews. Section: Practical reading.","body":"The main message for coaching is reassuring: a progressive plan that trains each muscle at least twice across the week, uses a mix of load ranges, keeps weekly volume at roughly ten or more hard sets for muscles the person wants to grow, and uses the lowering phase well covers most of what the evidence supports. Fine details such as exact tempo or equipment brand rarely deserve worry. This is an overview of reviews of mostly young, healthy adults, so it says less about older adults, people with health conditions or very advanced lifters.","token_count":199}]$lib$::jsonb
);

-- library-source: schoenfeld_2017_weekly_volume sha256:b8f816d54d0078a18c7afb9199d9e945e8004089f4fcede2cebb0657ac37227f
select private.library_replace_source(
$lib${"slug":"schoenfeld_2017_weekly_volume","title":"Dose-response relationship between weekly resistance training volume and increases in muscle mass: a systematic review and meta-analysis","authors":["Schoenfeld BJ","Ogborn D","Krieger JW"],"year":2017,"doi":"10.1080/02640414.2016.1210197","url":"https://doi.org/10.1080/02640414.2016.1210197","licence":"proprietary","region":["global"],"topics":["training","hypertrophy","volume"],"evidence_level":"systematic review and meta-analysis (15 studies)","kind":"paper"}$lib$::jsonb,
$lib$[{"ordinal":0,"section":"What the review did","header":"Source: Schoenfeld et al. 2017, Dose-response relationship between weekly resistance training volume and increases in muscle mass: a systematic review and meta-analysis. Section: What the review did.","body":"The authors pooled 15 studies (34 training groups) that compared different weekly amounts of resistance training and measured changes in muscle size. They used meta-regression, a method that checks whether more sets per week goes with more growth, instead of only comparing a high group with a low group.","token_count":126},{"ordinal":1,"section":"What it found","header":"Source: Schoenfeld et al. 2017, Dose-response relationship between weekly resistance training volume and increases in muscle mass: a systematic review and meta-analysis. Section: What it found.","body":"More weekly sets went with more growth. Each extra set per muscle per week was linked to a small gain in effect size, which the authors translated to roughly 0.4 percentage points more muscle gain. Comparing the higher-volume and lower-volume groups within each study, the higher groups gained about 4 percentage points more. When sets per week were sorted into fewer than 5, 5 to 9, and 10 or more, the trend pointed the same way but did not quite reach conventional statistical significance.\n\nThe authors described this as a graded dose-response relationship: more volume tends to produce more growth.","token_count":200},{"ordinal":2,"section":"Practical reading and limits","header":"Source: Schoenfeld et al. 2017, Dose-response relationship between weekly resistance training volume and increases in muscle mass: a systematic review and meta-analysis. Section: Practical reading and limits.","body":"The review supports the idea that doing more hard sets per week helps muscle growth, but it does not say that more is always better without limit, that one number fits everyone, or that very high volumes are practical or recoverable. Newer analyses (see the Pelland 2026 entry) find diminishing returns as volume climbs. Studies were mostly of young, healthy people over weeks to months. Coach should present volume as a lever with diminishing returns that is limited by recovery, time and joint tolerance.","token_count":179}]$lib$::jsonb
);

-- library-source: schoenfeld_2021_loading_continuum sha256:5a6fb186182efddf97f9ceb2df25a84982baa22a341c90f13c08c3c5aead6485
select private.library_replace_source(
$lib${"slug":"schoenfeld_2021_loading_continuum","title":"Loading recommendations for muscle strength, hypertrophy, and local endurance: a re-examination of the repetition continuum","authors":["Schoenfeld BJ","Grgic J","Van Every DW","Plotkin DL"],"year":2021,"doi":"10.3390/sports9020032","url":"https://doi.org/10.3390/sports9020032","licence":"CC-BY-4.0","region":["global"],"topics":["training","strength","hypertrophy","intensity"],"evidence_level":"narrative review","kind":"paper"}$lib$::jsonb,
$lib$[{"ordinal":0,"section":"The old rule and the challenge to it","header":"Source: Schoenfeld et al. 2021, Loading recommendations for muscle strength, hypertrophy, and local endurance: a re-examination of the repetition continuum. Section: The old rule and the challenge to it.","body":"A common teaching, called the repetition continuum, says heavy loads are best for maximal strength, moderate loads for muscle size, and light loads for muscular endurance. This review looks at the evidence behind that idea and finds that parts of it do not hold up.","token_count":118},{"ordinal":1,"section":"The proposed view","header":"Source: Schoenfeld et al. 2021, Loading recommendations for muscle strength, hypertrophy, and local endurance: a re-examination of the repetition continuum. Section: The proposed view.","body":"The authors propose a new view in which muscle adaptations can be obtained, and in some cases optimised, across a wide spectrum of loading zones instead of one zone per goal. They argue that the sharp boundaries in the old model are not supported by current research, and they discuss the nuances and what they imply for programming.","token_count":130},{"ordinal":2,"section":"Practical reading","header":"Source: Schoenfeld et al. 2021, Loading recommendations for muscle strength, hypertrophy, and local endurance: a re-examination of the repetition continuum. Section: Practical reading.","body":"For coaching this means a lifter does not need to force a single rep range. Someone with sore joints can build muscle with lighter loads taken close to hard effort, while someone chasing a strength number should still spend time with heavy loads (the Lopez 2021 network meta-analysis in this library found strength gains were larger with heavier loads). Choosing loads the person can perform with good technique and tolerate week after week is a legitimate way to keep training consistent. The article is a narrative review, so it argues from the evidence and does not give a numeric dose.","token_count":194}]$lib$::jsonb
);

-- library-source: pelland_2026_volume_frequency sha256:cb17d58e7b10b66470c9fe4e2e64fc3094f6fc42d2d10c1ff436b8db40d8056f
select private.library_replace_source(
$lib${"slug":"pelland_2026_volume_frequency","title":"The resistance training dose response: meta-regressions exploring the effects of weekly volume and frequency on muscle hypertrophy and strength gains","authors":["Pelland JC","Remmert JF","Robinson ZP","Hinson SR","Zourdos MC"],"year":2026,"doi":"10.1007/s40279-025-02344-w","url":"https://doi.org/10.1007/s40279-025-02344-w","licence":"proprietary","region":["global"],"topics":["training","hypertrophy","strength","volume","frequency"],"evidence_level":"meta-regression of 67 studies","kind":"paper"}$lib$::jsonb,
$lib$[{"ordinal":0,"section":"What the analysis did","header":"Source: Pelland et al. 2026, The resistance training dose response: meta-regressions exploring the effects of weekly volume and frequency on muscle hypertrophy and strength gains. Section: What the analysis did.","body":"The authors combined 67 studies with 2,058 participants (about four in five men, average age about 25). Their key step was classifying sets as direct or indirect for each muscle: a bench press is a direct set for the chest but only partly counts for the triceps. They counted such indirect sets as half a set, a method that fit the data best, then asked how weekly set volume and training frequency relate to muscle growth and strength gains.","token_count":164},{"ordinal":1,"section":"Volume","header":"Source: Pelland et al. 2026, The resistance training dose response: meta-regressions exploring the effects of weekly volume and frequency on muscle hypertrophy and strength gains. Section: Volume.","body":"For both muscle size and strength, more weekly sets meant more gains, but with diminishing returns: each additional set added less than the one before. The flattening was much more pronounced for strength than for muscle size.","token_count":106},{"ordinal":2,"section":"Frequency","header":"Source: Pelland et al. 2026, The resistance training dose response: meta-regressions exploring the effects of weekly volume and frequency on muscle hypertrophy and strength gains. Section: Frequency.","body":"For muscle size, the data were compatible with training frequency having little or no effect once volume is accounted for. For strength, higher frequency was linked to greater gains, again with diminishing returns.","token_count":104},{"ordinal":3,"section":"Practical reading and limits","header":"Source: Pelland et al. 2026, The resistance training dose response: meta-regressions exploring the effects of weekly volume and frequency on muscle hypertrophy and strength gains. Section: Practical reading and limits.","body":"Weekly hard sets are the main lever; frequency is mostly a way to spread that volume so each session stays productive and manageable. Because returns diminish, going from a small amount of training to a moderate amount usually pays off far more than going from a high amount to a very high one. Participants were mostly young and male, so applying the numbers to older adults or women needs more caution.","token_count":156}]$lib$::jsonb
);

-- library-source: singer_2024_rest_intervals sha256:aaa1e4c28f2a0ff88f55a953f46c394fe7cc561105d437a129a2a562a72510dc
select private.library_replace_source(
$lib${"slug":"singer_2024_rest_intervals","title":"Give it a rest: a systematic review with Bayesian meta-analysis on the effect of inter-set rest interval duration on muscle hypertrophy","authors":["Singer A","Wolf M","Generoso L","Arias E","Delcastillo K","Echevarria E"],"year":2024,"doi":"10.3389/fspor.2024.1429789","url":"https://doi.org/10.3389/fspor.2024.1429789","licence":"CC-BY-4.0","region":["global"],"topics":["training","hypertrophy","rest","time-efficient"],"evidence_level":"systematic review and Bayesian meta-analysis (9 studies)","kind":"paper"}$lib$::jsonb,
$lib$[{"ordinal":0,"section":"What the review did","header":"Source: Singer et al. 2024, Give it a rest: a systematic review with Bayesian meta-analysis on the effect of inter-set rest interval duration on muscle hypertrophy. Section: What the review did.","body":"The authors looked for randomised trials in healthy adults that changed only the rest period between sets and measured muscle or lean mass. Nine studies qualified, and a Bayesian analysis estimated how rest length affects growth in the thigh, the arm and the whole body.","token_count":117},{"ordinal":1,"section":"Findings","header":"Source: Singer et al. 2024, Give it a rest: a systematic review with Bayesian meta-analysis on the effect of inter-set rest interval duration on muscle hypertrophy. Section: Findings.","body":"Muscle gains were similar across short, intermediate, long and very long rests, and results varied a lot between studies. When short rests were compared directly with longer ones, estimates leaned slightly towards longer rests for the arm and thigh, and were close to zero for whole-body measures. Whether people trained to failure did not change the picture.\n\nThe authors concluded that resting longer than about 60 seconds may give a small benefit, possibly because it protects the amount of work done in later sets, and that they found no clear difference beyond roughly 90 seconds. This fits evidence that lost work from short rests stops growing once rests pass about that length.","token_count":218},{"ordinal":2,"section":"Practical reading","header":"Source: Singer et al. 2024, Give it a rest: a systematic review with Bayesian meta-analysis on the effect of inter-set rest interval duration on muscle hypertrophy. Section: Practical reading.","body":"Rest about one to two minutes between most sets for muscle growth is well supported, and there is no need to wait three to five minutes unless heavy, strength-focused lifts call for it. For a time-pressed person, shortening rests to save time is a reasonable trade and costs little, as long as the load or repetitions do not collapse in later sets; when they do, a slightly longer rest is a better fix than stopping early. Results are about muscle size, not maximal strength.","token_count":167}]$lib$::jsonb
);

-- library-source: zourdos_2016_rir_scale sha256:05f85fecf32a0e59c34772ae946e4139b9c1b2218f75594a6e3797685a448b79
select private.library_replace_source(
$lib${"slug":"zourdos_2016_rir_scale","title":"Novel resistance training-specific rating of perceived exertion scale measuring repetitions in reserve","authors":["Zourdos MC","Klemp A","Dolan C","Quiles JM","Schau KA","Jo E"],"year":2016,"doi":"10.1519/JSC.0000000000001049","url":"https://doi.org/10.1519/JSC.0000000000001049","licence":"proprietary","region":["global"],"topics":["training","intensity","rir","progression"],"evidence_level":"experimental study (29 lifters)","kind":"paper"}$lib$::jsonb,
$lib$[{"ordinal":0,"section":"What the study did","header":"Source: Zourdos et al. 2016, Novel resistance training-specific rating of perceived exertion scale measuring repetitions in reserve. Section: What the study did.","body":"The researchers compared how 15 experienced squatters (about five years of training) and 14 novices (a few months) rated effort on a scale built around repetitions in reserve: the number of repetitions a lifter believes they could still do when the set ends. Each person did a one-repetition maximum squat, then single repetitions at 60, 75 and 90 percent of that maximum and a set of eight at 70 percent. Bar speed was measured and each lifter gave an effort rating that mapped onto repetitions in reserve (a rating of 10 meant none left, 9 meant one left, and so on).","token_count":183},{"ordinal":1,"section":"Findings","header":"Source: Zourdos et al. 2016, Novel resistance training-specific rating of perceived exertion scale measuring repetitions in reserve. Section: Findings.","body":"Bar speed and effort rating moved in opposite directions: the slower the bar, the higher the rating, and the relationship was strong in both groups. Experienced lifters were slower at the heaviest loads, rated their maximum lift as harder, and so seemed more efficient at high intensities; the two groups looked similar at lighter loads.","token_count":123},{"ordinal":2,"section":"Practical reading and limits","header":"Source: Zourdos et al. 2016, Novel resistance training-specific rating of perceived exertion scale measuring repetitions in reserve. Section: Practical reading and limits.","body":"Repetitions in reserve is a practical way to set and adjust effort from day to day, because the load that feels like two reps from failure changes with fatigue, sleep and stress. It is a self-rating, so it can be off. This study tested the squat only, in a small group, and checks how the scale lines up with bar speed rather than proving it improves results.","token_count":133}]$lib$::jsonb
);

-- library-source: robinson_2024_proximity_to_failure sha256:82bc40675a794c3eaaceaa04f92a27ff5ed0a0ce4d33a5d0270428abdec71c6d
select private.library_replace_source(
$lib${"slug":"robinson_2024_proximity_to_failure","title":"Exploring the dose-response relationship between estimated resistance training proximity to failure, strength gain, and muscle hypertrophy: a series of meta-regressions","authors":["Robinson ZP","Pelland JC","Remmert JF","Refalo MC","Jukic I","Steele J"],"year":2024,"doi":"10.1007/s40279-024-02069-2","url":"https://doi.org/10.1007/s40279-024-02069-2","licence":"proprietary","region":["global"],"topics":["training","hypertrophy","strength","intensity","rir"],"evidence_level":"series of meta-regressions","kind":"paper"}$lib$::jsonb,
$lib$[{"ordinal":0,"section":"What the analysis did","header":"Source: Robinson et al. 2024, Exploring the dose-response relationship between estimated resistance training proximity to failure, strength gain, and muscle hypertrophy: a series of meta-regressions. Section: What the analysis did.","body":"Earlier reviews compared training to failure against stopping short as a yes-or-no question. These authors instead treated closeness to failure as a sliding scale, measured as estimated repetitions in reserve, and fitted models after adjusting for load, how volume was matched, how long the study lasted and the lifters' experience. The reserve for each study was estimated from the training description, so it is approximate.","token_count":165},{"ordinal":1,"section":"Findings","header":"Source: Robinson et al. 2024, Exploring the dose-response relationship between estimated resistance training proximity to failure, strength gain, and muscle hypertrophy: a series of meta-regressions. Section: Findings.","body":"For strength, the link between repetitions in reserve and gains was negligible: strength rose similarly across a wide range of reserve.\n\nFor muscle size, the models agreed that growth increased as sets finished closer to failure. The authors note that the exact shape of this relationship is uncertain, given the way reserve had to be estimated.","token_count":141},{"ordinal":2,"section":"Practical reading and limits","header":"Source: Robinson et al. 2024, Exploring the dose-response relationship between estimated resistance training proximity to failure, strength gain, and muscle hypertrophy: a series of meta-regressions. Section: Practical reading and limits.","body":"Strength work does not need to be pushed to failure; leaving a few reps in reserve is fine and keeps technique and recovery in better shape. For muscle growth, sets taken fairly close to failure appear to be more productive, but how close is best is not settled and the benefit is a trade against more fatigue and joint stress. A large overview of reviews (ACSM 2026 in this library) found no consistent effect of training to failure, so Coach should describe the effect for growth as modest and uncertain, not as a rule.","token_count":190}]$lib$::jsonb
);

-- library-source: iversen_2021_time_efficient sha256:ef49576c579e44c48af5c7e09849025f7ca58ee1859d1e773d4b7ce09d3dd0d6
select private.library_replace_source(
$lib${"slug":"iversen_2021_time_efficient","title":"No time to lift? Designing time-efficient training programs for strength and hypertrophy: a narrative review","authors":["Iversen VM","Norum M","Schoenfeld BJ","Fimland MS"],"year":2021,"doi":"10.1007/s40279-021-01490-1","url":"https://doi.org/10.1007/s40279-021-01490-1","licence":"CC-BY-4.0","region":["global"],"topics":["training","time-efficient","volume","strength","hypertrophy","frequency"],"evidence_level":"narrative review","kind":"paper"}$lib$::jsonb,
$lib$[{"ordinal":0,"section":"Exercise choice","header":"Source: Iversen et al. 2021, No time to lift? Designing time-efficient training programs for strength and hypertrophy: a narrative review. Section: Exercise choice.","body":"When time is short, the authors recommend building sessions around multi-joint exercises done with both sides together and through a full movement (lifting and lowering). At minimum, cover one leg-pressing movement such as a squat, one upper-body pull such as a pull-up, and one upper-body push such as a bench press. Machines or free weights both work; pick what suits the person's goals, access and preferences.","token_count":145},{"ordinal":1,"section":"Sets, reps and frequency","header":"Source: Iversen et al. 2021, No time to lift? Designing time-efficient training programs for strength and hypertrophy: a narrative review. Section: Sets, reps and frequency.","body":"Weekly volume matters more than how it is split across days. The review recommends at least four weekly sets per muscle group, using a load that allows 6 to 15 repetitions to failure. If sets are taken to volitional failure, lighter loads of roughly 15 to 40 repetitions can also be used.","token_count":116},{"ordinal":2,"section":"Saving time inside a session","header":"Source: Iversen et al. 2021, No time to lift? Designing time-efficient training programs for strength and hypertrophy: a narrative review. Section: Saving time inside a session.","body":"Techniques such as supersets (pairing exercises back to back), drop sets and rest-pause sets can cut session time to about half while keeping the same volume. They are probably better at building muscle than at building maximal strength, and long-term evidence is still thin. The authors suggest limiting warm-ups to exercise-specific ones and doing stretching only when improving flexibility is a goal.","token_count":146},{"ordinal":3,"section":"Practical reading and limits","header":"Source: Iversen et al. 2021, No time to lift? Designing time-efficient training programs for strength and hypertrophy: a narrative review. Section: Practical reading and limits.","body":"A short, well-chosen programme can deliver much of the benefit, so a person short on time can still progress. Four sets a week is a floor for progress, not the best amount; the review is about efficiency, not maximum results. It is a narrative review, so its advice rests on the authors' reading of studies, not a single pooled calculation.","token_count":130}]$lib$::jsonb
);

-- library-source: schoenfeld_2016_frequency_hypertrophy sha256:cb5a97b69bc31fe1aa6068ffce74bdfbbeb496e09eb431b9aa087c6e68c0dbd3
select private.library_replace_source(
$lib${"slug":"schoenfeld_2016_frequency_hypertrophy","title":"Effects of resistance training frequency on measures of muscle hypertrophy: a systematic review and meta-analysis","authors":["Schoenfeld BJ","Ogborn D","Krieger JW"],"year":2016,"doi":"10.1007/s40279-016-0543-8","url":"https://doi.org/10.1007/s40279-016-0543-8","licence":"proprietary","region":["global"],"topics":["training","hypertrophy","frequency"],"evidence_level":"systematic review and meta-analysis (10 studies)","kind":"paper"}$lib$::jsonb,
$lib$[{"ordinal":0,"section":"What the review did","header":"Source: Schoenfeld et al. 2016, Effects of resistance training frequency on measures of muscle hypertrophy: a systematic review and meta-analysis. Section: What the review did.","body":"The authors pooled ten experimental trials in healthy adults that compared different weekly training frequencies and measured muscle size changes over at least four weeks. They looked at how often each muscle group was trained, not just how many gym days a week there were.","token_count":113},{"ordinal":1,"section":"Findings","header":"Source: Schoenfeld et al. 2016, Effects of resistance training frequency on measures of muscle hypertrophy: a systematic review and meta-analysis. Section: Findings.","body":"Higher frequency was linked to larger growth than lower frequency (effect sizes of about 0.49 against 0.30). In the studies that kept total weekly volume equal, training a muscle twice a week gave better results than once a week. Whether three times a week beats twice a week could not be answered from the data.","token_count":120},{"ordinal":2,"section":"Practical reading and limits","header":"Source: Schoenfeld et al. 2016, Effects of resistance training frequency on measures of muscle hypertrophy: a systematic review and meta-analysis. Section: Practical reading and limits.","body":"The practical lesson is to train major muscles at least twice a week, for example with an upper and lower split or full-body sessions, when the plan allows it. A once-a-week bodybuilding split is not wrong, but it asks more of each session. Only ten studies qualified and they covered one to three sessions a week, so the review cannot say how much frequency helps beyond three. A later analysis (Pelland 2026 in this library) found frequency matters little for growth once volume is counted.","token_count":170}]$lib$::jsonb
);

-- library-source: grgic_2018_frequency_strength sha256:e5b24f00546e4c8ef26dace7113e19cca433cbafe560cb9e292c04bb9c6bde45
select private.library_replace_source(
$lib${"slug":"grgic_2018_frequency_strength","title":"Effect of resistance training frequency on gains in muscular strength: a systematic review and meta-analysis","authors":["Grgic J","Schoenfeld BJ","Davies TB","Lazinica B","Krieger JW","Pedisic Z"],"year":2018,"doi":"10.1007/s40279-018-0872-x","url":"https://doi.org/10.1007/s40279-018-0872-x","licence":"proprietary","region":["global"],"topics":["training","strength","frequency","volume"],"evidence_level":"systematic review and meta-analysis (22 studies)","kind":"paper"}$lib$::jsonb,
$lib$[{"ordinal":0,"section":"What the review did","header":"Source: Grgic et al. 2018, Effect of resistance training frequency on gains in muscular strength: a systematic review and meta-analysis. Section: What the review did.","body":"The authors pooled 22 studies that compared strength gains at different weekly training frequencies. They grouped frequency as 1, 2, 3 or 4 or more sessions per muscle per week and checked many moderators, including total volume, age, sex and whether sets were taken to failure.","token_count":112},{"ordinal":1,"section":"Findings","header":"Source: Grgic et al. 2018, Effect of resistance training frequency on gains in muscular strength: a systematic review and meta-analysis. Section: Findings.","body":"Overall, higher frequency went with larger strength gains, with effect sizes rising from 0.74 at once a week to 0.82, 0.93 and 1.08 at two, three and four or more times a week. But when studies matched total weekly volume, frequency made no significant difference. The effect looked stronger for multi-joint upper-body lifts and in women, and younger people responded better to higher frequency than older adults did.","token_count":144},{"ordinal":2,"section":"Practical reading and limits","header":"Source: Grgic et al. 2018, Effect of resistance training frequency on gains in muscular strength: a systematic review and meta-analysis. Section: Practical reading and limits.","body":"Training more days is mainly a way to fit in more volume. A person who can only train twice a week can still gain strength if the weekly volume is adequate, and a person who trains more often should not expect extra benefit without extra work. Most studies used untrained participants, so evidence for experienced lifters is thinner.","token_count":128}]$lib$::jsonb
);

-- library-source: bell_2023_deloading sha256:913ffb603c724334fe47f5c6dfb39e5569b3a72aa47d49717d8a3c4e5f3e4912
select private.library_replace_source(
$lib${"slug":"bell_2023_deloading","title":"Integrating deloading into strength and physique sports training programmes: an international Delphi consensus approach","authors":["Bell L","Strafford BW","Coleman M","Androulakis Korakakis P","Nolan D"],"year":2023,"doi":"10.1186/s40798-023-00633-0","url":"https://doi.org/10.1186/s40798-023-00633-0","licence":"CC-BY-4.0","region":["global"],"topics":["training","deload","recovery","progression"],"evidence_level":"expert consensus (Delphi, 34 coaches)","kind":"paper"}$lib$::jsonb,
$lib$[{"ordinal":0,"section":"What the study was","header":"Source: Bell et al. 2023, Integrating deloading into strength and physique sports training programmes: an international Delphi consensus approach. Section: What the study was.","body":"Deloading is a common habit in strength and bodybuilding training but has barely been tested in trials. The authors ran a three-round Delphi process with expert coaches (34 in round one, 21 by round three) to build a consensus on how deloads should be designed, using open questions first and then rating 138 statements on a four-point scale.","token_count":130},{"ordinal":1,"section":"The consensus definition","header":"Source: Bell et al. 2023, Integrating deloading into strength and physique sports training programmes: an international Delphi consensus approach. Section: The consensus definition.","body":"The panel agreed on this idea: a deload is a period of reduced training stress meant to ease physical and mental fatigue, help recovery and leave the person better prepared for the next block of training.","token_count":97},{"ordinal":2,"section":"Practical reading and limits","header":"Source: Bell et al. 2023, Integrating deloading into strength and physique sports training programmes: an international Delphi consensus approach. Section: Practical reading and limits.","body":"A deload is a planned, temporary reduction in load, volume or effort, used to manage fatigue instead of stopping training. The evidence is expert opinion, not a controlled trial, so Coach should say that deloads are a widely used coaching practice with consensus on their purpose, not a proven requirement. When a reduction applies is a decision for the plan's rules and the athlete's own data, not for the model.","token_count":150}]$lib$::jsonb
);

-- library-source: lopez_2021_load_network sha256:77572bbad892dafea12b6381a325677a7544783744a6ba7bb6a2ca072bba8696
select private.library_replace_source(
$lib${"slug":"lopez_2021_load_network","title":"Resistance training load effects on muscle hypertrophy and strength gain: systematic review and network meta-analysis","authors":["Lopez P","Radaelli R","Taaffe DR","Newton RU","Galvão DA","Trajano GS"],"year":2021,"doi":"10.1249/MSS.0000000000002585","url":"https://doi.org/10.1249/MSS.0000000000002585","licence":"CC-BY-NC-ND-4.0","region":["global"],"topics":["training","hypertrophy","strength","intensity","joint-friendly"],"evidence_level":"systematic review and network meta-analysis (28 studies)","kind":"paper"}$lib$::jsonb,
$lib$[{"ordinal":0,"section":"What the review did","header":"Source: Lopez et al. 2021, Resistance training load effects on muscle hypertrophy and strength gain: systematic review and network meta-analysis. Section: What the review did.","body":"The authors compared low loads (more than 15 repetitions to failure), moderate loads (9 to 15) and high loads (8 or fewer) in 28 studies with 747 healthy adults. Every set in the included studies was taken to failure, which makes the loads comparable in effort. A network meta-analysis compared all three at once.","token_count":123},{"ordinal":1,"section":"Findings","header":"Source: Lopez et al. 2021, Resistance training load effects on muscle hypertrophy and strength gain: systematic review and network meta-analysis. Section: Findings.","body":"Muscle growth did not differ between low, moderate and high loads. Strength improved more with high and moderate loads than with low loads. Untrained people gained more muscle, and people with some training experience gained more when they did more sessions.","token_count":106},{"ordinal":2,"section":"Practical reading and limits","header":"Source: Lopez et al. 2021, Resistance training load effects on muscle hypertrophy and strength gain: systematic review and network meta-analysis. Section: Practical reading and limits.","body":"If a joint, tendon or injury history makes heavy lifting uncomfortable, lighter loads taken close to failure can still build muscle, though maximal strength will improve less than with heavier loads. Taking light sets to failure is hard work and tiring, so the trade is comfort for joints against effort for the lifter. All studies were in healthy adults; this is not guidance for rehabilitating an injury.","token_count":148}]$lib$::jsonb
);

-- library-source: schumann_2022_concurrent_training sha256:8a9262401c85e92c32768a30c365fd3f78e73142a2b5a422092f185503a482ca
select private.library_replace_source(
$lib${"slug":"schumann_2022_concurrent_training","title":"Compatibility of concurrent aerobic and strength training for skeletal muscle size and function: an updated systematic review and meta-analysis","authors":["Schumann M","Feuerbacher JF","Sünkeler M","Freitag N","Rønnestad BR","Doma K"],"year":2022,"doi":"10.1007/s40279-021-01587-7","url":"https://doi.org/10.1007/s40279-021-01587-7","licence":"CC-BY-4.0","region":["global"],"topics":["training","cardio","strength","hypertrophy","concurrent-training"],"evidence_level":"systematic review and meta-analysis (43 studies)","kind":"paper"}$lib$::jsonb,
$lib$[{"ordinal":0,"section":"What the review did","header":"Source: Schumann et al. 2022, Compatibility of concurrent aerobic and strength training for skeletal muscle size and function: an updated systematic review and meta-analysis. Section: What the review did.","body":"The authors pooled 43 supervised trials in healthy adults that compared strength training plus aerobic training against the same strength training alone, for at least four weeks. They looked at maximal strength, explosive strength and muscle size, and checked effects of exercise order, cycling versus running, weekly frequency, age and training status.","token_count":140},{"ordinal":1,"section":"Findings","header":"Source: Schumann et al. 2022, Compatibility of concurrent aerobic and strength training for skeletal muscle size and function: an updated systematic review and meta-analysis. Section: Findings.","body":"Adding aerobic training did not hurt muscle size or maximal strength. Explosive strength (how fast force is produced) was somewhat lower with concurrent training, especially when the cardio and the lifting were in the same session instead of separated by at least three hours. Running and cycling, frequency and age did not clearly change the result.","token_count":136},{"ordinal":2,"section":"Practical reading","header":"Source: Schumann et al. 2022, Compatibility of concurrent aerobic and strength training for skeletal muscle size and function: an updated systematic review and meta-analysis. Section: Practical reading.","body":"For most people, doing both cardio and lifting is fine for building muscle and strength. When explosive power matters, keeping them in separate sessions helps. Studies were mostly short to medium term, so very high cardio volumes alongside heavy lifting remain a case for more care.","token_count":122}]$lib$::jsonb
);

-- library-source: schoenfeld_2020_range_of_motion sha256:201fc53f048cdbeb01bd450e1cd53241bd052cdf5f1ab625aedabb8aeed67167
select private.library_replace_source(
$lib${"slug":"schoenfeld_2020_range_of_motion","title":"Effects of range of motion on muscle development during resistance training interventions: a systematic review","authors":["Schoenfeld BJ","Grgic J"],"year":2020,"doi":"10.1177/2050312120901559","url":"https://doi.org/10.1177/2050312120901559","licence":"CC-BY-NC-4.0","region":["global"],"topics":["training","hypertrophy","joint-friendly","exercise-selection"],"evidence_level":"systematic review (6 studies)","kind":"paper"}$lib$::jsonb,
$lib$[{"ordinal":0,"section":"What the review did","header":"Source: Schoenfeld and Grgic 2020, Effects of range of motion on muscle development during resistance training interventions: a systematic review. Section: What the review did.","body":"The authors reviewed six controlled studies (135 participants, mostly men) that compared training through a full range of motion with a partial range over several weeks and measured changes in muscle size. Four studies trained the legs and two trained the arms. The studies were of high methodological quality, but there are few of them.","token_count":129},{"ordinal":1,"section":"Findings","header":"Source: Schoenfeld and Grgic 2020, Effects of range of motion on muscle development during resistance training interventions: a systematic review. Section: Findings.","body":"For the lower body, a full range of motion built more muscle than a partial range. For the upper body, results were limited and conflicting, so no firm conclusion was possible. No study had looked at the trunk muscles. There were hints that the best range may depend on the muscle, which still needs testing.","token_count":119},{"ordinal":2,"section":"Practical reading and limits","header":"Source: Schoenfeld and Grgic 2020, Effects of range of motion on muscle development during resistance training interventions: a systematic review. Section: Practical reading and limits.","body":"Taking the full range that the person can control comfortably is a good default for the legs. If a position at the end of the range bothers a joint, using a slightly shorter range that stays pain-free is a reasonable adjustment, particularly for the arms, where the evidence does not favour either choice. This does not tell anyone how to train around an injury; persistent pain is a reason to stop and see a professional. The evidence base is small and mostly in healthy young men.","token_count":167}]$lib$::jsonb
);

-- library-source: lauersen_2014_injury_prevention sha256:40b6f04f74a61a484fe93bf3dccd2b7b43586436ecc943b0e5dde2aeee70c47d
select private.library_replace_source(
$lib${"slug":"lauersen_2014_injury_prevention","title":"The effectiveness of exercise interventions to prevent sports injuries: a systematic review and meta-analysis of randomised controlled trials","authors":["Lauersen JB","Bertelsen DM","Andersen LB"],"year":2014,"doi":"10.1136/bjsports-2013-092538","url":"https://doi.org/10.1136/bjsports-2013-092538","licence":"proprietary","region":["global"],"topics":["injury-prevention","joint-friendly","strength","training"],"evidence_level":"systematic review and meta-analysis (25 trials)","kind":"paper"}$lib$::jsonb,
$lib$[{"ordinal":0,"section":"What the review did","header":"Source: Lauersen et al. 2014, The effectiveness of exercise interventions to prevent sports injuries: a systematic review and meta-analysis of randomised controlled trials. Section: What the review did.","body":"The authors pooled 25 randomised trials with 26,610 participants and 3,464 injuries to see whether exercise programmes prevent sports injuries. They split the programmes into strength training, stretching, balance and coordination (proprioception) training and combinations, and counted sudden injuries and overuse injuries separately.","token_count":135},{"ordinal":1,"section":"Findings","header":"Source: Lauersen et al. 2014, The effectiveness of exercise interventions to prevent sports injuries: a systematic review and meta-analysis of randomised controlled trials. Section: Findings.","body":"Strength training cut sports injuries to less than a third of the control rate (risk ratio about 0.32). Balance training roughly halved injuries (about 0.55), and programmes that combined several exercise types lowered them by about a third (about 0.66). Stretching alone showed no clear benefit (about 0.96). Overall, exercise programmes reduced both sudden injuries and overuse injuries, with overuse injuries almost halved.","token_count":155},{"ordinal":2,"section":"Practical reading and limits","header":"Source: Lauersen et al. 2014, The effectiveness of exercise interventions to prevent sports injuries: a systematic review and meta-analysis of randomised controlled trials. Section: Practical reading and limits.","body":"Regular strength work, and for some people balance work, is a sensible part of staying injury-free, while stretching on its own is not a good bet for preventing injuries. Most trials involved athletes in organised sport and tested injury prevention in healthy people. The review does not cover treating an existing injury, and Coach should not use it to promise that a person will not get hurt.","token_count":152}]$lib$::jsonb
);

-- library-source: gabbett_2016_training_load sha256:2357ced55d088ccdadc8009495bc8841b7539cdbfefd692af04fa64b2febf417
select private.library_replace_source(
$lib${"slug":"gabbett_2016_training_load","title":"The training-injury prevention paradox: should athletes be training smarter and harder?","authors":["Gabbett TJ"],"year":2016,"doi":"10.1136/bjsports-2015-095788","url":"https://doi.org/10.1136/bjsports-2015-095788","licence":"CC-BY-NC-4.0","region":["global"],"topics":["injury-prevention","joint-friendly","training","progression","load-management"],"evidence_level":"narrative review and model","kind":"paper"}$lib$::jsonb,
$lib$[{"ordinal":0,"section":"The idea","header":"Source: Gabbett 2016, The training-injury prevention paradox: should athletes be training smarter and harder?. Section: The idea.","body":"It is common to assume that more training means more injuries. This paper argues the picture is more subtle. People who are used to high training loads tend to have fewer injuries than people who train less, because regular hard training builds the physical qualities that protect the body. The author calls this the training-injury prevention paradox.","token_count":121},{"ordinal":1,"section":"What causes the damage","header":"Source: Gabbett 2016, The training-injury prevention paradox: should athletes be training smarter and harder?. Section: What causes the damage.","body":"The central claim is that non-contact injuries are less likely to be caused by training itself than by a poorly planned programme. Large and fast jumps in training load are likely to be behind many soft-tissue injuries, and under-training can raise risk too, because the body is not prepared for what is asked of it.","token_count":115},{"ordinal":2,"section":"Monitoring load","header":"Source: Gabbett 2016, The training-injury prevention paradox: should athletes be training smarter and harder?. Section: Monitoring load.","body":"To manage this, the paper recommends tracking both recent (acute) load and longer-term (chronic) load, using internal measures such as effort and external measures such as the work done. It describes the acute-to-chronic workload ratio, which compares a recent week with the average of recent weeks, as a useful way to spot sudden spikes.","token_count":119},{"ordinal":3,"section":"Practical reading and limits","header":"Source: Gabbett 2016, The training-injury prevention paradox: should athletes be training smarter and harder?. Section: Practical reading and limits.","body":"For coaching, the message is to build load gradually, avoid sharp jumps in volume or intensity, and not to fear training hard once the body has been prepared. The paper is a model drawn mostly from team-sport research, so Coach should treat the acute-to-chronic ratio as one useful heuristic rather than a precise injury predictor.","token_count":121}]$lib$::jsonb
);

-- library-source: jager_2017_protein sha256:decbe87116df3140d3d623caf066876baacd44c9862c6e805f12bf82b84751d1
select private.library_replace_source(
$lib${"slug":"jager_2017_protein","title":"International Society of Sports Nutrition position stand: protein and exercise","authors":["Jäger R","Kerksick CM","Campbell BI","Cribb PJ","Wells SD","Skwiat TM"],"year":2017,"doi":"10.1186/s12970-017-0177-8","url":"https://doi.org/10.1186/s12970-017-0177-8","licence":"CC-BY-4.0","region":["global"],"topics":["nutrition","protein","hypertrophy","body-composition","timing"],"evidence_level":"position stand","kind":"position_stand"}$lib$::jsonb,
$lib$[{"ordinal":0,"section":"How much protein per day","header":"Source: Jäger et al. 2017 (ISSN), International Society of Sports Nutrition position stand: protein and exercise. Section: How much protein per day.","body":"For most people who exercise, a daily intake of about 1.4 to 2.0 grams of protein per kilogram of body weight is enough to build or keep muscle. That range sits within the normal healthy-diet guidance for protein.\n\nHigher intakes of about 2.3 to 3.1 grams per kilogram may help hold on to lean mass in resistance-trained people when they are eating below maintenance. There is newer, less settled evidence that intakes above 3 grams per kilogram might even help fat loss in trained people.","token_count":160},{"ordinal":1,"section":"Dose per meal and spacing","header":"Source: Jäger et al. 2017 (ISSN), International Society of Sports Nutrition position stand: protein and exercise. Section: Dose per meal and spacing.","body":"Advice on the best amount per serving is mixed and depends on age and recent training. As a general guide the position stand gives about 0.25 grams of high-quality protein per kilogram of body weight, or roughly 20 to 40 grams, spread fairly evenly through the day, around every three to four hours. A serving should contain a full set of the essential amino acids, with enough of the amino acid leucine.","token_count":139},{"ordinal":2,"section":"Timing and food choice","header":"Source: Jäger et al. 2017 (ISSN), International Society of Sports Nutrition position stand: protein and exercise. Section: Timing and food choice.","body":"Eating protein before or after resistance training both help, and the muscle-building effect of a session lasts at least a day, so the exact timing is mostly a matter of what the person tolerates. Whole foods can supply all the protein needed; supplements are a convenient way to hit the numbers, especially with high training volumes. Casein (a slow-digesting milk protein) of 30 to 40 grams before sleep raises overnight muscle protein building without blunting fat burning. Endurance athletes should not neglect carbohydrate, and adding protein may help recovery.","token_count":179},{"ordinal":3,"section":"Practical reading and limits","header":"Source: Jäger et al. 2017 (ISSN), International Society of Sports Nutrition position stand: protein and exercise. Section: Practical reading and limits.","body":"These are general figures for healthy adults. They do not replace advice from a clinician or dietitian for kidney disease, pregnancy or other medical conditions, which Tracend does not cover. Protein targets work best alongside enough total energy and a sensible training plan.","token_count":108}]$lib$::jsonb
);

-- library-source: kerksick_2017_nutrient_timing sha256:264a5e1e70c8040ff597d835025a75e9cfebcd6504977b7c08d71d391b103c0e
select private.library_replace_source(
$lib${"slug":"kerksick_2017_nutrient_timing","title":"International Society of Sports Nutrition position stand: nutrient timing","authors":["Kerksick CM","Arent S","Schoenfeld BJ","Stout JR","Campbell B","Wilborn CD"],"year":2017,"doi":"10.1186/s12970-017-0189-4","url":"https://doi.org/10.1186/s12970-017-0189-4","licence":"CC-BY-4.0","region":["global"],"topics":["nutrition","timing","protein","carbohydrate","recovery"],"evidence_level":"position stand","kind":"position_stand"}$lib$::jsonb,
$lib$[{"ordinal":0,"section":"What matters first","header":"Source: Kerksick et al. 2017 (ISSN), International Society of Sports Nutrition position stand: nutrient timing. Section: What matters first.","body":"Of everything about when to eat, the position stand puts the total daily protein intake first, ideally spread evenly with feedings about every three hours. A dose of roughly 20 to 40 grams of protein, or about 10 grams of essential amino acids, is enough to maximally stimulate muscle protein building in a single sitting. About 0.25 to 0.40 grams per kilogram of body weight every three to four hours was linked with the best muscle protein building and body composition results.","token_count":156},{"ordinal":1,"section":"Around the workout","header":"Source: Kerksick et al. 2017 (ISSN), International Society of Sports Nutrition position stand: nutrient timing. Section: Around the workout.","body":"Eating protein, or carbohydrate with protein, before or after a session can support strength and body composition. Protein within about two hours after training stimulates muscle protein building strongly, although the size and timing of the meal eaten before training affects how much that post-workout feeding matters. Taking in carbohydrate and protein during resistance training can also help muscle glycogen and limit muscle damage.","token_count":145},{"ordinal":2,"section":"For heavy or long training","header":"Source: Kerksick et al. 2017 (ISSN), International Society of Sports Nutrition position stand: nutrient timing. Section: For heavy or long training.","body":"People training very hard or for a long time need more attention to carbohydrate. Muscle glycogen stores are best filled with a high-carbohydrate diet of 8 to 12 grams per kilogram per day, and when a second hard session comes soon after the first, refuelling quickly with carbohydrate (and protein) matters. For efforts above about an hour at high intensity the stand suggests roughly 30 to 60 grams of carbohydrate per hour. Casein protein of about 30 to 40 grams before sleep can raise overnight muscle protein building.","token_count":168},{"ordinal":3,"section":"Practical reading and limits","header":"Source: Kerksick et al. 2017 (ISSN), International Society of Sports Nutrition position stand: nutrient timing. Section: Practical reading and limits.","body":"For most recreational lifters, hitting daily protein and total energy needs matters far more than squeezing food into a narrow window. Timing becomes more useful for people training twice a day, doing long endurance work or trying to recover quickly. Meal frequency alone changes weight loss and body composition little. The numbers are general guidance for healthy adults, with the strongest evidence in trained people.","token_count":143}]$lib$::jsonb
);

-- library-source: schoenfeld_2018_protein_per_meal sha256:5e0a286a9661284ee7db96e3f2830c37c75f82ed08a4b2762c8658f6e5e8d94c
select private.library_replace_source(
$lib${"slug":"schoenfeld_2018_protein_per_meal","title":"How much protein can the body use in a single meal for muscle-building? Implications for daily protein distribution","authors":["Schoenfeld BJ","Aragon AA"],"year":2018,"doi":"10.1186/s12970-018-0215-1","url":"https://doi.org/10.1186/s12970-018-0215-1","licence":"CC-BY-4.0","region":["global"],"topics":["nutrition","protein","timing","hypertrophy"],"evidence_level":"narrative review","kind":"paper"}$lib$::jsonb,
$lib$[{"ordinal":0,"section":"The myth being tested","header":"Source: Schoenfeld and Aragon 2018, How much protein can the body use in a single meal for muscle-building? Implications for daily protein distribution. Section: The myth being tested.","body":"Some people believe muscle protein building is maxed out at about 20 to 25 grams of protein in a meal and that anything beyond that is wasted. The authors point out that this idea comes from studies of quickly digested protein taken alone, and that protein eaten in a mixed meal or from slower sources is absorbed more gradually and so is likely used better.","token_count":136},{"ordinal":1,"section":"What the evidence shows","header":"Source: Schoenfeld and Aragon 2018, How much protein can the body use in a single meal for muscle-building? Implications for daily protein distribution. Section: What the evidence shows.","body":"Larger servings (above 20 grams) do cause more of the amino acids to be burned for energy, but not all of the extra is lost; some of it goes into tissue building. The authors concluded that to maximise muscle building, a person should aim for about 0.4 grams per kilogram of body weight per meal across at least four meals, enough to reach a total of at least 1.6 grams per kilogram per day. If someone eats the upper daily intake from the literature, 2.2 grams per kilogram, over the same four meals, that is at most about 0.55 grams per kilogram per meal.","token_count":186},{"ordinal":2,"section":"Practical reading and limits","header":"Source: Schoenfeld and Aragon 2018, How much protein can the body use in a single meal for muscle-building? Implications for daily protein distribution. Section: Practical reading and limits.","body":"An 80 kg person aiming for the lower number would eat roughly 32 grams of protein at each of four meals. There is no need to panic about a meal with a bit more or less protein, but spreading intake sensibly through the day is better than saving it all for one sitting. It is a narrative review that sets a target by reasoning from the evidence, so it is not a rule that applies to every person.","token_count":147}]$lib$::jsonb
);

-- library-source: morton_2018_protein_supplementation sha256:c84036e859f7fac4d1e45e3df0d7e5e8b0a9c59f4779a4d1346b7b4f6012f856
select private.library_replace_source(
$lib${"slug":"morton_2018_protein_supplementation","title":"A systematic review, meta-analysis and meta-regression of the effect of protein supplementation on resistance training-induced gains in muscle mass and strength in healthy adults","authors":["Morton RW","Murphy KT","McKellar SR","Schoenfeld BJ","Henselmans M","Helms E"],"year":2018,"doi":"10.1136/bjsports-2017-097608","url":"https://doi.org/10.1136/bjsports-2017-097608","licence":"CC-BY-NC-4.0","region":["global"],"topics":["nutrition","protein","hypertrophy","strength","supplements"],"evidence_level":"systematic review and meta-analysis (49 studies)","kind":"paper"}$lib$::jsonb,
$lib$[{"ordinal":0,"section":"What the review did","header":"Source: Morton et al. 2018, A systematic review, meta-analysis and meta-regression of the effect of protein supplementation on resistance training-induced gains in muscle mass and strength in healthy adults. Section: What the review did.","body":"The authors pooled 49 randomised trials with 1,863 participants who followed a resistance training programme for at least six weeks and were given extra protein or not. They checked effects on strength and muscle size, and used a break-point analysis to find where extra protein stopped helping.","token_count":134},{"ordinal":1,"section":"Findings","header":"Source: Morton et al. 2018, A systematic review, meta-analysis and meta-regression of the effect of protein supplementation on resistance training-induced gains in muscle mass and strength in healthy adults. Section: Findings.","body":"Extra protein produced a significant, though modest, improvement in strength and in muscle size over prolonged training. The benefit was smaller with increasing age and larger in people who were already experienced lifters. Once total protein intake passed about 1.6 grams per kilogram of body weight per day, more protein no longer added gains in fat-free mass.","token_count":148},{"ordinal":2,"section":"Practical reading and limits","header":"Source: Morton et al. 2018, A systematic review, meta-analysis and meta-regression of the effect of protein supplementation on resistance training-induced gains in muscle mass and strength in healthy adults. Section: Practical reading and limits.","body":"Around 1.6 grams per kilogram per day covers most of the muscle-building benefit of protein for healthy adults who lift; going far above it is not needed for growth (although other position stands note that higher intakes may help in a calorie deficit). Protein powder is a convenience, not a necessity, since the gain comes from the total daily amount. The 1.6 figure is where the average benefit levelled off, with some individual differences, so it is a guide rather than a hard limit.","token_count":184}]$lib$::jsonb
);

-- library-source: aragon_2017_diets_body_composition sha256:08a3ebe76e038b6dba927a97515745de68f80b7bea874b05882f052b1f02222f
select private.library_replace_source(
$lib${"slug":"aragon_2017_diets_body_composition","title":"International society of sports nutrition position stand: diets and body composition","authors":["Aragon AA","Schoenfeld BJ","Wildman R","Kleiner S","VanDusseldorp T","Taylor L"],"year":2017,"doi":"10.1186/s12970-017-0174-y","url":"https://doi.org/10.1186/s12970-017-0174-y","licence":"CC-BY-4.0","region":["global"],"topics":["nutrition","energy-balance","body-composition","protein","fat-loss"],"evidence_level":"position stand","kind":"position_stand"}$lib$::jsonb,
$lib$[{"ordinal":0,"section":"Fat loss and muscle gain run on energy balance","header":"Source: Aragon et al. 2017 (ISSN), International society of sports nutrition position stand: diets and body composition. Section: Fat loss and muscle gain run on energy balance.","body":"Diets aimed at fat loss work through a sustained calorie deficit. The more body fat a person starts with, the more aggressively the deficit can be set; leaner people hold on to more lean mass with slower rates of weight loss. Diets aimed at gaining lean mass run on a sustained surplus that supports the training load, and the size of the surplus and the person's training status affect what is gained.","token_count":145},{"ordinal":1,"section":"Diet style matters less than people think","header":"Source: Aragon et al. 2017 (ISSN), International society of sports nutrition position stand: diets and body composition. Section: Diet style matters less than people think.","body":"A wide range of eating styles, from low-fat to low-carbohydrate and ketogenic, can improve body composition about equally well. Intermittent calorie restriction (such as alternate patterns) showed no significant advantage over restricting calories every day. Long-term success depends heavily on whether the person can stick with the approach, and on factors such as the body's adaptive reduction in energy use during dieting.","token_count":150},{"ordinal":2,"section":"Protein","header":"Source: Aragon et al. 2017 (ISSN), International society of sports nutrition position stand: diets and body composition. Section: Protein.","body":"Protein above the usual guidance for athletes may improve body composition. In lean, resistance-trained people eating below maintenance, intakes of about 2.3 to 3.1 grams per kilogram of fat-free mass may be needed to maximise muscle retention. Very high intakes above 3 grams per kilogram may add satiety and lean-mass protection, but the evidence is early.","token_count":125},{"ordinal":3,"section":"Practical reading and limits","header":"Source: Aragon et al. 2017 (ISSN), International society of sports nutrition position stand: diets and body composition. Section: Practical reading and limits.","body":"Choose a diet the person can maintain, set calories for the goal, keep protein high, and expect slower loss to protect lean mass in lean people. The position stand notes little research on women and older adults, and that methods for measuring body composition each have limits, so single measurements deserve some caution. It is not guidance for eating disorders or medical diets, which Tracend does not cover.","token_count":143}]$lib$::jsonb
);

-- library-source: helms_2014_contest_prep sha256:07b090a15914f019dddb5f5b5139b90f40dc6378d6bec6b789ca1e03e9b087e3
select private.library_replace_source(
$lib${"slug":"helms_2014_contest_prep","title":"Evidence-based recommendations for natural bodybuilding contest preparation: nutrition and supplementation","authors":["Helms ER","Aragon AA","Fitschen PJ"],"year":2014,"doi":"10.1186/1550-2783-11-20","url":"https://doi.org/10.1186/1550-2783-11-20","licence":"CC-BY-2.0","region":["global"],"topics":["nutrition","energy-balance","body-composition","protein","fat-loss","supplements"],"evidence_level":"narrative review","kind":"paper"}$lib$::jsonb,
$lib$[{"ordinal":0,"section":"Rate of loss and macronutrients","header":"Source: Helms et al. 2014, Evidence-based recommendations for natural bodybuilding contest preparation: nutrition and supplementation. Section: Rate of loss and macronutrients.","body":"This review was written for natural bodybuilders cutting down for a contest, which is an extreme case of getting lean, so its figures suit lean, trained people with a clear fat-loss goal. It recommends setting calories so body weight falls by about 0.5 to 1 percent per week to keep as much muscle as possible. Within that, most people will do best on 2.3 to 3.1 grams of protein per kilogram of lean body mass per day, 15 to 30 percent of calories from fat, and the rest from carbohydrate.","token_count":167},{"ordinal":1,"section":"Meal pattern and supplements","header":"Source: Helms et al. 2014, Evidence-based recommendations for natural bodybuilding contest preparation: nutrition and supplementation. Section: Meal pattern and supplements.","body":"Eating three to six meals a day with a protein-containing meal (0.4 to 0.5 grams per kilogram of body weight) before and after resistance training probably captures any benefit of timing. But changes to meal timing and frequency made little difference to fat loss or lean mass retention. Of the popular supplements, creatine monohydrate, caffeine and beta-alanine looked helpful, while others did not or need more study.","token_count":149},{"ordinal":2,"section":"Warnings","header":"Source: Helms et al. 2014, Evidence-based recommendations for natural bodybuilding contest preparation: nutrition and supplementation. Section: Warnings.","body":"The authors warn that deliberately dehydrating and manipulating electrolytes in the last days before a show can be dangerous and may not even improve appearance. They also stress that sports focused on appearance carry a raised risk of eating and body-image disorders, so athletes should be able to reach appropriate mental health professionals.","token_count":125},{"ordinal":3,"section":"Practical reading and limits","header":"Source: Helms et al. 2014, Evidence-based recommendations for natural bodybuilding contest preparation: nutrition and supplementation. Section: Practical reading and limits.","body":"The rate of 0.5 to 1 percent of body weight per week is a useful ceiling for most people trying to lose fat while training, with the slower end suiting leaner people. These recommendations come from a review of the literature on a specialised group, so Tracend should not push people towards contest-style leanness. Anyone with a history of disordered eating is outside the product's scope.","token_count":141}]$lib$::jsonb
);

-- library-source: kreider_2017_creatine sha256:456a1e6d840cf461b90f74702160d419a7675679ffe9e7ca5f3a59e9cbccc0af
select private.library_replace_source(
$lib${"slug":"kreider_2017_creatine","title":"International Society of Sports Nutrition position stand: safety and efficacy of creatine supplementation in exercise, sport, and medicine","authors":["Kreider RB","Kalman DS","Antonio J","Ziegenfuss TN","Wildman R","Collins R"],"year":2017,"doi":"10.1186/s12970-017-0173-z","url":"https://doi.org/10.1186/s12970-017-0173-z","licence":"CC-BY-4.0","region":["global"],"topics":["nutrition","creatine","supplements","strength","safety"],"evidence_level":"position stand","kind":"position_stand"}$lib$::jsonb,
$lib$[{"ordinal":0,"section":"What creatine does","header":"Source: Kreider et al. 2017 (ISSN), International Society of Sports Nutrition position stand: safety and efficacy of creatine supplementation in exercise, sport, and medicine. Section: What creatine does.","body":"Taking creatine raises the creatine and phosphocreatine stored in muscle, which supports high-intensity effort and so helps people do more quality work in training and adapt better. The position stand also reports possible help with recovery after exercise, tolerating heavy training loads and some injury-related outcomes.","token_count":132},{"ordinal":1,"section":"How much to take","header":"Source: Kreider et al. 2017 (ISSN), International Society of Sports Nutrition position stand: safety and efficacy of creatine supplementation in exercise, sport, and medicine. Section: How much to take.","body":"The quickest way to fill muscle stores is a loading phase of roughly 0.3 grams per kilogram of body weight per day (for example 5 grams four times a day) for 5 to 7 days, then 3 to 5 grams a day to maintain. Taking 3 to 5 grams a day without loading also raises stores, but more slowly, over about three to four weeks. Larger people may need up to 5 to 10 grams a day to maintain stores.","token_count":148},{"ordinal":2,"section":"Safety","header":"Source: Kreider et al. 2017 (ISSN), International Society of Sports Nutrition position stand: safety and efficacy of creatine supplementation in exercise, sport, and medicine. Section: Safety.","body":"Short- and long-term use, up to 30 grams a day for five years in the studies reviewed, was safe and well tolerated in healthy people, and in several patient groups from infants to older adults. Creatine is often taken with a meal or with carbohydrate and protein.","token_count":114},{"ordinal":3,"section":"Practical reading and limits","header":"Source: Kreider et al. 2017 (ISSN), International Society of Sports Nutrition position stand: safety and efficacy of creatine supplementation in exercise, sport, and medicine. Section: Practical reading and limits.","body":"Creatine monohydrate at 3 to 5 grams a day is a low-cost, well-studied option for people who lift, and loading is optional. It is a supplement, not a requirement, and is not a substitute for training, sleep and food. Anyone with a medical condition, especially kidney problems, or who takes medication should check with a clinician first, since this position stand is aimed at healthy people. Coach should not push supplements and should be clear that results vary between individuals.","token_count":175}]$lib$::jsonb
);

-- library-source: guest_2021_caffeine sha256:9aef4e480cb829cc72e348d33929924630fd18a105c3403829a7c7c74297db1b
select private.library_replace_source(
$lib${"slug":"guest_2021_caffeine","title":"International society of sports nutrition position stand: caffeine and exercise performance","authors":["Guest NS","VanDusseldorp TA","Nelson MT","Grgic J","Schoenfeld BJ","Jenkins NDM"],"year":2021,"doi":"10.1186/s12970-020-00383-4","url":"https://doi.org/10.1186/s12970-020-00383-4","licence":"CC-BY-4.0","region":["global"],"topics":["nutrition","caffeine","supplements","performance","sleep"],"evidence_level":"position stand","kind":"position_stand"}$lib$::jsonb,
$lib$[{"ordinal":0,"section":"What caffeine does for training","header":"Source: Guest et al. 2021 (ISSN), International society of sports nutrition position stand: caffeine and exercise performance. Section: What caffeine does for training.","body":"Caffeine has small to moderate benefits for muscular endurance, bar speed, strength, sprinting, jumping and many sport-specific actions, and it improves attention and vigilance in most people. The most consistent moderate-to-large benefits are for aerobic endurance. It helps both trained and untrained people, and may help thinking and physical performance when someone is sleep-deprived, although the size of the benefit differs between individuals.","token_count":155},{"ordinal":1,"section":"Dose and timing","header":"Source: Guest et al. 2021 (ISSN), International society of sports nutrition position stand: caffeine and exercise performance. Section: Dose and timing.","body":"Doses of 3 to 6 milligrams per kilogram of body weight reliably help performance, and the smallest effective dose may be as low as 2 milligrams per kilogram. Very high doses (about 9 milligrams per kilogram) bring many more side effects and are not needed. The most common timing is about 60 minutes before exercise; chewing gum may work faster than capsules. Coffee, gum, energy drinks, gels and pre-workout products containing caffeine can all raise performance.","token_count":155},{"ordinal":2,"section":"Why responses differ","header":"Source: Guest et al. 2021 (ISSN), International society of sports nutrition position stand: caffeine and exercise performance. Section: Why responses differ.","body":"Genetic differences in how caffeine is processed, habitual intake and other factors explain why some people feel a lot and others little, and why some get trouble sleeping or feel anxious after a dose.","token_count":90},{"ordinal":3,"section":"Practical reading and limits","header":"Source: Guest et al. 2021 (ISSN), International society of sports nutrition position stand: caffeine and exercise performance. Section: Practical reading and limits.","body":"A modest dose before training can help, but late-day caffeine can cost sleep, and poor sleep undermines recovery, so evening sessions are a reason to use less or none. People who are sensitive, anxious, pregnant or who have heart or blood pressure issues should be cautious and check with a clinician. Coach should present caffeine as optional and personal, never as something a person must use.","token_count":141}]$lib$::jsonb
);

-- library-source: sawka_2007_fluid_replacement sha256:b1102cab959a01c201af25d23bd34c067696b8989bf5b3841e4403a52dff4cc1
select private.library_replace_source(
$lib${"slug":"sawka_2007_fluid_replacement","title":"American College of Sports Medicine position stand: exercise and fluid replacement","authors":["Sawka MN","Burke LM","Eichner ER","Maughan RJ","Montain SJ","Stachenfeld NS"],"year":2007,"doi":"10.1249/mss.0b013e31802ca597","url":"https://doi.org/10.1249/mss.0b013e31802ca597","licence":"proprietary","region":["global"],"topics":["nutrition","hydration","performance","safety"],"evidence_level":"position stand","kind":"position_stand"}$lib$::jsonb,
$lib$[{"ordinal":0,"section":"Before and during exercise","header":"Source: Sawka et al. 2007 (ACSM), American College of Sports Medicine position stand: exercise and fluid replacement. Section: Before and during exercise.","body":"The aim before exercise is to start well hydrated with normal blood salt levels. If needed, drink beverages alongside normal meals and fluids beginning at least several hours beforehand, which gives the body time to absorb the fluid and let urine output return to normal.\n\nDuring exercise, the goal is to avoid losing more than about 2 percent of body weight as water, since larger losses and big shifts in blood salts can harm performance. Sweat rates and sweat salt content vary a great deal from person to person, so a personalised plan is better than a single rule.","token_count":181},{"ordinal":1,"section":"How to find your own needs","header":"Source: Sawka et al. 2007 (ACSM), American College of Sports Medicine position stand: exercise and fluid replacement. Section: How to find your own needs.","body":"A simple way to estimate a personal sweat rate is to weigh yourself before and after a session. During longer exercise, drinks that contain electrolytes and carbohydrate can help more than plain water in some situations.","token_count":94},{"ordinal":2,"section":"After exercise","header":"Source: Sawka et al. 2007 (ACSM), American College of Sports Medicine position stand: exercise and fluid replacement. Section: After exercise.","body":"Afterwards the goal is to replace any fluid and salt deficit. How fast and how aggressively depends on how big the deficit is and how soon the next session is.","token_count":76},{"ordinal":3,"section":"Practical reading and limits","header":"Source: Sawka et al. 2007 (ACSM), American College of Sports Medicine position stand: exercise and fluid replacement. Section: Practical reading and limits.","body":"For most gym sessions of an hour or less, normal drinking to thirst and with meals is enough; careful fluid planning matters more for long, hot or repeated sessions. Overdrinking can be harmful too, so no one should be told to force fluids. The position stand is from 2007, and it is guidance for healthy people, not for medical conditions affecting fluid balance.","token_count":131}]$lib$::jsonb
);

-- library-source: acsm_2011_exercise_quantity sha256:1ab5c5ff08da3b39503436b444f86b9c32befb815bd339e379f86f4c42fc8156
select private.library_replace_source(
$lib${"slug":"acsm_2011_exercise_quantity","title":"American College of Sports Medicine position stand: quantity and quality of exercise for developing and maintaining cardiorespiratory, musculoskeletal, and neuromotor fitness in apparently healthy adults","authors":["Garber CE","Blissmer B","Deschenes MR","Franklin BA","Lamonte MJ","Lee IM"],"year":2011,"doi":"10.1249/MSS.0b013e318213fefb","url":"https://doi.org/10.1249/MSS.0b013e318213fefb","licence":"proprietary","region":["global"],"topics":["cardio","activity","strength","flexibility","training","guidelines"],"evidence_level":"position stand","kind":"position_stand"}$lib$::jsonb,
$lib$[{"ordinal":0,"section":"Weekly amounts","header":"Source: Garber et al. 2011 (ACSM), American College of Sports Medicine position stand: quantity and quality of exercise for developing and maintaining cardiorespiratory, musculoskeletal, and neuromotor fitness in apparently healthy adults. Section: Weekly amounts.","body":"For healthy adults this position stand recommends moderate-intensity cardio of at least 30 minutes on 5 or more days a week (150 minutes or more), or vigorous-intensity cardio of at least 20 minutes on 3 or more days (75 minutes or more), or a mix of the two, reaching about 500 to 1000 MET-minutes a week (a MET-minute is a unit that scales time by how hard the activity is).\n\nResistance exercise for each major muscle group is recommended on 2 to 3 days a week, along with balance, agility and coordination (neuromotor) work. Flexibility exercises for the main muscle-tendon groups, a total of 60 seconds each, on at least 2 days a week help maintain joint range of movement.","token_count":236},{"ordinal":1,"section":"Individualising and doing less","header":"Source: Garber et al. 2011 (ACSM), American College of Sports Medicine position stand: quantity and quality of exercise for developing and maintaining cardiorespiratory, musculoskeletal, and neuromotor fitness in apparently healthy adults. Section: Individualising and doing less.","body":"The programme should be changed to suit a person's usual activity, physical function, health, response to exercise and own goals. Adults who cannot or do not want to reach these targets still gain from smaller amounts. There are also health benefits from sitting less and breaking up long periods of sitting with short bouts of activity.","token_count":155},{"ordinal":2,"section":"Practical reading and limits","header":"Source: Garber et al. 2011 (ACSM), American College of Sports Medicine position stand: quantity and quality of exercise for developing and maintaining cardiorespiratory, musculoskeletal, and neuromotor fitness in apparently healthy adults. Section: Practical reading and limits.","body":"Use these amounts as a weekly frame: a mix of cardio, strength, balance and flexibility, adapted to the person. The benefits of exercise clearly outweigh the risks for most adults. The document is from 2011 and is for apparently healthy adults; it does not replace medical advice for people with conditions.","token_count":147}]$lib$::jsonb
);

-- library-source: who_2020_activity_guidelines sha256:db6a6b28748afe3f79e31d6ad695b521585c35d908a2cf0fd36d1ce3c54ec74b
select private.library_replace_source(
$lib${"slug":"who_2020_activity_guidelines","title":"World Health Organization 2020 guidelines on physical activity and sedentary behaviour","authors":["Bull FC","Al-Ansari SS","Biddle S","Borodulin K","Buman MP","Cardon G"],"year":2020,"doi":"10.1136/bjsports-2020-102955","url":"https://doi.org/10.1136/bjsports-2020-102955","licence":"CC-BY-4.0","region":["global"],"topics":["cardio","activity","strength","sedentary","guidelines"],"evidence_level":"public health guideline","kind":"guideline"}$lib$::jsonb,
$lib$[{"ordinal":0,"section":"What adults should do","header":"Source: Bull et al. 2020 (WHO), World Health Organization 2020 guidelines on physical activity and sedentary behaviour. Section: What adults should do.","body":"The World Health Organization advises all adults to do 150 to 300 minutes of moderate-intensity aerobic activity a week, or 75 to 150 minutes of vigorous-intensity activity, or an equivalent mix of the two. It also recommends regular muscle-strengthening activity for every age group, and for adults that means working the major muscle groups on two or more days a week.","token_count":131},{"ordinal":1,"section":"Core messages","header":"Source: Bull et al. 2020 (WHO), World Health Organization 2020 guidelines on physical activity and sedentary behaviour. Section: Core messages.","body":"Some activity is better than none, and more activity is better for health outcomes. The guidelines also recommend reducing sedentary behaviour, although the evidence was not strong enough to put a number on how much sitting is too much. Both aerobic and muscle-strengthening activity matter.","token_count":109},{"ordinal":2,"section":"What is new","header":"Source: Bull et al. 2020 (WHO), World Health Organization 2020 guidelines on physical activity and sedentary behaviour. Section: What is new.","body":"Compared with the 2010 version, the 2020 guidelines add specific recommendations for pregnant and postpartum women and for people living with chronic conditions or disability, and they give a first recommendation to limit sedentary time.","token_count":95},{"ordinal":3,"section":"Practical reading and limits","header":"Source: Bull et al. 2020 (WHO), World Health Organization 2020 guidelines on physical activity and sedentary behaviour. Section: Practical reading and limits.","body":"These are population-level minimums for health, not training targets for performance or physique goals. Gym users who lift and walk regularly usually meet them easily; people starting from low activity benefit most from small steady increases. Tracend's scope excludes pregnancy and medical conditions, so the special-population recommendations are context, not something Coach applies.","token_count":137}]$lib$::jsonb
);

-- library-source: piercy_2018_us_guidelines sha256:cc180ea28f5d45d1d98d6637912f4cde85519a07c5fc3333e5c0d7211820cf3f
select private.library_replace_source(
$lib${"slug":"piercy_2018_us_guidelines","title":"The Physical Activity Guidelines for Americans","authors":["Piercy KL","Troiano RP","Ballard RM","Carlson SA","Fulton JE","Galuska DA"],"year":2018,"doi":"10.1001/jama.2018.14854","url":"https://doi.org/10.1001/jama.2018.14854","licence":"proprietary","region":["US"],"topics":["cardio","activity","strength","guidelines"],"evidence_level":"public health guideline","kind":"guideline"}$lib$::jsonb,
$lib$[{"ordinal":0,"section":"What the guidelines say for adults","header":"Source: Piercy et al. 2018 (US guidelines), The Physical Activity Guidelines for Americans. Section: What the guidelines say for adults.","body":"The second edition of the Physical Activity Guidelines for Americans recommends that adults do at least 150 to 300 minutes a week of moderate-intensity aerobic activity, or 75 to 150 minutes of vigorous activity, or an equivalent combination, plus muscle-strengthening activities on two or more days a week. Older adults should add balance training to a multicomponent routine.","token_count":129},{"ordinal":1,"section":"How they were built","header":"Source: Piercy et al. 2018 (US guidelines), The Physical Activity Guidelines for Americans. Section: How they were built.","body":"An advisory committee reviewed the science, covering 38 questions and 104 sub-questions, and graded the strength of evidence. Only evidence graded strong or moderate underpinned the main guidelines.","token_count":80},{"ordinal":2,"section":"Key messages","header":"Source: Piercy et al. 2018 (US guidelines), The Physical Activity Guidelines for Americans. Section: Key messages.","body":"Moving more and sitting less benefits nearly everyone. People who do the least physical activity gain the most from even modest increases. Both aerobic and muscle-strengthening activity are beneficial, and activity helps people feel, function and sleep better and lowers the risk of many chronic diseases.","token_count":105},{"ordinal":3,"section":"Practical reading and limits","header":"Source: Piercy et al. 2018 (US guidelines), The Physical Activity Guidelines for Americans. Section: Practical reading and limits.","body":"The adult targets match the World Health Organization's, so they can be quoted together; for a US user, this is the national guidance. The recommendations for children, pregnancy and chronic conditions sit outside Tracend's scope.","token_count":91}]$lib$::jsonb
);

-- library-source: paluch_2022_daily_steps sha256:431e78144440bd8d95e80da95e17c281508b966e70222b2057bddb35f57c72b1
select private.library_replace_source(
$lib${"slug":"paluch_2022_daily_steps","title":"Daily steps and all-cause mortality: a meta-analysis of 15 international cohorts","authors":["Paluch AE","Bajpai S","Bassett DR","Carnethon MR","Ekelund U","Evenson KR"],"year":2022,"doi":"10.1016/S2468-2667(21)00302-9","url":"https://doi.org/10.1016/S2468-2667(21)00302-9","licence":"CC-BY-NC-ND-4.0","region":["global"],"topics":["activity","steps","cardio","health"],"evidence_level":"meta-analysis of 15 cohorts (47,471 adults)","kind":"paper"}$lib$::jsonb,
$lib$[{"ordinal":0,"section":"What the study did","header":"Source: Paluch et al. 2022, Daily steps and all-cause mortality: a meta-analysis of 15 international cohorts. Section: What the study did.","body":"The researchers pooled 15 studies of adults who wore step counters, 47,471 people in all, followed for a median of about seven years during which 3,013 died. They asked how the number of steps per day, and the pace of stepping, relate to the risk of dying from any cause.","token_count":103},{"ordinal":1,"section":"Findings","header":"Source: Paluch et al. 2022, Daily steps and all-cause mortality: a meta-analysis of 15 international cohorts. Section: Findings.","body":"Compared with the least active quarter (about 3,600 steps a day), the next quarter (about 5,800 steps) had roughly 40 percent lower risk of death, the third (about 7,800 steps) 45 percent lower, and the most active (about 10,900 steps) 53 percent lower. For adults aged 60 and over, risk kept falling until roughly 6,000 to 8,000 steps a day. For adults under 60 it kept falling until roughly 8,000 to 10,000 steps a day.\n\nAfter steps per day were accounted for, a higher stepping pace showed a weaker link to lower mortality.","token_count":164},{"ordinal":2,"section":"Practical reading and limits","header":"Source: Paluch et al. 2022, Daily steps and all-cause mortality: a meta-analysis of 15 international cohorts. Section: Practical reading and limits.","body":"There is no magic at 10,000 steps: benefits rise steadily from low counts, so adding a couple of thousand steps is worthwhile for someone who does little. These are observational results, linking steps and long-term health, not proof that adding steps causes the change, and fitter or healthier people may walk more. The outcome studied was death from any cause, not fat loss or muscle gain.","token_count":135}]$lib$::jsonb
);

-- library-source: watson_2015_sleep_duration sha256:1d56a0eb3c4d2f4e5cd3492825e256ade97f7a0aa5dccc333873d000cf5665b6
select private.library_replace_source(
$lib${"slug":"watson_2015_sleep_duration","title":"Recommended amount of sleep for a healthy adult: a joint consensus statement of the American Academy of Sleep Medicine and Sleep Research Society","authors":["Watson NF","Badr MS","Belenky G","Bliwise DL","Buxton OM","Buysse D"],"year":2015,"doi":"10.5665/sleep.4716","url":"https://doi.org/10.5665/sleep.4716","licence":"proprietary","region":["global"],"topics":["sleep","recovery","health","guidelines"],"evidence_level":"expert consensus statement (15 experts)","kind":"guideline"}$lib$::jsonb,
$lib$[{"ordinal":0,"section":"The recommendation","header":"Source: Watson et al. 2015 (AASM and SRS), Recommended amount of sleep for a healthy adult: a joint consensus statement of the American Academy of Sleep Medicine and Sleep Research Society. Section: The recommendation.","body":"A panel of 15 sleep experts, using a structured rating process, agreed that adults should regularly sleep 7 or more hours a night to support good health. Sleeping less than 7 hours on a regular basis is linked with worse health, including weight gain and obesity, diabetes, high blood pressure, heart disease and stroke, depression and a higher risk of death. It is also linked with weaker immunity, more pain, worse performance, more errors and a higher risk of accidents.","token_count":173},{"ordinal":1,"section":"Longer sleep","header":"Source: Watson et al. 2015 (AASM and SRS), Recommended amount of sleep for a healthy adult: a joint consensus statement of the American Academy of Sleep Medicine and Sleep Research Society. Section: Longer sleep.","body":"Sleeping more than 9 hours regularly may be appropriate for young adults, people paying back a sleep debt and people who are ill. For other people it is unclear whether more than 9 hours carries any health risk. Anyone worried they sleep too little or too much should talk to a healthcare provider.","token_count":128},{"ordinal":2,"section":"Practical reading and limits","header":"Source: Watson et al. 2015 (AASM and SRS), Recommended amount of sleep for a healthy adult: a joint consensus statement of the American Academy of Sleep Medicine and Sleep Research Society. Section: Practical reading and limits.","body":"Seven hours is a floor for most adults, so a person regularly sleeping five or six hours is a good reason to tell them recovery will suffer, and to make sleep a first target before changing the training. The statement covers adults aged 18 to 60 and is about health generally, not about how sleep changes training results specifically. Coach should not diagnose sleep disorders.","token_count":152}]$lib$::jsonb
);

-- library-source: walsh_2021_sleep_athlete sha256:388e29a9f4d696b9b1c9e39bde6e3c97dce109d08c26c3d5cc9f31fe5bb56376
select private.library_replace_source(
$lib${"slug":"walsh_2021_sleep_athlete","title":"Sleep and the athlete: narrative review and 2021 expert consensus recommendations","authors":["Walsh NP","Halson SL","Sargent C","Roach GD","Nédélec M","Gupta L"],"year":2021,"doi":"10.1136/bjsports-2020-102025","url":"https://doi.org/10.1136/bjsports-2020-102025","licence":"proprietary","region":["global"],"topics":["sleep","recovery","performance","training"],"evidence_level":"narrative review and expert consensus","kind":"paper"}$lib$::jsonb,
$lib$[{"ordinal":0,"section":"What athletes face","header":"Source: Walsh et al. 2021, Sleep and the athlete: narrative review and 2021 expert consensus recommendations. Section: What athletes face.","body":"Athletes are especially likely to sleep too little (under seven hours) and to sleep poorly, for example with broken sleep. Reasons include training schedules, travel and competition, and non-sport factors such as stress and anxiety, and the review notes that female athletes are more at risk.","token_count":108},{"ordinal":1,"section":"Effects on performance and health","header":"Source: Walsh et al. 2021, Sleep and the athlete: narrative review and 2021 expert consensus recommendations. Section: Effects on performance and health.","body":"A night or more without sleep reduces athletic performance, but the effect of partial restriction over one to three nights, the more realistic case, is less clear. In the wider population, habitually sleeping under seven hours makes catching respiratory infections more likely. Much sleep research in athletes is weak: controls are poor, women are under-represented and the sleep measuring tools are questionable.","token_count":142},{"ordinal":2,"section":"Recommendations","header":"Source: Walsh et al. 2021, Sleep and the athlete: narrative review and 2021 expert consensus recommendations. Section: Recommendations.","body":"The panel provides a toolbox for practitioners covering sleep education and screening, aimed at the known risk factors. It recommends an individualised approach that takes the athlete's own sense of how much sleep they need into account, instead of a blanket seven-to-nine-hour target. Napping and sleep extension might help but need more research.","token_count":121},{"ordinal":3,"section":"Practical reading and limits","header":"Source: Walsh et al. 2021, Sleep and the athlete: narrative review and 2021 expert consensus recommendations. Section: Practical reading and limits.","body":"Ask about and take sleep seriously, treat the number of hours as a guide, and weigh how the person feels. The paper is mainly about elite athletes, so conclusions for recreational lifters are an extrapolation. It is not a basis for diagnosing sleep disorders.","token_count":102}]$lib$::jsonb
);

-- library-source: dupuy_2018_recovery_techniques sha256:d076f629183648df8747c4ad3eceaa08aa27949f8f1e361882a15050da3ab972
select private.library_replace_source(
$lib${"slug":"dupuy_2018_recovery_techniques","title":"An evidence-based approach for choosing post-exercise recovery techniques to reduce markers of muscle damage, soreness, fatigue, and inflammation: a systematic review with meta-analysis","authors":["Dupuy O","Douzi W","Theurot D","Bosquet L","Dugué B"],"year":2018,"doi":"10.3389/fphys.2018.00403","url":"https://doi.org/10.3389/fphys.2018.00403","licence":"CC-BY-4.0","region":["global"],"topics":["recovery","soreness","training"],"evidence_level":"systematic review and meta-analysis (99 studies)","kind":"paper"}$lib$::jsonb,
$lib$[{"ordinal":0,"section":"What the review did","header":"Source: Dupuy et al. 2018, An evidence-based approach for choosing post-exercise recovery techniques to reduce markers of muscle damage, soreness, fatigue, and inflammation: a systematic review with meta-analysis. Section: What the review did.","body":"The authors pooled 99 studies that tested recovery methods after exercise: active recovery, massage, compression garments, water immersion, contrast water therapy, cold exposure and others. They measured delayed-onset muscle soreness, perceived fatigue, muscle damage and inflammation markers.","token_count":135},{"ordinal":1,"section":"Findings","header":"Source: Dupuy et al. 2018, An evidence-based approach for choosing post-exercise recovery techniques to reduce markers of muscle damage, soreness, fatigue, and inflammation: a systematic review with meta-analysis. Section: Findings.","body":"Active recovery, massage, compression garments, immersion, contrast water therapy and cryotherapy all reduced soreness. Massage appeared to be the most effective method for reducing soreness and perceived fatigue. Perceived fatigue also fell with compression garments, water immersion and massage. Massage and cold exposure were the most powerful for lowering inflammation markers, which fell by small amounts.","token_count":161},{"ordinal":2,"section":"Practical reading and limits","header":"Source: Dupuy et al. 2018, An evidence-based approach for choosing post-exercise recovery techniques to reduce markers of muscle damage, soreness, fatigue, and inflammation: a systematic review with meta-analysis. Section: Practical reading and limits.","body":"Several options can ease soreness for a day or two, so people can pick what they enjoy or can access. These effects are about how a person feels and about short-term markers; the review does not show that these methods improve long-term strength or muscle growth. Sleep, enough food and a sensible plan remain the foundation of recovery, and this entry does not cover treating injuries.","token_count":160}]$lib$::jsonb
);

-- library-source: riebe_2015_screening sha256:8218cfb8b6703bd4a596e8a7ca7d01dca35058afd06327513a2b94c6d56ad743
select private.library_replace_source(
$lib${"slug":"riebe_2015_screening","title":"Updating ACSM's recommendations for exercise preparticipation health screening","authors":["Riebe D","Franklin BA","Thompson PD","Garber CE","Whitfield GP","Magal M"],"year":2015,"doi":"10.1249/MSS.0000000000000664","url":"https://doi.org/10.1249/MSS.0000000000000664","licence":"proprietary","region":["global"],"topics":["screening","safety","health"],"evidence_level":"expert roundtable consensus","kind":"guideline"}$lib$::jsonb,
$lib$[{"ordinal":0,"section":"Why the screening was changed","header":"Source: Riebe et al. 2015 (ACSM), Updating ACSM's recommendations for exercise preparticipation health screening. Section: Why the screening was changed.","body":"Screening aims to spot people at raised risk of exercise-related sudden cardiac death or heart attack. The older approach sent many people to a doctor unnecessarily, which could itself discourage them from becoming active. A 2014 roundtable of the American College of Sports Medicine reviewed the evidence, noting that exercise is safe for most people, that exercise-related heart events are often preceded by warning signs and symptoms, and that the risk falls as people become more active and fit.","token_count":164},{"ordinal":1,"section":"The three-factor model","header":"Source: Riebe et al. 2015 (ACSM), Updating ACSM's recommendations for exercise preparticipation health screening. Section: The three-factor model.","body":"The new model asks about three things: the person's current level of physical activity, whether they have signs or symptoms or a known heart, metabolic or kidney disease, and the intensity of exercise they want to do. Listing cardiovascular risk factors is no longer part of the screening.","token_count":109},{"ordinal":2,"section":"Practical reading and limits","header":"Source: Riebe et al. 2015 (ACSM), Updating ACSM's recommendations for exercise preparticipation health screening. Section: Practical reading and limits.","body":"Someone who already exercises regularly and has no symptoms or known disease can usually continue; someone inactive who wants to start vigorous exercise, or anyone with warning symptoms or known disease, should speak with a healthcare professional first. Screening should be a short, non-diagnostic set of questions, and a flag is a reason to refer, not a verdict. Starting with moderate effort and building gradually is a sensible default.","token_count":149}]$lib$::jsonb
);

-- library-source: bredin_2013_parq_plus sha256:10481aa7710a7ae6aba31f22b82b64ec8b8ff3f95e21fa8c7f3656e6d0750b7a
select private.library_replace_source(
$lib${"slug":"bredin_2013_parq_plus","title":"PAR-Q+ and ePARmed-X+: new risk stratification and physical activity clearance strategy for physicians and patients alike","authors":["Bredin SSD","Gledhill N","Jamnik VK","Warburton DER"],"year":2013,"doi":null,"url":"https://pmc.ncbi.nlm.nih.gov/articles/PMC3596208/","licence":"proprietary","region":["global"],"topics":["screening","safety","health"],"evidence_level":"evidence-based clearance tool (systematic reviews and consensus)","kind":"guideline"}$lib$::jsonb,
$lib$[{"ordinal":0,"section":"Why it replaced the old questionnaire","header":"Source: Bredin et al. 2013, PAR-Q+ and ePARmed-X+: new risk stratification and physical activity clearance strategy for physicians and patients alike. Section: Why it replaced the old questionnaire.","body":"The original seven-question PAR-Q was deliberately cautious, which produced many false alarms and needless doctor referrals, excluded people under 15 and over 69 without a sound reason, and was often used inconsistently. The research team behind the new PAR-Q+ built it from systematic reviews of more than 540,000 articles and a structured consensus process, producing more than 60 evidence-based recommendations.","token_count":154},{"ordinal":1,"section":"How the PAR-Q+ works","header":"Source: Bredin et al. 2013, PAR-Q+ and ePARmed-X+: new risk stratification and physical activity clearance strategy for physicians and patients alike. Section: How the PAR-Q+ works.","body":"A person answers seven questions. If every answer is no, they are cleared for unrestricted activity following the general guidelines. If any answer is yes, they answer follow-up questions about specific medical conditions. If all of those are no, they are cleared and receive advice on a safe plan. If any is yes, they are referred to a qualified exercise professional or to the electronic ePARmed-X+ for more detail, and may end up cleared with or without restrictions.","token_count":163},{"ordinal":2,"section":"The risk continuum","header":"Source: Bredin et al. 2013, PAR-Q+ and ePARmed-X+: new risk stratification and physical activity clearance strategy for physicians and patients alike. Section: The risk continuum.","body":"The process found that the risks of staying inactive far outweigh the small, short-lived risks of exercise. Low-risk people can exercise at low to moderate intensity with little supervision; intermediate-risk people should exercise with guidance from qualified professionals; high-risk people should exercise in medically supervised settings. Gradual progression of intensity is important at every level.","token_count":146},{"ordinal":3,"section":"Practical reading and limits","header":"Source: Bredin et al. 2013, PAR-Q+ and ePARmed-X+: new risk stratification and physical activity clearance strategy for physicians and patients alike. Section: Practical reading and limits.","body":"Screening is about deciding whether and how to start, with referral for anyone who flags a concern, not about diagnosing. It was designed for use with healthcare and fitness professionals; an app can use the same logic for a first check but must route concerning answers to a qualified professional.","token_count":123}]$lib$::jsonb
);

-- library-source: byrne_2018_matador sha256:3c01c5e8575f604b60e55d68466e6ad08e92b13fac514b15950aec6f4e9f2c75
select private.library_replace_source(
$lib${"slug":"byrne_2018_matador","title":"Intermittent energy restriction improves weight loss efficiency in obese men: the MATADOR study","authors":["Byrne NM","Sainsbury A","King NA","Hills AP","Wood RE"],"year":2018,"doi":"10.1038/ijo.2017.206","url":"https://doi.org/10.1038/ijo.2017.206","licence":"CC-BY-NC-ND-4.0","region":["global"],"topics":["nutrition","energy-balance","fat-loss","diet-break","metabolic-adaptation"],"evidence_level":"randomised controlled trial (51 men with obesity)","kind":"paper"}$lib$::jsonb,
$lib$[{"ordinal":0,"section":"What the trial did","header":"Source: Byrne et al. 2018 (MATADOR), Intermittent energy restriction improves weight loss efficiency in obese men: the MATADOR study. Section: What the trial did.","body":"Fifty-one men with obesity were randomly placed on one of two diets. Both groups ate 67 percent of what they needed to hold their weight for 16 weeks in total. One group did this continuously. The other did it as eight blocks of two weeks, with a two-week block of eating at maintenance between them, so their diet lasted 30 weeks from start to finish. Forty-seven men began the diet phase, and the main results below are for the 19 continuous and 17 intermittent dieters who finished as planned.","token_count":165},{"ordinal":1,"section":"Results","header":"Source: Byrne et al. 2018 (MATADOR), Intermittent energy restriction improves weight loss efficiency in obese men: the MATADOR study. Section: Results.","body":"The intermittent group lost more weight (14.1 against 9.1 kg) and more fat (12.3 against 8.0 kg). Loss of fat-free mass was similar in the two groups (1.8 against 1.2 kg). Body weight barely moved during the seven maintenance blocks. The fall in resting energy expenditure was not different between groups, but once it was adjusted for changes in body composition the fall was smaller in the intermittent group. The authors read this as the maintenance blocks reducing the body's compensatory slowdown, which made the diet more efficient.","token_count":173},{"ordinal":2,"section":"Practical reading and limits","header":"Source: Byrne et al. 2018 (MATADOR), Intermittent energy restriction improves weight loss efficiency in obese men: the MATADOR study. Section: Practical reading and limits.","body":"The participants were men with obesity (average weight about 110 kg), so the result is not proof for a lean, trained person. The intermittent group took 30 weeks to complete the same amount of dieting, so extra time passed, and the main analysis covered only the people who completed the protocol. A later trial in trained adults (the ICECAP trial) did not find extra fat loss from breaks. Coach should present a planned break as a reasonable option that helps some people stay on track and may help a little with efficiency, not as a requirement.","token_count":180}]$lib$::jsonb
);

-- library-source: peos_2021_icecap sha256:c732fccfe486781c7267b92482ac4f8a1aeb6a15793a06292da13a17167bd333
select private.library_replace_source(
$lib${"slug":"peos_2021_icecap","title":"Continuous versus intermittent dieting for fat loss and fat-free mass retention in resistance-trained adults: the ICECAP trial","authors":["Peos JJ","Helms ER","Fournier PA","Ong J","Hall C","Krieger J"],"year":2021,"doi":"10.1249/mss.0000000000002636","url":"https://doi.org/10.1249/mss.0000000000002636","licence":"proprietary","region":["global"],"topics":["nutrition","energy-balance","fat-loss","diet-break","training","hunger"],"evidence_level":"randomised controlled trial (61 resistance-trained adults)","kind":"paper"}$lib$::jsonb,
$lib$[{"ordinal":0,"section":"What the trial did","header":"Source: Peos et al. 2021 (ICECAP), Continuous versus intermittent dieting for fat loss and fat-free mass retention in resistance-trained adults: the ICECAP trial. Section: What the trial did.","body":"Sixty-one resistance-trained adults (32 of them women, average age about 29, about 25 percent body fat) were randomly assigned to a moderate calorie deficit in one of two patterns. One group dieted for 12 weeks without a break. The other dieted in four blocks of three weeks, each followed by a week of eating at maintenance, which made 15 weeks in total. All results were analysed according to the group each person was assigned to.","token_count":157},{"ordinal":1,"section":"Results","header":"Source: Peos et al. 2021 (ICECAP), Continuous versus intermittent dieting for fat loss and fat-free mass retention in resistance-trained adults: the ICECAP trial. Section: Results.","body":"After the deficit, the groups did not differ in fat mass, fat-free mass or body weight, and there was no difference in muscle strength or endurance, resting energy expenditure, the hormones measured (leptin, testosterone, thyroid hormone, IGF-1, ghrelin), sleep, or eating-disorder-related behaviours. The group that took breaks reported lower hunger and less desire to eat, and greater satisfaction with the diet.","token_count":149},{"ordinal":2,"section":"Practical reading and limits","header":"Source: Peos et al. 2021 (ICECAP), Continuous versus intermittent dieting for fat loss and fat-free mass retention in resistance-trained adults: the ICECAP trial. Section: Practical reading and limits.","body":"For a trained person, breaks did not speed up fat loss or protect muscle better in this trial, but they made dieting feel easier. That is a good reason to offer a break to someone who is tired of dieting, and a poor reason to promise faster results. The trial lasted 12 weeks of deficit, so it does not say what happens over a very long diet.","token_count":136}]$lib$::jsonb
);

-- library-source: trexler_2014_metabolic_adaptation sha256:6e8798f78608b4535016bd17326ef9fd067c7dfd7826cd08705a4eaff65dee65
select private.library_replace_source(
$lib${"slug":"trexler_2014_metabolic_adaptation","title":"Metabolic adaptation to weight loss: implications for the athlete","authors":["Trexler ET","Smith-Ryan AE","Norton LE"],"year":2014,"doi":"10.1186/1550-2783-11-7","url":"https://doi.org/10.1186/1550-2783-11-7","licence":"CC-BY-2.0","region":["global"],"topics":["nutrition","energy-balance","fat-loss","metabolic-adaptation","diet-break","weight-maintenance"],"evidence_level":"narrative review","kind":"paper"}$lib$::jsonb,
$lib$[{"ordinal":0,"section":"What happens in a long deficit","header":"Source: Trexler et al. 2014, Metabolic adaptation to weight loss: implications for the athlete. Section: What happens in a long deficit.","body":"Eating less is followed by changes in several hormones: leptin, insulin, testosterone and thyroid hormones tend to fall, while ghrelin (which raises hunger) and cortisol tend to rise. Total daily energy expenditure falls, and the fall is often bigger than the lost body mass alone would predict. This extra drop is called adaptive thermogenesis. The energy spent on exercise and on everyday movement outside exercise (fidgeting, walking about) also falls. Some of these changes persist after the diet, even in people who have kept the lower weight for more than a year.","token_count":177},{"ordinal":1,"section":"What the authors recommend","header":"Source: Trexler et al. 2014, Metabolic adaptation to weight loss: implications for the athlete. Section: What the authors recommend.","body":"The size of the adaptation is probably in proportion to the size of the deficit, so the review advises using the smallest deficit that still gives appreciable weight loss, treating weight loss as a series of steps, and adjusting food or activity when progress flattens to open the deficit again. Large deficits cost more lean mass and hurt performance and recovery. A structured resistance training programme and enough protein help protect lean mass, and diets high in protein are linked with more fullness and more heat production from food.","token_count":169},{"ordinal":2,"section":"Refeeds, reverse dieting and regaining","header":"Source: Trexler et al. 2014, Metabolic adaptation to weight loss: implications for the athlete. Section: Refeeds, reverse dieting and regaining.","body":"Refeeds are short spells of eating slightly above maintenance, mostly extra carbohydrate, used in physique sports to lift leptin. Leptin does respond in the short term, but the measured rise in energy expenditure was modest, and the authors say there is not enough evidence that refeeds help a long diet. Reverse dieting (raising calories in small steps after a diet) is also unproven. After a diet, regained weight comes back mostly as fat, and leaner people can overshoot their old body fat. Repeated cycles of loss and regain are linked with long-term weight gain in weight-class athletes.","token_count":185},{"ordinal":3,"section":"Practical reading and limits","header":"Source: Trexler et al. 2014, Metabolic adaptation to weight loss: implications for the athlete. Section: Practical reading and limits.","body":"This is the explanation for a plateau or a rising appetite after a big loss: it is expected biology, not weak willpower, and the answer is patience, smaller deficits and keeping training and protein up. Most of the underlying research is on animals or on people with overweight who do not train, so how strongly it applies to a lean, trained person is uncertain. Refeeds and reverse dieting should be described as popular but unproven.","token_count":143}]$lib$::jsonb
);

-- library-source: mountjoy_2023_reds sha256:965fab6aafcbc7d985163793128d0a04d84453488232618229c520a65e6038b4
select private.library_replace_source(
$lib${"slug":"mountjoy_2023_reds","title":"2023 International Olympic Committee's (IOC) consensus statement on Relative Energy Deficiency in Sport (REDs)","authors":["Mountjoy M","Ackerman KE","Bailey DM","Burke LM","Constantini N","Hackney AC"],"year":2023,"doi":"10.1136/bjsports-2023-106994","url":"https://doi.org/10.1136/bjsports-2023-106994","licence":"proprietary","region":["global"],"topics":["nutrition","energy-balance","low-energy-availability","recovery","safety","fat-loss"],"evidence_level":"expert consensus statement","kind":"guideline"}$lib$::jsonb,
$lib$[{"ordinal":0,"section":"What REDs is","header":"Source: Mountjoy et al. 2023 (IOC), 2023 International Olympic Committee's (IOC) consensus statement on Relative Energy Deficiency in Sport (REDs). Section: What REDs is.","body":"Relative Energy Deficiency in Sport (REDs) is a syndrome of harmful health and performance effects seen in female and male athletes who are exposed to low energy availability, meaning they take in too little energy for the energy their exercise uses. The panel first described it in 2014 and updated it in 2023, after more than 170 new original studies since the 2018 statement.","token_count":138},{"ordinal":1,"section":"What has changed","header":"Source: Mountjoy et al. 2023 (IOC), 2023 International Olympic Committee's (IOC) consensus statement on Relative Energy Deficiency in Sport (REDs). Section: What has changed.","body":"The 2023 statement adds evidence on the part played by low carbohydrate availability and by mental health, and more data on low energy availability in males. It updates the health and performance models and introduces a physiological model that shows how a problematic or an adaptable period of low energy availability, together with personal factors, leads to different outcomes.","token_count":139},{"ordinal":2,"section":"Assessment, prevention and treatment","header":"Source: Mountjoy et al. 2023 (IOC), 2023 International Olympic Committee's (IOC) consensus statement on Relative Energy Deficiency in Sport (REDs). Section: Assessment, prevention and treatment.","body":"The statement sets out safe and effective ways to assess body composition to help prevent REDs, and introduces the REDs Clinical Assessment Tool version 2, which clinicians use to detect and diagnose REDs from the accumulated severity and risk level, with matching advice on training and competition. It also covers principles of prevention and treatment for sports organisations and clinicians.","token_count":148},{"ordinal":3,"section":"Practical reading and limits","header":"Source: Mountjoy et al. 2023 (IOC), 2023 International Olympic Committee's (IOC) consensus statement on Relative Energy Deficiency in Sport (REDs). Section: Practical reading and limits.","body":"This summary is written from the abstract, because the full text could not be fetched, so it does not list individual signs or thresholds. Detection and diagnosis belong to clinicians using the assessment tool, and Coach must never diagnose. The sensible use is to treat steady, large deficits combined with a lot of training as a reason to ask how the person feels, favour smaller deficits and enough food, and suggest a clinician when the picture looks worrying. The statement is aimed at athletes, so applying it to a recreational lifter is an extrapolation.","token_count":187}]$lib$::jsonb
);

-- library-source: varkevisser_2019_weight_loss_maintenance sha256:4f2acdd40b629affe80f9625cb481fd390d486fa6bbbeb7196dfed58e6d1a9ca
select private.library_replace_source(
$lib${"slug":"varkevisser_2019_weight_loss_maintenance","title":"Determinants of weight loss maintenance: a systematic review","authors":["Varkevisser RDM","van Stralen MM","Kroeze W","Ket JCF","Steenhuis IHM"],"year":2019,"doi":"10.1111/obr.12772","url":"https://doi.org/10.1111/obr.12772","licence":"CC-BY-NC-ND-4.0","region":["global"],"topics":["nutrition","weight-maintenance","fat-loss","behaviour-change","adherence"],"evidence_level":"systematic review (67 studies)","kind":"paper"}$lib$::jsonb,
$lib$[{"ordinal":0,"section":"What the review did","header":"Source: Varkevisser et al. 2019, Determinants of weight loss maintenance: a systematic review. Section: What the review did.","body":"The reviewers searched for prospective studies of adults with overweight or obesity who lost weight without surgery or medication. From 8,222 articles they selected 67, which together tested 124 possible determinants of keeping weight off: 5 demographic, 59 behavioural, 51 psychological or cognitive and 9 social or environmental. They scored study quality and summarised each determinant by the strength of evidence.","token_count":136},{"ordinal":1,"section":"What predicted success","header":"Source: Varkevisser et al. 2019, Determinants of weight loss maintenance: a systematic review. Section: What predicted success.","body":"Age, gender and socioeconomic status did not predict who kept weight off. Strong evidence supported these as helpful: weighing oneself regularly, monitoring what one eats, increasing physical activity, controlling portions, cutting unhealthy foods, eating less overall, eating more fruit and vegetables and drinking fewer sugary drinks. Self-monitoring of exercise and confidence in one's ability to manage weight and to exercise (self-efficacy) were also positive. Problematic eating predicted regaining, and stress on its own was not a clear predictor.","token_count":171},{"ordinal":2,"section":"Practical reading and limits","header":"Source: Varkevisser et al. 2019, Determinants of weight loss maintenance: a systematic review. Section: Practical reading and limits.","body":"Maintenance is a skill built from ordinary habits: keep tracking weight and food, stay active and stay confident, and it works in both sexes and at all ages. The review is of people with overweight or obesity, so it is only a rough guide for someone who is now at a healthy weight. The social and environmental evidence was thin, and the findings are associations, not proof of cause.","token_count":130}]$lib$::jsonb
);

-- library-source: icmr_nin_2024_dietary_guidelines sha256:f11275fc6e9f970d39acf87e20478ef90d7eb010e42929cf254dd3183cd48dd6
select private.library_replace_source(
$lib${"slug":"icmr_nin_2024_dietary_guidelines","title":"Dietary Guidelines for Indians 2024","authors":["ICMR-NIN Expert Committee"],"year":2024,"doi":null,"url":"https://www.nin.res.in/dietaryguidelines/pdfjs/locale/DGI_2024.pdf","licence":"proprietary","region":["IN"],"topics":["nutrition","protein","fat-loss","energy-balance","activity","guidelines","india"],"evidence_level":"national dietary guidelines","kind":"guideline"}$lib$::jsonb,
$lib$[{"ordinal":0,"section":"Body weight and weight loss","header":"Source: ICMR-NIN 2024, Dietary Guidelines for Indians 2024. Section: Body weight and weight loss.","body":"The guidelines apply Asian BMI cut-offs because Asians tend to carry more body fat at a given BMI: a healthy range is 18.5 to 23, overweight is above 23 up to 27.5 and obesity is above 27.5. They also use waist circumference, which is linked to higher risk above 90 cm in men and above 80 cm in women. Weight loss should be gradual, with half a kilogram a week called safe. A weight-loss diet should not go below 1,000 kcal a day and should be nutritionally complete, and the guidelines advise against deficits above 40 percent of daily energy needs. Rapid loss and anti-obesity drugs should be avoided.","token_count":176},{"ordinal":1,"section":"Protein","header":"Source: ICMR-NIN 2024, Dietary Guidelines for Indians 2024. Section: Protein.","body":"The guidelines give 0.83 g of protein per kg a day as the recommended allowance for healthy men and women, with protein supplying 10 to 15 percent of energy, and say a varied diet meets this, including a vegetarian one. They advise getting protein from food rather than protein powders, and warn that very high intakes from powders over long periods are not advisable. They accept that a higher share, 15 percent of energy, may help keep muscle during a calorie deficit. They note that protein only builds muscle with enough energy from carbohydrate and fat and with resistance exercise, and that intakes above about 1.6 g per kg a day add no further muscle in resistance training.","token_count":190},{"ordinal":2,"section":"Food pattern and activity","header":"Source: ICMR-NIN 2024, Dietary Guidelines for Indians 2024. Section: Food pattern and activity.","body":"The guidelines are food-based: a variety of whole grains and millets, pulses, vegetables, fruit, milk or curd, and nuts, with cereals and pulses combined (about 3 to 1 by raw weight) for better protein quality. They advise limiting sugar, salt, refined oil and ultra-processed foods, and avoiding soft drinks and alcohol. For activity, they recommend a combination of aerobic, strength, balance and flexibility work, including yoga, with muscle-strengthening at least two days a week for adults, and sleep of 6 to 8 hours a day.","token_count":156},{"ordinal":3,"section":"Practical reading and limits","header":"Source: ICMR-NIN 2024, Dietary Guidelines for Indians 2024. Section: Practical reading and limits.","body":"For Indian users, use these foods and cut-offs alongside the sports papers: a person at a BMI of 23 is at the top of the Asian healthy range, not comfortably inside the usual 18.5 to 25. Where the guidelines and the sports-nutrition papers disagree, such as protein powders and the daily protein target for lifters, Coach should say the two sources differ and let the athlete's own needs and goals decide, with Tracend's rules setting the numbers. The guidelines are for the general population, not for athletes, and are not a basis for medical diets.","token_count":163}]$lib$::jsonb
);

-- library-source: vella_2010_alcohol_recovery sha256:8c8c24675a431a7ff1634cf1d2623bae0b006e9562508f6ea902fbf7ea7870df
select private.library_replace_source(
$lib${"slug":"vella_2010_alcohol_recovery","title":"Alcohol, athletic performance and recovery","authors":["Vella LD","Cameron-Smith D"],"year":2010,"doi":"10.3390/nu2080781","url":"https://doi.org/10.3390/nu2080781","licence":"CC-BY-3.0","region":["global"],"topics":["alcohol","recovery","nutrition","sleep","hydration","performance"],"evidence_level":"narrative review","kind":"paper"}$lib$::jsonb,
$lib$[{"ordinal":0,"section":"Effects on the body","header":"Source: Vella and Cameron-Smith 2010, Alcohol, athletic performance and recovery. Section: Effects on the body.","body":"Alcohol acts as a diuretic, widens blood vessels, interferes with the body's temperature control and lowers work tolerance in both hot and cold conditions. It impairs the liver's glucose output and can reduce how much glucose muscle takes up and stores. It slows reaction time, balance and fine motor control in proportion to the dose, and it lowers sleep depth and shortens REM sleep.","token_count":125},{"ordinal":1,"section":"Performance","header":"Source: Vella and Cameron-Smith 2010, Alcohol, athletic performance and recovery. Section: Performance.","body":"Evidence on endurance is mixed, with harm once blood alcohol is high enough. For strength and power the review found most studies did not show a clear effect of alcohol taken just before testing, though one sprint study did. The review stresses that few clinical trials exist.","token_count":95},{"ordinal":2,"section":"Recovery","header":"Source: Vella and Cameron-Smith 2010, Alcohol, athletic performance and recovery. Section: Recovery.","body":"Results on muscle-damage markers and on rebuilding energy stores after exercise were inconclusive, and glycogen replenished within 24 hours in one study even after alcohol. Alcohol lowers muscle protein synthesis in a dose-dependent way when no exercise is done, but how that applies after a hard lifting session has not been tested properly in humans. The clearest functional finding came from one research group: after hard eccentric exercise, drinking about 1 g of alcohol per kg of body weight made the loss of muscle force at 36 hours worse.","token_count":162},{"ordinal":3,"section":"Practical reading and limits","header":"Source: Vella and Cameron-Smith 2010, Alcohol, athletic performance and recovery. Section: Practical reading and limits.","body":"Drinking is unlikely to cancel out a training programme in one night, but it can make the next sessions worse through poorer sleep, dehydration and slower recovery from damaging exercise, and replacing food with alcohol cuts the carbohydrate and protein the muscles need. The review is from 2010 and includes few human trials, so Coach should speak in terms of \"may\" and not give precise limits. Coach should not encourage drinking, nor lecture an adult about it.","token_count":146}]$lib$::jsonb
);

-- library-source: zhu_2024_motivational_interviewing sha256:9200d0178b2800844206257581c35694bacedbcc9310bbb9cae75d0ef7f99786
select private.library_replace_source(
$lib${"slug":"zhu_2024_motivational_interviewing","title":"Effectiveness of behavioural interventions with motivational interviewing on physical activity outcomes in adults: systematic review and meta-analysis","authors":["Zhu S","Sinha D","Kirk M","Michalopoulou M","Hajizadeh A","Wren G"],"year":2024,"doi":"10.1136/bmj-2023-078713","url":"https://doi.org/10.1136/bmj-2023-078713","licence":"CC-BY-4.0","region":["global"],"topics":["behaviour-change","coaching-communication","activity","adherence","motivation"],"evidence_level":"systematic review and meta-analysis (97 randomised trials)","kind":"paper"}$lib$::jsonb,
$lib$[{"ordinal":0,"section":"What the review did","header":"Source: Zhu et al. 2024, Effectiveness of behavioural interventions with motivational interviewing on physical activity outcomes in adults: systematic review and meta-analysis. Section: What the review did.","body":"Motivational interviewing is a counselling style in which the helper asks open questions, reflects back what the person says and draws out their own reasons for change. The reviewers searched seven databases up to March 2023 for randomised trials comparing a behavioural programme that included motivational interviewing with a similar programme without it, in adults, measuring physical activity or sedentary time. They found 129 papers on 97 trials with 27,811 people.","token_count":170},{"ordinal":1,"section":"Results","header":"Source: Zhu et al. 2024, Effectiveness of behavioural interventions with motivational interviewing on physical activity outcomes in adults: systematic review and meta-analysis. Section: Results.","body":"Programmes that included motivational interviewing did better than their comparators on total physical activity (about 1,323 extra steps a day, low-certainty evidence), on moderate to vigorous activity (about 95 extra minutes a week, very low certainty) and on sedentary time (about 51 minutes a day less, very low certainty). But when the comparator was a programme of similar intensity, there was no evidence of a difference. The effect faded over time, and there was no evidence of a benefit beyond one year. Most trials enrolled people with a health condition, and for the general population there was no evidence of an effect on moderate to vigorous activity or sedentary time.","token_count":220},{"ordinal":2,"section":"Practical reading and limits","header":"Source: Zhu et al. 2024, Effectiveness of behavioural interventions with motivational interviewing on physical activity outcomes in adults: systematic review and meta-analysis. Section: Practical reading and limits.","body":"A conversational, question-led style is a sensible way to coach, but it should not be sold as a proven way to raise activity: the benefit could not be isolated to the interviewing style itself, it fades, and the certainty is low. Coach can ask what the person wants and what gets in the way before suggesting changes, and should keep supporting them over months and not expect one chat to last. Most of the evidence is from people with health conditions, so for healthy lifters it is an extrapolation.","token_count":180}]$lib$::jsonb
);

-- library-source: lally_2010_habit_formation sha256:0c83b68459ee581718ac884d9275452200b0abd135d4171cb76f429b04b63267
select private.library_replace_source(
$lib${"slug":"lally_2010_habit_formation","title":"How are habits formed: modelling habit formation in the real world","authors":["Lally P","van Jaarsveld CHM","Potts HWW","Wardle J"],"year":2010,"doi":"10.1002/ejsp.674","url":"https://doi.org/10.1002/ejsp.674","licence":"proprietary","region":["global"],"topics":["behaviour-change","habits","adherence","consistency","coaching-communication"],"evidence_level":"observational study (96 volunteers over 12 weeks)","kind":"paper"}$lib$::jsonb,
$lib$[{"ordinal":0,"section":"What the study did","header":"Source: Lally et al. 2010, How are habits formed: modelling habit formation in the real world. Section: What the study did.","body":"Ninety-six volunteers each picked one eating, drinking or activity behaviour and did it every day in the same situation, for example after breakfast, for 12 weeks. Every day they rated how automatic the behaviour felt and recorded whether they did it. Eighty-two gave enough data to analyse.","token_count":104},{"ordinal":1,"section":"Results","header":"Source: Lally et al. 2010, How are habits formed: modelling habit formation in the real world. Section: Results.","body":"Automaticity rose in a curve that climbs quickly at first and then levels off. The model fitted for 62 people, and fitted well for 39 of them. Doing the behaviour more consistently went with a better fit. The time to reach 95 percent of each person's own plateau ranged from 18 to 254 days, so it can take a very long time and differs a great deal between people. Missing a single opportunity did not materially affect the process.","token_count":136},{"ordinal":2,"section":"Practical reading and limits","header":"Source: Lally et al. 2010, How are habits formed: modelling habit formation in the real world. Section: Practical reading and limits.","body":"Coach should not promise a fixed number of days to form a habit. The findings support small, specific actions tied to a steady cue, repeated consistently, and treating a missed day as no reason to quit. The volunteers chose their own behaviour and rated automaticity themselves, and the study did not test complex routines such as a full training programme.","token_count":123}]$lib$::jsonb
);

-- library-source: mujika_2001_muscular_detraining sha256:a82711fe9d22d8f03d411b057e375ed60535071b125a4ec8affa3d8ea09f5168
select private.library_replace_source(
$lib${"slug":"mujika_2001_muscular_detraining","title":"Muscular characteristics of detraining in humans","authors":["Mujika I","Padilla S"],"year":2001,"doi":"10.1097/00005768-200108000-00009","url":"https://doi.org/10.1097/00005768-200108000-00009","licence":"proprietary","region":["global"],"topics":["detraining","training","strength","recovery","time-off"],"evidence_level":"narrative review","kind":"paper"}$lib$::jsonb,
$lib$[{"ordinal":0,"section":"What detraining is","header":"Source: Mujika and Padilla 2001, Muscular characteristics of detraining in humans. Section: What detraining is.","body":"During periods when the training stimulus is too low, muscle detrains: it loses part of what training built. The review describes what happens inside muscle in people who stop training.","token_count":75},{"ordinal":1,"section":"Strength and muscle size","header":"Source: Mujika and Padilla 2001, Muscular characteristics of detraining in humans. Section: Strength and muscle size.","body":"Strength performance is in general readily maintained for up to four weeks of inactivity. The exceptions are the eccentric force and sport-specific power of highly trained athletes, and strength that was gained recently, which may fall significantly. Muscle fibre size drops quickly in strength and sprint athletes, while force production declines slowly, in line with a fall in the muscle's electrical activity (EMG). The mix of fibre types stays unchanged during the first weeks.","token_count":150},{"ordinal":2,"section":"Endurance-related changes","header":"Source: Mujika and Padilla 2001, Muscular characteristics of detraining in humans. Section: Endurance-related changes.","body":"The finer blood-supply and energy-production features of muscle start to change sooner: capillary density can fall within two to three weeks of inactivity, and oxygen extraction from the blood declines if the stoppage goes beyond three to eight weeks. These features remain above untrained levels in a detrained athlete but usually return to baseline in someone who trained only recently.","token_count":127},{"ordinal":3,"section":"Practical reading and limits","header":"Source: Mujika and Padilla 2001, Muscular characteristics of detraining in humans. Section: Practical reading and limits.","body":"A break of one to three weeks is unlikely to erase strength in someone who has trained for a while, although muscle fibre size can shrink early and recently gained strength is the least secure. Longer breaks cost more. The review is about stopping altogether, so light activity during the break is not covered, and as a narrative review it is not a pooled analysis, so the effect for a particular lifter is an estimate.","token_count":136}]$lib$::jsonb
);

-- library-source: bosquet_2013_training_cessation sha256:543dce1df0b4fa42d1955780641bbe5935c426d3f7f59653cea1b061f2c0bf56
select private.library_replace_source(
$lib${"slug":"bosquet_2013_training_cessation","title":"Effect of training cessation on muscular performance: a meta-analysis","authors":["Bosquet L","Berryman N","Dupuy O","Mekary S","Arvisais D","Bherer L"],"year":2013,"doi":"10.1111/sms.12047","url":"https://doi.org/10.1111/sms.12047","licence":"proprietary","region":["global"],"topics":["detraining","training","strength","time-off","older-adults"],"evidence_level":"meta-analysis (103 studies)","kind":"paper"}$lib$::jsonb,
$lib$[{"ordinal":0,"section":"What the analysis did","header":"Source: Bosquet et al. 2013, Effect of training cessation on muscular performance: a meta-analysis. Section: What the analysis did.","body":"The authors searched seven databases and pooled 103 studies of resistance training cessation, grouping the results by training status, sex, age and the length of the break.","token_count":76},{"ordinal":1,"section":"Results","header":"Source: Bosquet et al. 2013, Effect of training cessation on muscular performance: a meta-analysis. Section: Results.","body":"Stopping resistance training reduced every component of muscular performance: submaximal strength (a standardised effect of -0.62), maximal force (-0.46) and maximal power (-0.20), so the pooled effect was larger for submaximal strength than for power. The loss grew with the length of the break. It was larger in people over 65, and for maximal force and power it was larger in inactive people than in recreational athletes.","token_count":136},{"ordinal":2,"section":"Practical reading and limits","header":"Source: Bosquet et al. 2013, Effect of training cessation on muscular performance: a meta-analysis. Section: Practical reading and limits.","body":"Stopping does cost strength, more so the longer it lasts, and for maximal force and power the cost was smaller in recreational athletes than in inactive people. The abstract does not give weeks or percentages, so this source cannot be used to quote how much is lost after a particular number of weeks. Taken with Mujika and Padilla, it supports saying that a couple of weeks off is unlikely to be a setback for a regular lifter.","token_count":142}]$lib$::jsonb
);

-- library-source: lopes_2019_elastic_resistance sha256:ceccc1e6e6d2316f1fe6f6384e5599340c6a7aeba841dd0ba1944275ebbbd1b3
select private.library_replace_source(
$lib${"slug":"lopes_2019_elastic_resistance","title":"Effects of training with elastic resistance versus conventional resistance on muscular strength: a systematic review and meta-analysis","authors":["Lopes JSS","Machado AF","Micheletti JK","de Almeida AC","Cavina AP","Pastre CM"],"year":2019,"doi":"10.1177/2050312119831116","url":"https://doi.org/10.1177/2050312119831116","licence":"CC-BY-NC-4.0","region":["global"],"topics":["home-training","equipment","strength","training","minimal-equipment"],"evidence_level":"systematic review and meta-analysis (8 studies)","kind":"paper"}$lib$::jsonb,
$lib$[{"ordinal":0,"section":"What the review did","header":"Source: Lopes et al. 2019, Effects of training with elastic resistance versus conventional resistance on muscular strength: a systematic review and meta-analysis. Section: What the review did.","body":"Elastic resistance (tubes and bands) is cheap and easy to use, so the reviewers compared training with it against training with conventional equipment (weight machines and dumbbells) on muscular strength. They searched four databases up to December 2017 and pooled eight studies.","token_count":118},{"ordinal":1,"section":"Results","header":"Source: Lopes et al. 2019, Effects of training with elastic resistance versus conventional resistance on muscular strength: a systematic review and meta-analysis. Section: Results.","body":"Neither method was better for lower-limb strength or upper-limb strength. The authors conclude that elastic resistance training can produce strength gains similar to conventional training, across different groups of people and different training protocols.","token_count":110},{"ordinal":2,"section":"Practical reading and limits","header":"Source: Lopes et al. 2019, Effects of training with elastic resistance versus conventional resistance on muscular strength: a systematic review and meta-analysis. Section: Practical reading and limits.","body":"A person without a gym can reasonably expect to keep and even build strength with bands, and Coach should not call that second-best. Only eight studies were pooled, and the abstract does not say how muscle size changed. Another source in the library (Lopez 2021) covers lighter loads taken close to failure. This review does not test bodyweight training, so Coach should not claim bodyweight exercise works as well as weights on the strength of this paper alone.","token_count":166}]$lib$::jsonb
);

-- library-source: fragala_2019_older_adults sha256:0e6f0654ada28aa73b40f572ebd4bddb5a5022f7031efc29d302c31a7b28815f
select private.library_replace_source(
$lib${"slug":"fragala_2019_older_adults","title":"Resistance training for older adults: position statement from the National Strength and Conditioning Association","authors":["Fragala MS","Cadore EL","Dorgo S","Izquierdo M","Kraemer WJ","Peterson MD"],"year":2019,"doi":"10.1519/jsc.0000000000003230","url":"https://doi.org/10.1519/jsc.0000000000003230","licence":"proprietary","region":["global"],"topics":["older-adults","strength","training","safety","guidelines"],"evidence_level":"position statement","kind":"position_stand"}$lib$::jsonb,
$lib$[{"ordinal":0,"section":"Why it matters","header":"Source: Fragala et al. 2019 (NSCA), Resistance training for older adults: position statement from the National Strength and Conditioning Association. Section: Why it matters.","body":"Ageing, even without chronic disease, brings biological changes that can reduce skeletal muscle mass, strength and function, which lowers resilience and raises vulnerability to serious events. The position statement argues that countering muscle disuse through resistance training is a powerful way to fight the loss of strength and muscle and their consequences for physical function, mobility, independence, chronic disease management, wellbeing, quality of life and healthy life expectancy.","token_count":167},{"ordinal":1,"section":"What it covers","header":"Source: Fragala et al. 2019 (NSCA), Resistance training for older adults: position statement from the National Strength and Conditioning Association. Section: What it covers.","body":"The statement gives evidence-based recommendations in four parts: programme design variables, physiological adaptations, functional benefits, and considerations for frailty, sarcopenia and other chronic conditions. Its stated aims are a more unified approach, promotion of the health and functional benefits, and reducing fears and barriers to starting.","token_count":132},{"ordinal":2,"section":"Practical reading and limits","header":"Source: Fragala et al. 2019 (NSCA), Resistance training for older adults: position statement from the National Strength and Conditioning Association. Section: Practical reading and limits.","body":"This summary is written from the abstract, which gives no sets, loads or frequencies, so Tracend's rules and the shared training sources set those. The usable message for Coach is that older adults benefit from lifting and that fear and other barriers to starting are worth addressing kindly. Frailty, sarcopenia and chronic conditions are matters for a professional, and Coach does not plan rehabilitation. This is a peer-reviewed journal article; the association's courses and textbooks are not used.","token_count":173}]$lib$::jsonb
);

-- library-source: mcnulty_2020_menstrual_cycle sha256:14bf1669698c18d1ce2de4232404efe1a9c37a6b2101b87981c4f73ea995c39c
select private.library_replace_source(
$lib${"slug":"mcnulty_2020_menstrual_cycle","title":"The effects of menstrual cycle phase on exercise performance in eumenorrheic women: a systematic review and meta-analysis","authors":["McNulty KL","Elliott-Sale KJ","Dolan E","Swinton PA","Ansdell P","Goodall S"],"year":2020,"doi":"10.1007/s40279-020-01319-3","url":"https://doi.org/10.1007/s40279-020-01319-3","licence":"CC-BY-4.0","region":["global"],"topics":["women","menstrual-cycle","performance","training","individualisation"],"evidence_level":"systematic review and network meta-analysis (78 studies)","kind":"paper"}$lib$::jsonb,
$lib$[{"ordinal":0,"section":"What the review did","header":"Source: McNulty et al. 2020, The effects of menstrual cycle phase on exercise performance in eumenorrheic women: a systematic review and meta-analysis. Section: What the review did.","body":"Sex hormones change across the menstrual cycle, and results on whether this affects exercise performance conflict. The authors followed standard systematic review rules, searched four databases and included 78 studies of women with regular cycles, 51 of which could be pooled in a first analysis comparing the early follicular phase (the early part of the cycle) with all other phases. A broader network analysis compared every phase with every other using 73 studies.","token_count":163},{"ordinal":1,"section":"Results","header":"Source: McNulty et al. 2020, The effects of menstrual cycle phase on exercise performance in eumenorrheic women: a systematic review and meta-analysis. Section: Results.","body":"Performance might be trivially lower in the early follicular phase than in the other phases, for both endurance and strength outcomes. The largest difference was between the early follicular and the late follicular phase, and it was small. The quality of the evidence was low.","token_count":112},{"ordinal":2,"section":"Practical reading and limits","header":"Source: McNulty et al. 2020, The effects of menstrual cycle phase on exercise performance in eumenorrheic women: a systematic review and meta-analysis. Section: Practical reading and limits.","body":"Because the effect is trivial, the variation between studies is large and many included studies were of poor quality, the authors say general guidelines on exercise across the cycle cannot be made and recommend a personalised approach based on how each woman responds. Coach should therefore not change a plan by cycle day by default, but should listen when a woman reports a pattern in her own training. The review covers women with regular cycles, not irregular cycles, hormonal contraception or the menopause, and Coach should not give medical advice on these.","token_count":189}]$lib$::jsonb
);

-- library-source: williams_2017_periodised_strength sha256:8072b79306669ac9298872a0719d1d80118babc2f5ac8b116816b2de2e244f2f
select private.library_replace_source(
$lib${"slug":"williams_2017_periodised_strength","title":"Comparison of periodized and non-periodized resistance training on maximal strength: a meta-analysis","authors":["Williams TD","Tolusso DV","Fedewa MV","Esco MR"],"year":2017,"doi":"10.1007/s40279-017-0734-y","url":"https://doi.org/10.1007/s40279-017-0734-y","licence":"proprietary","region":["global"],"topics":["training","periodisation","strength","progression"],"evidence_level":"meta-analysis (18 studies, 81 effects)","kind":"paper"}$lib$::jsonb,
$lib$[{"ordinal":0,"section":"What the review did","header":"Source: Williams et al. 2017, Comparison of periodized and non-periodized resistance training on maximal strength: a meta-analysis. Section: What the review did.","body":"Periodisation means arranging training into planned phases in which load, repetitions and volume change over time. The authors pooled 18 studies, published between 1988 and 2015, that compared a periodised resistance programme with a non-periodised one and measured one-repetition maximum strength in the squat, bench press or leg press. The studies supplied 81 effect estimates, combined with a random-effects model.","token_count":145},{"ordinal":1,"section":"Findings","header":"Source: Williams et al. 2017, Comparison of periodized and non-periodized resistance training on maximal strength: a meta-analysis. Section: Findings.","body":"Periodised programmes raised one-repetition maximum more than non-periodised ones, by a moderate standardised effect of 0.43 (95 percent confidence interval 0.27 to 0.58). Four factors were linked to the size of that advantage: undulating models (where load and repetition targets change often) did better than other models, and the effect was larger in untrained participants, in longer studies and with more frequent training. The authors concluded that changing loads and repetitions over time seems to be a key part of getting stronger.","token_count":173},{"ordinal":2,"section":"Practical reading and limits","header":"Source: Williams et al. 2017, Comparison of periodized and non-periodized resistance training on maximal strength: a meta-analysis. Section: Practical reading and limits.","body":"Planned variation in load and repetitions is a reasonable way to keep strength moving over months. The abstract does not describe matching total training volume between groups as an entry rule, so some of the advantage may reflect differences in the amount of work. The Moesgaard 2022 entry, which kept volume equal, found a smaller strength advantage, and the ACSM 2026 overview in this library found no consistent effect of periodisation across reviews. Coach should present periodisation as a useful structure, not a requirement; the plan's rules set the actual progression. This summary was written from the abstract only, so study quality and populations are not described here.","token_count":214}]$lib$::jsonb
);

-- library-source: moesgaard_2022_periodisation_volume_equated sha256:436d4ccbbc76eb17de64c38faacfc420f58b9593492ab9aad0f9419f572ec291
select private.library_replace_source(
$lib${"slug":"moesgaard_2022_periodisation_volume_equated","title":"Effects of periodization on strength and muscle hypertrophy in volume-equated resistance training programs: a systematic review and meta-analysis","authors":["Moesgaard L","Beck MM","Christiansen L","Aagaard P","Lundbye-Jensen J"],"year":2022,"doi":"10.1007/s40279-021-01636-1","url":"https://doi.org/10.1007/s40279-021-01636-1","licence":"proprietary","region":["global"],"topics":["training","periodisation","strength","hypertrophy","volume"],"evidence_level":"systematic review and meta-analysis (35 studies)","kind":"paper"}$lib$::jsonb,
$lib$[{"ordinal":0,"section":"What the review did","header":"Source: Moesgaard et al. 2022, Effects of periodization on strength and muscle hypertrophy in volume-equated resistance training programs: a systematic review and meta-analysis. Section: What the review did.","body":"The authors kept only studies in which total training volume was the same in the programmes being compared, so any difference could be put down to how the work was arranged rather than how much there was. Thirty-five studies qualified. The two main comparisons were non-periodised against periodised training, and linear periodisation (gradual changes over weeks) against undulating periodisation (frequent daily or weekly changes in volume and intensity). Results were also split by training status. Other model comparisons had too few studies to analyse.","token_count":191},{"ordinal":1,"section":"Findings","header":"Source: Moesgaard et al. 2022, Effects of periodization on strength and muscle hypertrophy in volume-equated resistance training programs: a systematic review and meta-analysis. Section: Findings.","body":"For one-repetition maximum strength, periodised training beat non-periodised training by a small effect of 0.31 (95 percent confidence interval 0.04 to 0.57), and undulating beat linear by a similar 0.31 (0.02 to 0.61). The undulating advantage was seen in trained participants (0.61, with an interval starting at 0.00) but not in untrained ones (0.06).\n\nFor muscle size there was no clear difference, either between periodised and non-periodised training (0.13, interval minus 0.10 to 0.36) or between linear and undulating models (0.05). The authors suggest periodisation helps strength mainly through nervous-system adaptations rather than extra muscle.","token_count":214},{"ordinal":2,"section":"Practical reading and limits","header":"Source: Moesgaard et al. 2022, Effects of periodization on strength and muscle hypertrophy in volume-equated resistance training programs: a systematic review and meta-analysis. Section: Practical reading and limits.","body":"When the amount of work is equal, the way it is organised seems to matter a little for strength in trained lifters and not for muscle size. For someone chasing muscle, enough hard sets and steady progression count for more than the choice of model; a trained lifter aiming for a bigger one-repetition maximum may gain a small edge from regular variation in load and repetitions. The trained-lifter result is borderline, and the ACSM 2026 entry in this library did not find a consistent periodisation effect across reviews. This summary was written from the abstract only.","token_count":197}]$lib$::jsonb
);

-- library-source: grgic_2017_linear_undulating_hypertrophy sha256:210407029bf392a22a00784a0fb3f9d0cd001d35f8ffd0a756898ec58373306d
select private.library_replace_source(
$lib${"slug":"grgic_2017_linear_undulating_hypertrophy","title":"Effects of linear and daily undulating periodized resistance training programs on measures of muscle hypertrophy: a systematic review and meta-analysis","authors":["Grgic J","Mikulic P","Podnar H","Pedisic Z"],"year":2017,"doi":"10.7717/peerj.3695","url":"https://doi.org/10.7717/peerj.3695","licence":"CC-BY-4.0","region":["global"],"topics":["training","periodisation","hypertrophy","volume","progression"],"evidence_level":"systematic review and meta-analysis (13 studies, 417 participants)","kind":"paper"}$lib$::jsonb,
$lib$[{"ordinal":0,"section":"What the review did","header":"Source: Grgic et al. 2017, Effects of linear and daily undulating periodized resistance training programs on measures of muscle hypertrophy: a systematic review and meta-analysis. Section: What the review did.","body":"The authors compared two common ways of organising training for muscle growth. Linear periodisation moves gradually, typically about every four weeks, towards heavier loads and less volume. Daily undulating periodisation changes the load and repetition target from one session to the next. They included 13 studies (417 participants, 303 of them in the two periodised groups) that matched volume between models, lasted at least six weeks and measured muscle size, either directly with imaging or indirectly through body composition. Studies averaged about 12 weeks.","token_count":194},{"ordinal":1,"section":"Findings","header":"Source: Grgic et al. 2017, Effects of linear and daily undulating periodized resistance training programs on measures of muscle hypertrophy: a systematic review and meta-analysis. Section: Findings.","body":"The pooled difference between models was essentially zero (standardised difference minus 0.02, 95 percent confidence interval minus 0.25 to 0.21). The result held when studies were removed one at a time, when the two studies that added aerobic training were dropped, and when results were split by measurement method or by study length. Methodological quality was moderate to high.","token_count":145},{"ordinal":2,"section":"Practical reading and limits","header":"Source: Grgic et al. 2017, Effects of linear and daily undulating periodized resistance training programs on measures of muscle hypertrophy: a systematic review and meta-analysis. Section: Practical reading and limits.","body":"For muscle growth, the choice between a linear and a daily undulating layout looks like a matter of preference; the authors point to training volume and progressive overload as what counts. Someone who likes watching the same lift climb week to week may prefer a linear plan, and someone who needs variety to stay consistent may prefer frequent changes. All but one study used untrained people, studies were short, and few used sensitive imaging such as ultrasound or MRI, so this says little about experienced lifters over a full year. The Moesgaard 2022 entry, which included later studies, also found no difference for muscle size.","token_count":214}]$lib$::jsonb
);

-- library-source: helms_2018_rpe_vs_percentage sha256:136c9052fedf15597193936912d9d9e1dc6b7181cfbad5014cc8fa45359f05f7
select private.library_replace_source(
$lib${"slug":"helms_2018_rpe_vs_percentage","title":"RPE vs. percentage 1RM loading in periodized programs matched for sets and repetitions","authors":["Helms ER","Byrnes RK","Cooke DM","Haischer MH","Carzoli JP","Johnson TK"],"year":2018,"doi":"10.3389/fphys.2018.00247","url":"https://doi.org/10.3389/fphys.2018.00247","licence":"CC-BY-4.0","region":["global"],"topics":["training","autoregulation","rpe","rir","strength","intensity"],"evidence_level":"randomised trial (21 trained men, 8 weeks)","kind":"paper"}$lib$::jsonb,
$lib$[{"ordinal":0,"section":"What the study did","header":"Source: Helms et al. 2018, RPE vs. percentage 1RM loading in periodized programs matched for sets and repetitions. Section: What the study did.","body":"Twenty-one men aged 19 to 35, each with at least two years of lifting and a squat of at least 1.5 times and a bench press of at least 1.25 times body weight, squatted and bench pressed three times a week for eight weeks. Both groups followed the same daily undulating programme with identical exercises, sets, repetitions and rest. One group (11 men) lifted set percentages of their pre-study one-repetition maximum. The other (10 men) picked loads to land in a target range on the repetitions-in-reserve effort scale, adjusting by about 2 percent for each half-point outside the range. Everyone took the same protein and amino acid supplement around sessions.","token_count":201},{"ordinal":1,"section":"Findings","header":"Source: Helms et al. 2018, RPE vs. percentage 1RM loading in periodized programs matched for sets and repetitions. Section: Findings.","body":"Both groups gained strength and muscle thickness (chest and thigh, by ultrasound), with no statistically significant difference between them. Strength gains were a little larger with effort-based loading (squat about 17 against 14 kg, bench press about 11 against 10 kg), which the authors described as a small, probable but uncertain advantage; muscle growth was effectively equal. The effort group ended up training at a higher average rating and, on the bench press, with heavier relative loads and slightly more volume. Most sets in both groups finished roughly 3 to 4 repetitions short of failure.","token_count":184},{"ordinal":2,"section":"Practical reading and limits","header":"Source: Helms et al. 2018, RPE vs. percentage 1RM loading in periodized programs matched for sets and repetitions. Section: Practical reading and limits.","body":"Letting the lifter set the day's load from a target effort works at least as well as fixed percentages, and may help strength slightly because loads can rise as the person improves. Worthwhile gains also came without training to failure. The trial was small and short, in strong young men, and covered only two lifts, so the strength edge is a possibility rather than a firm result. The Hickmott 2022 entry pools this and similar trials.","token_count":148}]$lib$::jsonb
);

-- library-source: hickmott_2022_autoregulation sha256:ac6fceaa2f80c83632cc0c05948b274880c7361edf1b9448078ac1a93ac2033e
select private.library_replace_source(
$lib${"slug":"hickmott_2022_autoregulation","title":"The effect of load and volume autoregulation on muscular strength and hypertrophy: a systematic review and meta-analysis","authors":["Hickmott LM","Chilibeck PD","Shaw KA","Butcher SJ"],"year":2022,"doi":"10.1186/s40798-021-00404-9","url":"https://doi.org/10.1186/s40798-021-00404-9","licence":"CC-BY-4.0","region":["global"],"topics":["training","autoregulation","rpe","rir","strength","hypertrophy"],"evidence_level":"systematic review and meta-analysis (18 studies reviewed, 15 pooled)","kind":"paper"}$lib$::jsonb,
$lib$[{"ordinal":0,"section":"What the review did","header":"Source: Hickmott et al. 2022, The effect of load and volume autoregulation on muscular strength and hypertrophy: a systematic review and meta-analysis. Section: What the review did.","body":"Autoregulation means adjusting training to how the person is performing on the day. The review covered two kinds. Load autoregulation sets the weight from effort ratings (repetitions in reserve) or bar speed rather than a fixed percentage of a tested maximum. Volume autoregulation ends a set once bar speed has fallen by a chosen percentage, so a larger allowed drop means more repetitions and a set closer to failure. Of 18 studies reviewed, 15 were pooled: 6 on load and 9 on volume, lasting 5 to 12 weeks. Participants were resistance trained and mostly young men; one load study was of adolescent girls.","token_count":198},{"ordinal":1,"section":"Findings","header":"Source: Hickmott et al. 2022, The effect of load and volume autoregulation on muscular strength and hypertrophy: a systematic review and meta-analysis. Section: Findings.","body":"Autoregulated and percentage-based loading gave similar one-repetition maximum gains (about 2 kg more with autoregulation, not statistically significant; standardised difference 0.21). Effort-rating methods leaned towards a small benefit (about 3 kg, borderline) while bar-speed methods showed none, but the two did not differ significantly. Only one load study measured muscle size, so no pooled answer was possible there.\n\nFor set length, stopping at 25 percent bar-speed loss or less gave slightly more strength (about 2.3 kg), mainly in studies where participants also did other training. Allowing more than 25 percent loss gave slightly more growth (about 0.6 square centimetres of muscle cross-section), though a 20 to 25 percent loss grew muscle about as well.","token_count":235},{"ordinal":2,"section":"Practical reading and limits","header":"Source: Hickmott et al. 2022, The effect of load and volume autoregulation on muscular strength and hypertrophy: a systematic review and meta-analysis. Section: Practical reading and limits.","body":"Effort-based load selection is a sound alternative to fixed percentages rather than a clear upgrade; its main value may be letting loads rise when the lifter is ready and ease back on a poor day. Stopping sets a bit further from failure suits strength, and going a bit closer suits size, but both differences were small. Most people have no bar-speed device, so repetitions in reserve is the practical tool; the Halperin 2022 entry describes how accurate those estimates are. Studies were short and mostly in young trained men.","token_count":180}]$lib$::jsonb
);

-- library-source: halperin_2022_rir_prediction_accuracy sha256:8afe02d9b511ec33e87f442dfb10e7fd2fa6d2db4df4f243865b98590e6232a3
select private.library_replace_source(
$lib${"slug":"halperin_2022_rir_prediction_accuracy","title":"Accuracy in predicting repetitions to task failure in resistance exercise: a scoping review and exploratory meta-analysis","authors":["Halperin I","Malleron T","Har-Nir I","Androulakis-Korakakis P","Wolf M","Fisher J"],"year":2022,"doi":"10.1007/s40279-021-01559-x","url":"https://doi.org/10.1007/s40279-021-01559-x","licence":"proprietary","region":["global"],"topics":["training","rir","rpe","autoregulation","intensity"],"evidence_level":"scoping review and exploratory meta-analysis (12 studies, 414 participants)","kind":"paper"}$lib$::jsonb,
$lib$[{"ordinal":0,"section":"What the review did","header":"Source: Halperin et al. 2022, Accuracy in predicting repetitions to task failure in resistance exercise: a scoping review and exploratory meta-analysis. Section: What the review did.","body":"Training by repetitions in reserve relies on people judging how many more repetitions they could manage before failure. This review collected studies in which healthy participants made that judgement, before or during a set, and then kept going to failure so the guess could be checked. Sixteen publications qualified, and 12 studies with 414 participants went into a multilevel meta-analysis of 262 effect estimates. The search ran to January 2021.","token_count":158},{"ordinal":1,"section":"Findings","header":"Source: Halperin et al. 2022, Accuracy in predicting repetitions to task failure in resistance exercise: a scoping review and exploratory meta-analysis. Section: Findings.","body":"On average, people guessed close to one repetition fewer than they could actually do (0.95 repetitions, 95 percent confidence interval 0.17 to 1.73), with very large differences between studies. Guesses became slightly more accurate when made nearer to failure, in sets of 12 repetitions or fewer rather than longer sets, and in later sets. Training experience made no clear difference, nor did upper versus lower body exercises, and accuracy varied little from person to person.","token_count":163},{"ordinal":2,"section":"Practical reading and limits","header":"Source: Halperin et al. 2022, Accuracy in predicting repetitions to task failure in resistance exercise: a scoping review and exploratory meta-analysis. Section: Practical reading and limits.","body":"A target such as two reps in reserve is a useful guide, not a precise measurement: people tend to be about a repetition out, and usually have a little more left than they think. Estimates are least reliable in light, high-repetition sets and early sets, so effort targets work best as ranges and are best judged across several sessions. The authors left open whether this much error matters in practice, and studies explained and confirmed failure in different ways. This summary was written from the abstract only.","token_count":177}]$lib$::jsonb
);

-- library-source: refalo_2023_failure_hypertrophy sha256:1321c19ac75a45b2adcd9ed8ebe01464c75740bbf9d7c18cbc2ad1bb2490d5ac
select private.library_replace_source(
$lib${"slug":"refalo_2023_failure_hypertrophy","title":"Influence of resistance training proximity-to-failure on skeletal muscle hypertrophy: a systematic review with meta-analysis","authors":["Refalo MC","Helms ER","Trexler ET","Hamilton DL","Fyfe JJ"],"year":2023,"doi":"10.1007/s40279-022-01784-y","url":"https://doi.org/10.1007/s40279-022-01784-y","licence":"CC-BY-4.0","region":["global"],"topics":["training","hypertrophy","rir","intensity","volume"],"evidence_level":"systematic review and meta-analysis (15 studies)","kind":"paper"}$lib$::jsonb,
$lib$[{"ordinal":0,"section":"What the review did","header":"Source: Refalo et al. 2023, Influence of resistance training proximity-to-failure on skeletal muscle hypertrophy: a systematic review with meta-analysis. Section: What the review did.","body":"The authors found 15 studies in healthy adults that measured muscle growth and compared how close to failure sets were taken. They grouped them three ways: momentary muscular failure (no further repetition possible) against stopping short; other definitions of failure against stopping short; and studies that ended sets at different amounts of bar-speed loss, where a bigger loss means finishing nearer failure. Seven of the nine failure-versus-non-failure studies used untrained people, while all six bar-speed studies used trained people and heavier loads.","token_count":186},{"ordinal":1,"section":"Findings","header":"Source: Refalo et al. 2023, Influence of resistance training proximity-to-failure on skeletal muscle hypertrophy: a systematic review with meta-analysis. Section: Findings.","body":"Pooling every definition of failure gave a statistically significant but trivial advantage for failure (effect size 0.19, 95 percent confidence interval 0.00 to 0.37), not changed by whether volume load was matched or by the load used. The authors warn this result is fragile: it lost significance under slightly different statistical assumptions. Comparing only true momentary failure with stopping short showed no clear difference (0.12), and larger bar-speed losses did not reliably beat moderate ones (0.08). Within-group growth was similar whether sets went to failure, near failure or to moderate or large speed loss. The advantage for failure looked somewhat larger with light loads (0.28 against 0.15), though the difference was not statistically significant.","token_count":235},{"ordinal":2,"section":"Practical reading and limits","header":"Source: Refalo et al. 2023, Influence of resistance training proximity-to-failure on skeletal muscle hypertrophy: a systematic review with meta-analysis. Section: Practical reading and limits.","body":"The authors propose that the benefit flattens out: getting reasonably close to failure matters, but going all the way adds little and brings more fatigue. They suggest stopping most sets close to failure and keeping true failure mainly for simpler, safer exercises such as machines and single-joint lifts, the last set of an exercise, and lighter loads. They also name muscles trained with few sets or only once or twice a week, and trained lifters, as cases where going to failure may make more sense. This fits the Robinson 2024 entry, which found more growth as sets end nearer failure but an uncertain shape; both say close is good and the best distance is not settled. Studies were few and small, and how close the non-failure sets really got was often unclear.","token_count":240}]$lib$::jsonb
);

-- library-source: coleman_2024_deload_trial sha256:6ffd0298284c6a41f24a9f51890bf81e1f2b62454a01ac03f5a45c6598b36d34
select private.library_replace_source(
$lib${"slug":"coleman_2024_deload_trial","title":"Gaining more from doing less? The effects of a one-week deload period during supervised resistance training on muscular adaptations","authors":["Coleman M","Burke R","Augustin F","Piñero A","Maldonado J","Fisher JP"],"year":2024,"doi":"10.7717/peerj.16777","url":"https://doi.org/10.7717/peerj.16777","licence":"CC-BY-4.0","region":["global"],"topics":["training","deload","recovery","strength","hypertrophy","time-off"],"evidence_level":"randomised controlled trial (39 trained adults, 9 weeks)","kind":"paper"}$lib$::jsonb,
$lib$[{"ordinal":0,"section":"What the study did","header":"Source: Coleman et al. 2024, Gaining more from doing less? The effects of a one-week deload period during supervised resistance training on muscular adaptations. Section: What the study did.","body":"Thirty-nine resistance-trained young adults (29 men and 10 women, all with at least a year of regular lifting) followed a high-volume nine-week programme: upper and lower body sessions, each twice a week, with sets taken to volitional failure. The lower body work (Smith machine squat, leg extension, toe press and seated calf raise, five sets of 8 to 12 repetitions each) was supervised; the upper body sessions were done alone. One group took the fifth week completely off resistance training, while the other trained straight through. The team measured muscle thickness, lower body strength, local endurance and jump power.","token_count":205},{"ordinal":1,"section":"Findings","header":"Source: Coleman et al. 2024, Gaining more from doing less? The effects of a one-week deload period during supervised resistance training on muscular adaptations. Section: Findings.","body":"Gains in thigh and calf muscle thickness, leg extension endurance and jump height were similar in both groups. Strength was the exception: continuous training gave somewhat larger gains in squat one-repetition maximum and isometric knee extension strength, with probabilities of about 85 and 92 percent in its favour, although the size of the difference was uncertain. The week-off group later reported slightly more soreness and lower motivation, and participants often said informally that they felt out of practice, not refreshed, after the break.","token_count":183},{"ordinal":2,"section":"Practical reading and limits","header":"Source: Coleman et al. 2024, Gaining more from doing less? The effects of a one-week deload period during supervised resistance training on muscular adaptations. Section: Practical reading and limits.","body":"A one-week break did not cost muscle, but it did not boost growth either, and it may cost a little strength. Here the deload was complete rest; the authors note that coaches usually deload by cutting volume or load instead, which this trial did not test. Results apply to young trained adults, the lower body and a nine-week block. This fits the Bell 2023 entry: a deload is a coaching practice with a sensible purpose, not a proven requirement, and whether one applies is for the plan's rules and the athlete's own data to decide.","token_count":183}]$lib$::jsonb
);

-- library-source: travis_2020_powerlifting_taper sha256:2d16df11fc007e0e41d6098656e3e0da572b71ced207ba0c4ee45ff3d913908b
select private.library_replace_source(
$lib${"slug":"travis_2020_powerlifting_taper","title":"Tapering and peaking maximal strength for powerlifting performance: a review","authors":["Travis SK","Mujika I","Gentles JA","Stone MH","Bazyler CD"],"year":2020,"doi":"10.3390/sports8090125","url":"https://doi.org/10.3390/sports8090125","licence":"CC-BY-4.0","region":["global"],"topics":["training","tapering","peaking","strength","performance","detraining"],"evidence_level":"systematic review (16 studies)","kind":"paper"}$lib$::jsonb,
$lib$[{"ordinal":0,"section":"What the review did","header":"Source: Travis et al. 2020, Tapering and peaking maximal strength for powerlifting performance: a review. Section: What the review did.","body":"Most tapering research comes from endurance sport. This review gathered 16 studies of strength and power athletes (powerlifters, weightlifters, throwers and strongman competitors) and well-trained lifters who cut back or stopped training before a competition or a one-repetition maximum test. It also drew on surveys of national powerlifting teams and of strongman athletes. Apart from one large survey, samples ranged from 5 to 44 people.","token_count":144},{"ordinal":1,"section":"Findings","header":"Source: Travis et al. 2020, Tapering and peaking maximal strength for powerlifting performance: a review. Section: Findings.","body":"Tapers of 1 to 4 weeks that cut volume by roughly a third to about 70 percent were followed by better squat (about 2 to 10 percent) and bench press (about 1 to 6 percent) results. Moderate cuts of about 30 to 50 percent over two weeks seemed to work better than larger ones, and cuts above about 70 percent sometimes left performance flat or worse. Changes in volume appeared to matter more than changes in intensity. Two to seven days of complete rest before testing kept or improved performance, whereas two weeks or more off began to lower maximums slightly.","token_count":172},{"ordinal":2,"section":"The authors' recommendation","header":"Source: Travis et al. 2020, Tapering and peaking maximal strength for powerlifting performance: a review. Section: The authors' recommendation.","body":"To peak maximal strength, they suggest cutting volume by about 30 to 70 percent over one to two weeks, keeping loads heavy (about 85 percent of maximum or more) or trimming them near the end, reducing work either progressively (an exponential taper) or in a single step, and finishing with 2 to 7 days of complete rest.","token_count":116},{"ordinal":3,"section":"Practical reading and limits","header":"Source: Travis et al. 2020, Tapering and peaking maximal strength for powerlifting performance: a review. Section: Practical reading and limits.","body":"A taper only makes sense for someone with a real target day, such as a meet or a planned maximum test; most people training for health or muscle do not need one, and a short planned easing is a different thing from a routine deload. The evidence is thin: few, small studies with varied methods, and the authors could not account for drug use or outside activity. The numbers are a guide for planning, and the plan's rules decide the actual reduction.","token_count":149}]$lib$::jsonb
);

-- library-source: bosquet_2007_tapering sha256:d547b912f84d519788e35b243d64ba891bd2c21fc35fbd74637a9212aaef4b87
select private.library_replace_source(
$lib${"slug":"bosquet_2007_tapering","title":"Effects of tapering on performance: a meta-analysis","authors":["Bosquet L","Montpetit J","Arvisais D","Mujika I"],"year":2007,"doi":"10.1249/mss.0b013e31806010e0","url":"https://doi.org/10.1249/mss.0b013e31806010e0","licence":"proprietary","region":["global"],"topics":["tapering","peaking","performance","cardio","training"],"evidence_level":"meta-analysis (27 studies of competitive athletes)","kind":"paper"}$lib$::jsonb,
$lib$[{"ordinal":0,"section":"What the review did","header":"Source: Bosquet et al. 2007, Effects of tapering on performance: a meta-analysis. Section: What the review did.","body":"The authors searched six databases and kept 27 of 182 candidate studies in which competitive athletes cut their training before a competition or a field-based performance test, with enough detail about how training was reduced to calculate effects. They then asked which features of the taper (reductions in intensity, volume or frequency, the pattern of the reduction and how long it lasted) went with the biggest gains in performance.","token_count":137},{"ordinal":1,"section":"Findings","header":"Source: Bosquet et al. 2007, Effects of tapering on performance: a meta-analysis. Section: Findings.","body":"The best results came from a taper of about two weeks (overall effect 0.59), in which training volume was reduced by 41 to 60 percent (effect 0.72) following an exponential, progressive pattern rather than a single step, while training intensity and the number of sessions stayed the same. The authors offered this as the most efficient way to bring performance to a peak.","token_count":119},{"ordinal":2,"section":"Practical reading and limits","header":"Source: Bosquet et al. 2007, Effects of tapering on performance: a meta-analysis. Section: Practical reading and limits.","body":"A taper is a short, planned cut in training volume, keeping sessions and intensity, before an event that matters. It belongs to people with a target day, such as a race or a competition, not to everyday training. The abstract does not list the sports; the Travis 2020 entry in this library describes this analysis as evidence from endurance athletes and finds broadly similar volume cuts work for strength athletes. This summary was written from the abstract only, so the size and quality of the pooled studies are not described here.","token_count":164}]$lib$::jsonb
);

-- library-source: haugen_2023_free_weights_machines sha256:c982d71f61fbf7e6042791ab8d7e7bc74837a660eac9b0103b61facb3591cbf0
select private.library_replace_source(
$lib${"slug":"haugen_2023_free_weights_machines","title":"Effect of free-weight vs. machine-based strength training on maximal strength, hypertrophy and jump performance: a systematic review and meta-analysis","authors":["Haugen ME","Vårvik FT","Larsen S","Haugen AS","van den Tillaar R","Bjørnsen T"],"year":2023,"doi":"10.1186/s13102-023-00713-4","url":"https://doi.org/10.1186/s13102-023-00713-4","licence":"CC-BY-4.0","region":["global"],"topics":["training","exercise-selection","free-weights","machines","equipment","strength","hypertrophy"],"evidence_level":"systematic review and meta-analysis (13 studies, 1,016 participants)","kind":"paper"}$lib$::jsonb,
$lib$[{"ordinal":0,"section":"What the review did","header":"Source: Haugen et al. 2023, Effect of free-weight vs. machine-based strength training on maximal strength, hypertrophy and jump performance: a systematic review and meta-analysis. Section: What the review did.","body":"The authors pooled 13 studies that directly compared free-weight training (barbell squat, bench press and similar) with machine training (leg press, chest press, Smith machine and similar) for at least six weeks in adults aged 18 to 60. There were 1,016 participants, mostly men; six studies used trained and seven untrained people, and none used competitive athletes. Studies lasted about nine weeks on average, with two to four sessions a week. Twelve studies measured maximal strength, five jump height and five muscle size.","token_count":185},{"ordinal":1,"section":"Findings","header":"Source: Haugen et al. 2023, Effect of free-weight vs. machine-based strength training on maximal strength, hypertrophy and jump performance: a systematic review and meta-analysis. Section: Findings.","body":"Strength gains followed the equipment. Tested on free weights, the free-weight groups gained a little more (standardised difference about 0.21); tested on machines, the machine groups tended to gain more (about 0.29, short of significance). When each group was tested on the equipment it trained with, gains were similar (0.08), and so were isometric strength, jump height and muscle growth (minus 0.06). Training status did not change these results, and both kinds of training improved every outcome measured.","token_count":178},{"ordinal":2,"section":"Practical reading and limits","header":"Source: Haugen et al. 2023, Effect of free-weight vs. machine-based strength training on maximal strength, hypertrophy and jump performance: a systematic review and meta-analysis. Section: Practical reading and limits.","body":"For general strength and muscle, free weights and machines both work, so the choice can rest on preference, access, comfort and goals. Strength is partly specific to the tool: someone who wants a bigger barbell squat should practise the barbell squat, and the same goes for machine lifts. The authors speculate that a mix of both may suit total muscle growth best, which the data did not test. Muscle-size results came from few studies, several using indirect measures, and the analysis did not adjust for differences in volume, effort or range of motion.","token_count":194}]$lib$::jsonb
);

-- library-source: wolf_2023_partial_full_rom sha256:ab2ec4e706065fec3d71c29a80edcd55df11828d0b04d33f782b35a6e708fc82
select private.library_replace_source(
$lib${"slug":"wolf_2023_partial_full_rom","title":"Partial vs full range of motion resistance training: a systematic review and meta-analysis","authors":["Wolf M","Androulakis-Korakakis P","Fisher JP","Schoenfeld BJ","Steele J"],"year":2023,"doi":"10.47206/ijsc.v3i1.182","url":"https://doi.org/10.47206/ijsc.v3i1.182","licence":"CC-BY-4.0","region":["global"],"topics":["training","range-of-motion","exercise-selection","hypertrophy","strength","joint-friendly"],"evidence_level":"systematic review and Bayesian meta-analysis (23 studies analysed)","kind":"paper"}$lib$::jsonb,
$lib$[{"ordinal":0,"section":"What the review did","header":"Source: Wolf et al. 2023, Partial vs full range of motion resistance training: a systematic review and meta-analysis. Section: What the review did.","body":"The authors searched to August 2022 and included 24 studies, published papers and some university theses, that compared training through a full range of motion with a partial range; 23 had usable data. They pooled strength, muscle size, power, sport-type and body-fat outcomes, and explored sub-groups: whether the partial range kept the muscle short or long, upper against lower body, machines against free weights, and whether the outcome test resembled one of the training styles.","token_count":158},{"ordinal":1,"section":"Findings","header":"Source: Wolf et al. 2023, Partial vs full range of motion resistance training: a systematic review and meta-analysis. Section: Findings.","body":"Full range came out ahead overall, but only trivially (standardised difference 0.12, 95 percent interval minus 0.02 to 0.26). Every outcome type leaned the same way by small amounts, for example about 0.14 for strength, 0.04 for muscle size and 0.19 for power, and upper and lower body looked alike. Strength was specific to the range trained: full range won by a small margin (0.32) on tests that resembled full-range training, while partial range did trivially better on tests that resembled partials. In an exploratory analysis, partials done with the muscle in a lengthened position tended to grow muscle more than full range (minus 0.28, with a wide interval crossing zero); partials at short muscle lengths did not.","token_count":215},{"ordinal":2,"section":"Practical reading and limits","header":"Source: Wolf et al. 2023, Partial vs full range of motion resistance training: a systematic review and meta-analysis. Section: Practical reading and limits.","body":"Full range of motion is a sensible default, but the gap is small enough that a shorter range is a fair choice when a joint, equipment or preference calls for it; for muscle growth, keeping the stretched part of the movement looks wiser than keeping the top. This is broader than the Schoenfeld and Grgic 2020 entry, which favoured full range for the legs; the authors credit newer studies and say an earlier four-study, legs-only meta-analysis may have overstated the full-range benefit. Sub-group findings are exploratory and underpowered, theses may not have had full peer review, and the lead author's doctoral funding came from a commercial coaching company.","token_count":205}]$lib$::jsonb
);

-- library-source: kassiano_2022_exercise_variation sha256:d97b89098109585eacb5ca8fde1b8fe4a1e7b125af6c66b1e74c5bfa47d1d3c1
select private.library_replace_source(
$lib${"slug":"kassiano_2022_exercise_variation","title":"Does varying resistance exercises promote superior muscle hypertrophy and strength gains? A systematic review","authors":["Kassiano W","Nunes JP","Costa B","Ribeiro AS","Schoenfeld BJ","Cyrino ES"],"year":2022,"doi":"10.1519/JSC.0000000000004258","url":"https://doi.org/10.1519/JSC.0000000000004258","licence":"proprietary","region":["global"],"topics":["training","exercise-selection","exercise-substitution","hypertrophy","strength"],"evidence_level":"systematic review (8 studies, 241 young men)","kind":"paper"}$lib$::jsonb,
$lib$[{"ordinal":0,"section":"What the review did","header":"Source: Kassiano et al. 2022, Does varying resistance exercises promote superior muscle hypertrophy and strength gains? A systematic review. Section: What the review did.","body":"Coaches often rotate exercises to keep training fresh or to work a muscle from different angles, but it was unclear whether that beats sticking with a fixed selection. This systematic review searched three databases and found eight trials that compared varied with fixed exercise selection for muscle growth and strength. All 241 participants were young men. Study quality was rated good to excellent on a standard physiotherapy trial scale. The results were described study by study rather than pooled into a single estimate.","token_count":175},{"ordinal":1,"section":"Findings","header":"Source: Kassiano et al. 2022, Does varying resistance exercises promote superior muscle hypertrophy and strength gains? A systematic review. Section: Findings.","body":"Exercise variation did make a difference, in both directions. Some planned, systematic variation appeared to improve growth across different regions of a muscle and to help maximise dynamic strength. Excessive or random variation, changing exercises very often, and swapping between exercises that give much the same stimulus appeared able to reduce gains. The authors recommend choosing variations deliberately, based on anatomy and how each exercise loads the muscle.","token_count":158},{"ordinal":2,"section":"Practical reading and limits","header":"Source: Kassiano et al. 2022, Does varying resistance exercises promote superior muscle hypertrophy and strength gains? A systematic review. Section: Practical reading and limits.","body":"Rotating exercises for its own sake is not needed. A modest set of well-chosen exercises that load a muscle in genuinely different ways, each kept long enough to progress, fits this evidence. Replacing an exercise that does not suit a person's joints or equipment with another that trains the same muscles is a considered, one-off swap rather than frequent rotation, which is in keeping with the review's idea of systematic variation. The evidence is eight small studies in young men, and this summary was written from the abstract only, so effect sizes and study details are not given.","token_count":192}]$lib$::jsonb
);

-- library-source: keogh_2017_weight_training_injuries sha256:f3e00e7c51ec3c4886b329c30c080d30e358384cceb068f35f2d25ee493fab9e
select private.library_replace_source(
$lib${"slug":"keogh_2017_weight_training_injuries","title":"The epidemiology of injuries across the weight-training sports","authors":["Keogh JWL","Winwood PW"],"year":2017,"doi":"10.1007/s40279-016-0575-0","url":"https://doi.org/10.1007/s40279-016-0575-0","licence":"proprietary","region":["global"],"topics":["injury-risk","safety","training","strength"],"evidence_level":"systematic review (20 studies of competitive weight-training athletes)","kind":"paper"}$lib$::jsonb,
$lib$[{"ordinal":0,"section":"What the review did","header":"Source: Keogh and Winwood 2017, The epidemiology of injuries across the weight-training sports. Section: What the review did.","body":"The authors searched four databases for studies of injury in competitive weight-training sports: weightlifting, powerlifting, bodybuilding, strongman, Highland Games and CrossFit. They found 20 eligible studies and rated each for risk of bias. Only five had a low risk of bias, and only four followed athletes forward in time; most asked athletes to recall injuries after the fact. Fourteen studies had more than 100 participants.","token_count":139},{"ordinal":1,"section":"Findings","header":"Source: Keogh and Winwood 2017, The epidemiology of injuries across the weight-training sports. Section: Findings.","body":"Bodybuilding had the lowest injury rates, about 0.12 to 0.7 injuries per lifter per year, or about 0.24 to 1 per 1,000 hours of training. Strongman (about 4.5 to 6.1 per 1,000 hours) and Highland Games (about 7.5 per 1,000 hours) had the highest. The shoulder, lower back, knee, elbow and wrist or hand were injured most often, mostly as strains, tendon irritation and sprains. Age, sex, competitive level and bodyweight class made few clear differences. The authors concluded that these sports seem to have relatively low injury rates compared with common team sports.","token_count":171},{"ordinal":2,"section":"Practical reading and limits","header":"Source: Keogh and Winwood 2017, The epidemiology of injuries across the weight-training sports. Section: Practical reading and limits.","body":"Lifting carries some risk, as any sport does, but the rate is low; the highest figures came from strongman and Highland Games, which involve unusual implements and events, and bodybuilding-style training was lowest. The body parts that come up most, shoulders, lower back, knees and elbows, deserve care with progression and technique. The data are mostly competitors recalling injuries, which is less reliable than tracking them, and recreational gym-goers were not the subject. This does not cover treating an injury; persistent pain is a reason to see a professional.","token_count":177}]$lib$::jsonb
);

-- library-source: lauersen_2018_strength_dose_injury sha256:bdefac66ce5e8ee82d9786192c1a19407cc479c5f03e0109bfd3df1ca9354eac
select private.library_replace_source(
$lib${"slug":"lauersen_2018_strength_dose_injury","title":"Strength training as superior, dose-dependent and safe prevention of acute and overuse sports injuries: a systematic review, qualitative analysis and meta-analysis","authors":["Lauersen JB","Andersen TE","Andersen LB"],"year":2018,"doi":"10.1136/bjsports-2018-099078","url":"https://doi.org/10.1136/bjsports-2018-099078","licence":"proprietary","region":["global"],"topics":["injury-prevention","injury-risk","strength","training","volume"],"evidence_level":"systematic review and meta-analysis (6 randomised trials, 7,738 participants)","kind":"paper"}$lib$::jsonb,
$lib$[{"ordinal":0,"section":"What the review did","header":"Source: Lauersen et al. 2018, Strength training as superior, dose-dependent and safe prevention of acute and overuse sports injuries: a systematic review, qualitative analysis and meta-analysis. Section: What the review did.","body":"Two of the authors of the Lauersen 2014 entry narrowed their focus to randomised trials that used strength training to prevent sports injuries in people who were not injured. Searching four databases to July 2017, they found six trials testing five programmes, with 7,738 participants aged 12 to 40 who had 177 sudden or overuse injuries between them. The trials were published from 2003 to 2016, five in Europe and one in Africa.","token_count":164},{"ordinal":1,"section":"Findings","header":"Source: Lauersen et al. 2018, Strength training as superior, dose-dependent and safe prevention of acute and overuse sports injuries: a systematic review, qualitative analysis and meta-analysis. Section: Findings.","body":"Strength training cut injury risk to about a third of the control rate (risk ratio 0.338, 95 percent confidence interval 0.238 to 0.480). The result held across robustness checks, the strength of evidence was rated high, and there was no sign of publication bias. In a follow-up regression, a 10 percent increase in strength training volume went with an injury risk more than four percentage points lower, and both more volume and higher intensity were linked to lower risk. The trials were judged well run, with high compliance and no safety concerns.","token_count":192},{"ordinal":2,"section":"Practical reading and limits","header":"Source: Lauersen et al. 2018, Strength training as superior, dose-dependent and safe prevention of acute and overuse sports injuries: a systematic review, qualitative analysis and meta-analysis. Section: Practical reading and limits.","body":"Regular, progressive strength training is one of the best-supported ways to lower sports injury risk, and within the range studied more of it seemed to help further. The evidence is only six trials in organised sport, some including teenagers, with programmes aimed at particular injuries, so it does not set a dose for gym-goers and cannot promise that anyone will avoid injury. This summary was written from the abstract only.","token_count":166}]$lib$::jsonb
);

-- library-source: impellizzeri_2020_acwr_pitfalls sha256:c368367df38505a4eceda16995b2086efdeaec3a4e515deaee49c5cfc9f96dba
select private.library_replace_source(
$lib${"slug":"impellizzeri_2020_acwr_pitfalls","title":"Acute:chronic workload ratio: conceptual issues and fundamental pitfalls","authors":["Impellizzeri FM","Tenan MS","Kempton T","Novak A","Coutts AJ"],"year":2020,"doi":"10.1123/ijspp.2019-0864","url":"https://doi.org/10.1123/ijspp.2019-0864","licence":"proprietary","region":["global"],"topics":["acwr","load-management","injury-risk","injury-prevention","progression"],"evidence_level":"methodological critique","kind":"paper"}$lib$::jsonb,
$lib$[{"ordinal":0,"section":"What the paper argues","header":"Source: Impellizzeri et al. 2020, Acute:chronic workload ratio: conceptual issues and fundamental pitfalls. Section: What the paper argues.","body":"The acute-to-chronic workload ratio compares a recent week of training load with the average of several recent weeks, and it became the most popular load-based injury warning sign in sport. These authors point out that advising people to change their ratio in order to change their injury risk assumes the ratio causes injuries, yet no study had used methods able to test that. In their view, adjusting the ratio to prevent injury is an untested idea that goes beyond what the data show.","token_count":157},{"ordinal":1,"section":"The specific problems","header":"Source: Impellizzeri et al. 2020, Acute:chronic workload ratio: conceptual issues and fundamental pitfalls. Section: The specific problems.","body":"Their reasons are mixed. The measure is ambiguous, and there is little theory for why the ratio itself should matter. Its link with injury is neither consistent nor one-directional, and no study has shown that it causes injury. They conclude the ratio should not be used to manage load or guide injury-prevention advice, because dividing one load by another distorts the numbers and can produce apparent links with injury that are artefacts of the maths.","token_count":149},{"ordinal":2,"section":"Practical reading and limits","header":"Source: Impellizzeri et al. 2020, Acute:chronic workload ratio: conceptual issues and fundamental pitfalls. Section: Practical reading and limits.","body":"This directly challenges one part of the Gabbett 2016 entry in this library, which proposed the ratio as a useful way to spot spikes in load. Coach should present both sides: Gabbett's wider point, that well-prepared hard training is protective and large sudden jumps are a plausible risk, remains a sensible coaching habit, but the ratio's numbers should not be quoted as safe zones or used to forecast injury. A 2021 follow-up led by the same author (Impellizzeri et al., Sports Medicine 2021, doi 10.1007/s40279-020-01378-6) reanalysed published data and recommended dropping the ratio altogether. The research behind the ratio comes mostly from team sport, and this summary was written from the abstract only.","token_count":215}]$lib$::jsonb
);

-- library-source: trommelen_2023_protein_dose sha256:08aa3db5c7ddab897d657263a39be41be7775811914a9bfb24666bfc6e2df393
select private.library_replace_source(
$lib${"slug":"trommelen_2023_protein_dose","title":"The anabolic response to protein ingestion during recovery from exercise has no upper limit in magnitude and duration in vivo in humans","authors":["Trommelen J","van Lieshout GAA","Nyakayiru J","Holwerda AM","Smeets JSJ","Hendriks FK"],"year":2023,"doi":"10.1016/j.xcrm.2023.101324","url":"https://doi.org/10.1016/j.xcrm.2023.101324","licence":"CC-BY-4.0","region":["global"],"topics":["nutrition","protein","timing","hypertrophy"],"evidence_level":"randomised controlled trial, acute tracer study (36 young men)","kind":"paper"}$lib$::jsonb,
$lib$[{"ordinal":0,"section":"What the study did","header":"Source: Trommelen et al. 2023, The anabolic response to protein ingestion during recovery from exercise has no upper limit in magnitude and duration in vivo in humans. Section: What the study did.","body":"Thirty-six healthy, recreationally active young men did one whole-body resistance session and then drank 0, 25 or 100 g of milk protein (12 per group, assigned at random). The protein carried stable isotope labels, so the researchers could follow where its amino acids went, and they sampled blood and thigh muscle for 12 hours. Earlier dose studies had mostly tested 45 g at most and measured for 6 hours or less.","token_count":153},{"ordinal":1,"section":"Findings","header":"Source: Trommelen et al. 2023, The anabolic response to protein ingestion during recovery from exercise has no upper limit in magnitude and duration in vivo in humans. Section: Findings.","body":"Muscle protein building over the 12 hours rose with the dose: 100 g beat 25 g, which beat none. Compared with 25 g, the 100 g dose raised myofibrillar protein synthesis by about 20 percent in the first 4 hours and about 40 percent from hour 4 to 12, so the large serving worked mainly by lasting longer. After 100 g, protein was still being absorbed at 12 hours. Amino acid burning rose only slightly next to the rise in protein building, and body protein breakdown barely changed. About 18 percent of the 25 g serving and about 13 percent of the 100 g serving (about 13 g) was built into muscle over the 12 hours.","token_count":201},{"ordinal":2,"section":"How it fits with other entries (Tracend's reading)","header":"Source: Trommelen et al. 2023, The anabolic response to protein ingestion during recovery from exercise has no upper limit in magnitude and duration in vivo in humans. Section: How it fits with other entries (Tracend's reading).","body":"The Schoenfeld and Aragon 2018 entry in this library, and the digest's guide of about 0.25 to 0.4 g per kg per meal over 3 to 4 meals, lean on studies in which muscle building levelled off near 20 to 25 g. This trial suggests that ceiling partly reflects measuring for too short a time: a large serving keeps working for longer rather than being burned off. The two are not fully at odds, because spreading protein still gives several rises across the day, but the idea that extra protein in one meal is simply wasted is not supported here.","token_count":193},{"ordinal":3,"section":"Practical reading and limits","header":"Source: Trommelen et al. 2023, The anabolic response to protein ingestion during recovery from exercise has no upper limit in magnitude and duration in vivo in humans. Section: Practical reading and limits.","body":"This was one session and one drink in a laboratory, in young men, using milk protein after whole-body lifting. It did not measure muscle growth over weeks, and the authors note the body might adapt to repeated large meals. Tracend's reading: the daily total matters most, and spreading protein over 3 to 4 meals remains a sensible guide, but someone who prefers fewer, larger protein meals need not fear the extra is lost. One author works for a dairy company, which did not fund the study.","token_count":175}]$lib$::jsonb
);

-- library-source: iraki_2019_offseason_bodybuilding sha256:cf8120f40426aafba3040fa32621235d77504e8e17f3ad3870b4c0887eed0ef5
select private.library_replace_source(
$lib${"slug":"iraki_2019_offseason_bodybuilding","title":"Nutrition Recommendations for Bodybuilders in the Off-Season: A Narrative Review","authors":["Iraki J","Fitschen P","Espinar S","Helms E"],"year":2019,"doi":"10.3390/sports7070154","url":"https://doi.org/10.3390/sports7070154","licence":"CC-BY-4.0","region":["global"],"topics":["nutrition","energy-surplus","bulking","protein","hypertrophy","supplements"],"evidence_level":"narrative review","kind":"paper"}$lib$::jsonb,
$lib$[{"ordinal":0,"section":"Surplus and rate of gain","header":"Source: Iraki et al. 2019, Nutrition Recommendations for Bodybuilders in the Off-Season: A Narrative Review. Section: Surplus and rate of gain.","body":"The review argues that the right surplus depends on training experience. Untrained people can gain mostly lean mass on large surpluses, but trained lifters are closer to their ceiling, so a big surplus mainly adds fat, which then lengthens the next diet. In one study of elite athletes it cites, eating about 600 kcal a day more gave slightly more lean mass (1.7 against 1.2 kg, not significant) but clearly more fat (1.1 against 0.2 kg). The authors suggest eating about 10 to 20 percent above maintenance and gaining about 0.25 to 0.5 percent of body weight a week, with advanced lifters at the low end or below, judged from weekly average weights.","token_count":199},{"ordinal":1,"section":"Macronutrients and meals","header":"Source: Iraki et al. 2019, Nutrition Recommendations for Bodybuilders in the Off-Season: A Narrative Review. Section: Macronutrients and meals.","body":"Protein of 1.6 to 2.2 g per kg a day is suggested, split into 3 to 6 meals of about 0.40 to 0.55 g per kg, with one meal within 1 to 2 hours of training. Fat of about 0.5 to 1.5 g per kg a day (20 to 35 percent of energy) avoids very low intakes, and the rest of the energy comes from carbohydrate, ideally at least 3 to 5 g per kg a day; ketogenic diets have gone with poorer muscle gain in trained people. The authors note that long-term studies often fail to confirm timing tricks that look useful in short laboratory studies.","token_count":169},{"ordinal":2,"section":"Supplements","header":"Source: Iraki et al. 2019, Nutrition Recommendations for Bodybuilders in the Off-Season: A Narrative Review. Section: Supplements.","body":"Creatine monohydrate (3 g a day, no loading needed) and caffeine (5 to 6 mg per kg before training) are presented as likely to help; beta-alanine (3 to 5 g a day, for high-repetition phases) and citrulline malate (8 g before training) as possible. A low-dose multivitamin and fish oil are suggested only as a safety net for diet gaps or general health, not for muscle.","token_count":125},{"ordinal":3,"section":"Practical reading and limits","header":"Source: Iraki et al. 2019, Nutrition Recommendations for Bodybuilders in the Off-Season: A Narrative Review. Section: Practical reading and limits.","body":"This is expert opinion built on mostly short studies; the authors say large, long trials in off-season bodybuilders are lacking. Its protein per meal sits above the digest's 0.25 to 0.4 g per kg, and its caffeine dose at the top of the Guest 2021 entry's range. Tracend's reading: a small surplus with slow, steady weight gain is the guide, the plan's rules set the numbers, and none of the supplements is needed to make progress.","token_count":145}]$lib$::jsonb
);

-- library-source: slater_2019_energy_surplus sha256:4eb06112726cc87432d04b1705038faf9cb94645a3bfc2056f8d9790cb5690e4
select private.library_replace_source(
$lib${"slug":"slater_2019_energy_surplus","title":"Is an Energy Surplus Required to Maximize Skeletal Muscle Hypertrophy Associated With Resistance Training","authors":["Slater GJ","Dieter BP","Marsh DJ","Helms ER","Shaw G","Iraki J"],"year":2019,"doi":"10.3389/fnut.2019.00131","url":"https://doi.org/10.3389/fnut.2019.00131","licence":"CC-BY-4.0","region":["global"],"topics":["nutrition","energy-surplus","bulking","hypertrophy","energy-balance"],"evidence_level":"narrative review","kind":"paper"}$lib$::jsonb,
$lib$[{"ordinal":0,"section":"What the review asked","header":"Source: Slater et al. 2019, Is an Energy Surplus Required to Maximize Skeletal Muscle Hypertrophy Associated With Resistance Training. Section: What the review asked.","body":"The authors examined whether eating more than you burn is needed to build muscle with lifting, how big any surplus should be, where the extra energy should come from and when to eat it. They found no well-controlled long-term trials that set out to test a surplus directly in lifters, so they drew on overfeeding studies, short trials and physiology.","token_count":130},{"ordinal":1,"section":"Main points","header":"Source: Slater et al. 2019, Is an Energy Surplus Required to Maximize Skeletal Muscle Hypertrophy Associated With Resistance Training. Section: Main points.","body":"A surplus does push the body towards gaining lean mass, even without training, but overfeeding alone mostly adds fat: in one classic study, men gained about 2 kg of fat for each kg of lean mass. Textbook figures for the cost of building a kilogram of muscle ignore the energy used to make new protein and the body's own adjustments to overeating (more fidgeting, more heat from digestion), and people vary widely, so no single figure is supported. Muscle can also grow in a deficit, most clearly in untrained people or those with more body fat. As long as minimum intakes of protein (the review cites 1.6 to 2.2 g per kg a day for lifters), carbohydrate and fat are met, the source of the extra energy seems not to matter much. Drinks and more frequent snacks can help people who struggle to eat more.","token_count":240},{"ordinal":2,"section":"Practical reading and limits","header":"Source: Slater et al. 2019, Is an Energy Surplus Required to Maximize Skeletal Muscle Hypertrophy Associated With Resistance Training. Section: Practical reading and limits.","body":"The authors advise starting with a modest surplus of about 1,500 to 2,000 kJ a day (roughly 360 to 480 kcal) and adjusting from changes in body composition and strength. This is reasoned advice, not a tested prescription, and the review predates the Helms 2023 trial in this library, which found larger surpluses mostly added fat in trained lifters. Tracend's reading: a small surplus checked against weekly trends is the guide, and newer lifters can usually grow on less extra food than they expect.","token_count":169}]$lib$::jsonb
);

-- library-source: helms_2023_energy_surplus sha256:57604099c10c9521f8b4ea59f2108c69996254eed1dcb4667265fa1c05a18805
select private.library_replace_source(
$lib${"slug":"helms_2023_energy_surplus","title":"Effect of Small and Large Energy Surpluses on Strength, Muscle, and Skinfold Thickness in Resistance-Trained Individuals: A Parallel Groups Design","authors":["Helms ER","Spence AJ","Sousa C","Kreiger J","Taylor S","Oranchuk DJ"],"year":2023,"doi":"10.1186/s40798-023-00651-y","url":"https://doi.org/10.1186/s40798-023-00651-y","licence":"CC-BY-4.0","region":["global"],"topics":["nutrition","energy-surplus","bulking","hypertrophy","strength","body-composition"],"evidence_level":"randomised trial (17 resistance-trained adults completed)","kind":"paper"}$lib$::jsonb,
$lib$[{"ordinal":0,"section":"What the trial did","header":"Source: Helms et al. 2023, Effect of Small and Large Energy Surpluses on Strength, Muscle, and Skinfold Thickness in Resistance-Trained Individuals: A Parallel Groups Design. Section: What the trial did.","body":"Twenty-one resistance-trained lifters with at least a year of experience were assigned to eat at maintenance, about 5 percent above it, or about 15 percent above it for 8 weeks while doing the same supervised full-body programme three times a week. Protein was at least 1.8 g per kg a day for everyone. COVID-19 disruption left 17 completers (2 of them women), so the authors also analysed how weight change related to each outcome across all participants.","token_count":165},{"ordinal":1,"section":"Findings","header":"Source: Helms et al. 2023, Effect of Small and Large Energy Surpluses on Strength, Muscle, and Skinfold Thickness in Resistance-Trained Individuals: A Parallel Groups Design. Section: Findings.","body":"Thigh and triceps muscle thickness and squat strength changed similarly in all groups. The 15 percent group gained more bench press strength in the group comparison, but bench gains were not linked to how much weight people gained. The clearest result was that weight gain strongly predicted gains in skinfold thickness (a measure of fat). Only the biceps, the most heavily trained muscle in the programme, showed a weak link between more weight gain and more growth. The 5 and 15 percent groups gained about the same weight (about 3.3 kg each over 8 weeks), and the authors note that not everyone kept to their assigned surplus, so a precise small surplus can be hard to hit.","token_count":218},{"ordinal":2,"section":"Practical reading and limits","header":"Source: Helms et al. 2023, Effect of Small and Large Energy Surpluses on Strength, Muscle, and Skinfold Thickness in Resistance-Trained Individuals: A Parallel Groups Design. Section: Practical reading and limits.","body":"The authors recommend conservative surpluses of about 5 to 20 percent above maintenance, or gaining about 0.25 to 0.5 percent of body weight a week, smaller and slower for more experienced lifters. The sample was small, mostly male and mixed in experience, the programme was moderate in volume, and it lasted only 8 weeks. Tracend's reading: faster gain mainly adds fat, so a small surplus is the default, while someone who cares more about size than leanness may choose faster gain knowingly.","token_count":177}]$lib$::jsonb
);

-- library-source: murphy_2022_energy_deficiency_lean_mass sha256:508b72fe0de84a8f4fc260bf76ed4fc7936f3a670146f35512b17744a906effe
select private.library_replace_source(
$lib${"slug":"murphy_2022_energy_deficiency_lean_mass","title":"Energy deficiency impairs resistance training gains in lean mass but not strength: A meta-analysis and meta-regression","authors":["Murphy C","Koehler K"],"year":2022,"doi":"10.1111/sms.14075","url":"https://doi.org/10.1111/sms.14075","licence":"CC-BY-NC-ND-4.0","region":["global"],"topics":["nutrition","energy-balance","fat-loss","recomposition","hypertrophy","strength"],"evidence_level":"systematic review, meta-analysis and meta-regression of randomised trials","kind":"paper"}$lib$::jsonb,
$lib$[{"ordinal":0,"section":"What the review did","header":"Source: Murphy and Koehler 2022, Energy deficiency impairs resistance training gains in lean mass but not strength: A meta-analysis and meta-regression. Section: What the review did.","body":"The authors searched for randomised trials in which people did resistance training while eating less than they burned for at least 3 weeks. In one analysis they pooled trials that had a comparison group training without a deficit. In a second they matched deficit trials without such a group to similar trials of training without a deficit. They then combined both sets to look at how the size of the deficit related to lean mass change.","token_count":155},{"ordinal":1,"section":"Findings","header":"Source: Murphy and Koehler 2022, Energy deficiency impairs resistance training gains in lean mass but not strength: A meta-analysis and meta-regression. Section: Findings.","body":"Training in a deficit gave smaller lean mass gains than training without one (effect size about minus 0.57 in the main analysis), while strength gains were similar (about minus 0.31, not significant). The matched comparison agreed: lean mass fell slightly in the deficit trials and rose in the trials without a deficit, but strength rose about equally in both. In the combined analysis, a deficit of roughly 500 kcal a day was enough to prevent lean mass gains. The authors advise people training to build muscle to avoid long deficits, and people training to keep muscle while losing weight to avoid deficits larger than 500 kcal a day.","token_count":203},{"ordinal":2,"section":"Practical reading and limits","header":"Source: Murphy and Koehler 2022, Energy deficiency impairs resistance training gains in lean mass but not strength: A meta-analysis and meta-regression. Section: Practical reading and limits.","body":"This explains a common experience: strength can keep rising during a diet even when muscle size stalls. The 500 kcal figure is an average from a regression across mixed studies, not a hard line for every person, and this summary is written from the abstract only, so participant details and study count are not given here. It fits the digest's advice to lose about 0.5 to 1 percent of body weight a week and the Garthe 2011 entry. Tracend's reading: moderate deficits, with lifting and protein kept up, are the guide.","token_count":178}]$lib$::jsonb
);

-- library-source: garthe_2011_weight_loss_rate sha256:66c83efbc2cbd226e21d742c5d8b9b9fa98d84e1f76fd983fb7e5b1ad407258f
select private.library_replace_source(
$lib${"slug":"garthe_2011_weight_loss_rate","title":"Effect of Two Different Weight-Loss Rates on Body Composition and Strength and Power-Related Performance in Elite Athletes","authors":["Garthe I","Raastad T","Refsnes PE","Koivisto A","Sundgot-Borgen J"],"year":2011,"doi":"10.1123/ijsnem.21.2.97","url":"https://doi.org/10.1123/ijsnem.21.2.97","licence":"proprietary","region":["global"],"topics":["nutrition","fat-loss","energy-balance","body-composition","strength"],"evidence_level":"randomised controlled trial (24 elite athletes)","kind":"paper"}$lib$::jsonb,
$lib$[{"ordinal":0,"section":"What the trial did","header":"Source: Garthe et al. 2011, Effect of Two Different Weight-Loss Rates on Body Composition and Strength and Power-Related Performance in Elite Athletes. Section: What the trial did.","body":"Twenty-four elite athletes who needed to lose weight were randomly assigned to a slow target of about 0.7 percent of body weight a week (13 athletes) or a fast target of about 1.4 percent a week (11 athletes). Both groups followed energy-restricted diets and kept four resistance training sessions a week within their usual training. They were measured with DEXA scans, one-repetition maximum tests, a 40 metre sprint and a jump test.","token_count":154},{"ordinal":1,"section":"Findings","header":"Source: Garthe et al. 2011, Effect of Two Different Weight-Loss Rates on Body Composition and Strength and Power-Related Performance in Elite Athletes. Section: Findings.","body":"The slow group dieted for about 8.5 weeks and the fast group for about 5.3. Energy intake was cut by about 19 percent and 30 percent. Both groups lost about 5.5 percent of body weight; in practice the weekly losses were about 0.7 and 1.0 percent. Fat mass fell by about 31 percent in the slow group and 21 percent in the fast group. Lean mass rose by about 2.1 percent in the slow group and did not change in the fast group, a significant difference. The authors concluded that athletes who want to gain lean mass and strength while losing weight should aim for about 0.7 percent of body weight a week.","token_count":194},{"ordinal":2,"section":"Practical reading and limits","header":"Source: Garthe et al. 2011, Effect of Two Different Weight-Loss Rates on Body Composition and Strength and Power-Related Performance in Elite Athletes. Section: Practical reading and limits.","body":"This supports the digest's guide of about 0.5 to 1 percent of body weight a week, with slower loss for leaner people. The groups were small, the athletes were elite and lifting regularly, and the slow group also dieted for longer. This summary is from the abstract only, so details such as the split of men and women are not given here. Tracend's reading: a slower cut is the safer default when keeping muscle and strength matters, and the plan's rules set the target.","token_count":165}]$lib$::jsonb
);

-- library-source: barakat_2020_recomposition sha256:87f8cca32b8c730df3d34dd0a3d3eae3d6cbc5c0db79a9fd05a2057b207cc234
select private.library_replace_source(
$lib${"slug":"barakat_2020_recomposition","title":"Body Recomposition: Can Trained Individuals Build Muscle and Lose Fat at the Same Time?","authors":["Barakat C","Pearson J","Escalante G","Campbell B","De Souza EO"],"year":2020,"doi":"10.1519/SSC.0000000000000584","url":"https://doi.org/10.1519/SSC.0000000000000584","licence":"CC-BY-NC-ND-4.0","region":["global"],"topics":["nutrition","recomposition","body-composition","protein","sleep","training"],"evidence_level":"narrative review","kind":"paper"}$lib$::jsonb,
$lib$[{"ordinal":0,"section":"What the review found","header":"Source: Barakat et al. 2020, Body Recomposition: Can Trained Individuals Build Muscle and Lose Fat at the Same Time?. Section: What the review found.","body":"The authors gathered randomised trials in resistance-trained people in which fat-free mass rose while fat mass fell over 4 to 10 weeks. This happened in powerlifters, recreational lifters, team-sport athletes and aspiring physique athletes, on a range of programmes. In several trials, high protein intakes (above 2 g per kg a day) went with more fat loss alongside muscle gain, even when the extra protein added calories. Starting with more body fat, returning after a break, and being newer to training made recomposition larger. Case studies of natural bodybuilders preparing for a contest mostly did not show it, probably because of the very large and long energy deficit.","token_count":207},{"ordinal":1,"section":"Sleep and measurement","header":"Source: Barakat et al. 2020, Body Recomposition: Can Trained Individuals Build Muscle and Lose Fat at the Same Time?. Section: Sleep and measurement.","body":"Short sleep is linked with losing more lean mass during weight loss (that evidence comes from overweight adults who were not lifting) and with worse training, and one small trial in untrained people found that sleep coaching helped fat loss. The review warns that body composition methods have errors of a size similar to many of the reported changes (DEXA has a typical error of about 1.6 percent body fat against MRI), so small recomposition results should be read with caution.","token_count":158},{"ordinal":2,"section":"Practical reading and limits","header":"Source: Barakat et al. 2020, Body Recomposition: Can Trained Individuals Build Muscle and Lose Fat at the Same Time?. Section: Practical reading and limits.","body":"The authors suggest progressive lifting at least three times a week, high protein (2.6 to 3.5 g per kg of fat-free mass a day), protein supplements if useful and good sleep. That protein range is per kg of fat-free mass and is above the digest's 1.4 to 2.0 g per kg of body weight; it rests on a few small trials. Tracend's reading: recomposition is realistic for trained people near maintenance, slower for lean, experienced lifters, and best judged by strength and measurements over months, not week-to-week scale changes.","token_count":171}]$lib$::jsonb
);

-- library-source: pinckaers_2021_plant_protein sha256:2b2d586401af01fc8fb4e8ac069d3dfd5b7cb6ed3011573a54ba38e816ce4230
select private.library_replace_source(
$lib${"slug":"pinckaers_2021_plant_protein","title":"The Anabolic Response to Plant-Based Protein Ingestion","authors":["Pinckaers PJM","Trommelen J","Snijders T","van Loon LJC"],"year":2021,"doi":"10.1007/s40279-021-01540-8","url":"https://doi.org/10.1007/s40279-021-01540-8","licence":"CC-BY-4.0","region":["global"],"topics":["nutrition","protein","plant-protein","vegetarian","hypertrophy"],"evidence_level":"narrative review","kind":"paper"}$lib$::jsonb,
$lib$[{"ordinal":0,"section":"Why plant protein can be weaker","header":"Source: Pinckaers et al. 2021, The Anabolic Response to Plant-Based Protein Ingestion. Section: Why plant protein can be weaker.","body":"Whole plant foods are digested less completely than animal foods: about 50 to 75 percent of the protein in chickpeas, mung beans and peas is absorbed, against about 85 to 95 percent for eggs and chicken, largely because of fibre and other compounds in the food. Isolated plant proteins (powders) absorb about as well as animal proteins. Most plant proteins also have less of the essential amino acids, especially leucine, and are often short of lysine or methionine. In the few direct comparisons, soy or wheat protein usually raised muscle protein building less than the same amount of whey or milk protein, though not in every study.","token_count":191},{"ordinal":1,"section":"How to close the gap","header":"Source: Pinckaers et al. 2021, The Anabolic Response to Plant-Based Protein Ingestion. Section: How to close the gap.","body":"Plant proteins vary widely: potato, corn, pea, canola and brown rice protein are relatively rich in essential amino acids or leucine. Three ways to compensate are eating more of the plant protein (for example, about 38 g of pea or 40 g of soy protein supplies the 2.7 g of leucine in about 25 g of whey), blending sources whose gaps cancel out (such as rice with pea or soy), and adding the missing amino acid. Training studies already show that supplementing soy, pea, rice or potato protein supports muscle gain.","token_count":158},{"ordinal":2,"section":"Practical reading and limits","header":"Source: Pinckaers et al. 2021, The Anabolic Response to Plant-Based Protein Ingestion. Section: Practical reading and limits.","body":"Most people who train eat enough protein that small quality differences matter little; the authors see the greater risk when energy and protein intake are low, as in a diet. Much of the evidence is short laboratory work with single proteins, not whole meals. Tracend's reading: a plant-based lifter does fine with a slightly higher protein target, varied sources and, if useful, a pea or soy powder, especially when cutting. Two authors have received funding from food companies, and the paper appeared in an industry-supported journal supplement.","token_count":169}]$lib$::jsonb
);

-- library-source: hevia_larrain_2021_vegan_protein sha256:d7695f77ee49939fe8d95110e6a0d0b222d8b237545db7654a02b3f663c497bf
select private.library_replace_source(
$lib${"slug":"hevia_larrain_2021_vegan_protein","title":"High-Protein Plant-Based Diet Versus a Protein-Matched Omnivorous Diet to Support Resistance Training Adaptations: A Comparison Between Habitual Vegans and Omnivores","authors":["Hevia-Larraín V","Gualano B","Longobardi I","Gil S","Fernandes AL","Costa LAR"],"year":2021,"doi":"10.1007/s40279-021-01434-9","url":"https://doi.org/10.1007/s40279-021-01434-9","licence":"proprietary","region":["global"],"topics":["nutrition","protein","plant-protein","vegetarian","hypertrophy","strength"],"evidence_level":"non-randomised controlled trial (38 untrained young men, 19 vegan, 19 omnivore)","kind":"paper"}$lib$::jsonb,
$lib$[{"ordinal":0,"section":"What the study did","header":"Source: Hevia-Larraín et al. 2021, High-Protein Plant-Based Diet Versus a Protein-Matched Omnivorous Diet to Support Resistance Training Adaptations: A Comparison Between Habitual Vegans and Omnivores. Section: What the study did.","body":"Nineteen young men who were habitual vegans and 19 who were omnivores, all healthy and of similar size, did 12 weeks of supervised resistance training twice a week. Each man's protein intake was brought up to about 1.6 g per kg a day with a supplement: soy protein for the vegans, whey for the omnivores. Diets were checked every four weeks. Leg lean mass, thigh muscle and muscle fibre size, and leg press strength were measured before and after.","token_count":170},{"ordinal":1,"section":"Findings","header":"Source: Hevia-Larraín et al. 2021, High-Protein Plant-Based Diet Versus a Protein-Matched Omnivorous Diet to Support Resistance Training Adaptations: A Comparison Between Habitual Vegans and Omnivores. Section: Findings.","body":"Both groups improved on every measure: leg lean mass rose by about 1.2 kg in each group, thigh muscle cross-sectional area and fibre size grew, and leg press strength rose by about 97 kg in the vegans and 117 kg in the omnivores. None of the differences between the groups were statistically significant. The authors concluded that, with enough protein, the source (plant foods plus soy, or mixed foods plus whey) did not change muscle or strength gains in untrained young men.","token_count":175},{"ordinal":2,"section":"Practical reading and limits","header":"Source: Hevia-Larraín et al. 2021, High-Protein Plant-Based Diet Versus a Protein-Matched Omnivorous Diet to Support Resistance Training Adaptations: A Comparison Between Habitual Vegans and Omnivores. Section: Practical reading and limits.","body":"The men were untrained, so they would gain readily on almost any sensible plan, and they ate a fairly high protein intake that included a soy isolate. The groups were not randomised (they were defined by existing diet), the study was small, and no women took part. This summary is from the abstract only. It agrees with the Pinckaers 2021 entry that enough total protein covers most of the difference. Tracend's reading: a vegan lifter who reaches the plan's protein target can expect similar progress; the plan's rules set the number.","token_count":194}]$lib$::jsonb
);

-- library-source: maughan_2018_ioc_supplements sha256:3b2ec83573fc7c17802d437b6d4e9ea4ca59c87a77d9db20c1889fbfd6a4e055
select private.library_replace_source(
$lib${"slug":"maughan_2018_ioc_supplements","title":"IOC consensus statement: dietary supplements and the high-performance athlete","authors":["Maughan RJ","Burke LM","Dvorak J","Larson-Meyer DE","Peeling P","Phillips SM"],"year":2018,"doi":"10.1136/bjsports-2018-099027","url":"https://doi.org/10.1136/bjsports-2018-099027","licence":"CC-BY-NC-4.0","region":["global"],"topics":["nutrition","supplements","safety","performance","creatine","caffeine","nitrate","beta-alanine"],"evidence_level":"expert consensus statement","kind":"guideline"}$lib$::jsonb,
$lib$[{"ordinal":0,"section":"Where supplements fit","header":"Source: Maughan et al. 2018 (IOC), IOC consensus statement: dietary supplements and the high-performance athlete. Section: Where supplements fit.","body":"An International Olympic Committee expert panel sees supplements as at most a small addition to a sound diet. They can correct a deficiency (iron, calcium and vitamin D are the usual ones, and vitamin B12 for vegans), provide energy and nutrients conveniently (sports drinks, gels, bars, protein), or claim to improve performance directly or indirectly. The panel says to check diet, history and, where useful, blood markers first, ideally with a sports nutrition professional, before choosing any supplement.","token_count":164},{"ordinal":1,"section":"What has good evidence","header":"Source: Maughan et al. 2018 (IOC), IOC consensus statement: dietary supplements and the high-performance athlete. Section: What has good evidence.","body":"Only a handful of performance supplements are backed well enough to be worth considering, and even then the gains are small: caffeine, creatine monohydrate, nitrate, sodium bicarbonate and possibly beta-alanine. Responses vary widely between people, so anything used for competition should be tried in training first. Caffeine usually gives its full benefit at 3 to 6 mg per kg, and side effects become more common at 9 mg per kg or more. Protein helps lean mass gain alongside resistance training. For most products sold as fat burners there is no evidence at all, and high doses of single antioxidants such as vitamins C and E may blunt training adaptations.","token_count":202},{"ordinal":2,"section":"Risks and contamination","header":"Source: Maughan et al. 2018 (IOC), IOC consensus statement: dietary supplements and the high-performance athlete. Section: Risks and contamination.","body":"In most countries supplements are regulated like foods, so makers need not prove that claims are true, that products are safe, or that labels match contents. Products have contained undeclared stimulants, anabolic steroids, SARMs, diuretics and other banned drugs, sometimes at medicinal doses; an early survey found undeclared steroid precursors in about 15 percent of over 600 products. Under anti-doping rules an athlete is responsible even for an unknowing intake, and traces too small to have any effect can still give a positive test. Third-party testing schemes reduce but cannot remove this risk.","token_count":188},{"ordinal":3,"section":"Practical reading and limits","header":"Source: Maughan et al. 2018 (IOC), IOC consensus statement: dietary supplements and the high-performance athlete. Section: Practical reading and limits.","body":"Written for elite athletes, but the principles suit any lifter: food, training and sleep come first, very few products add anything, and none is required. Anyone competing in a drug-tested sport should use only third-party tested products, if any. The doses in the statement's tables are not reproduced here; see the Kreider 2017, Guest 2021, Trexler 2015 and Senefeld 2020 entries.","token_count":134}]$lib$::jsonb
);

-- library-source: antonio_2021_creatine_questions sha256:3d1d4299e9067d92acd1c4b6662ebcc95744b92d9e68be538f48d586687b5bed
select private.library_replace_source(
$lib${"slug":"antonio_2021_creatine_questions","title":"Common questions and misconceptions about creatine supplementation: what does the scientific evidence really show?","authors":["Antonio J","Candow DG","Forbes SC","Gualano B","Jagim AR","Kreider RB"],"year":2021,"doi":"10.1186/s12970-021-00412-w","url":"https://doi.org/10.1186/s12970-021-00412-w","licence":"CC-BY-4.0","region":["global"],"topics":["nutrition","creatine","supplements","safety","women","older-adults"],"evidence_level":"expert review of published trials","kind":"paper"}$lib$::jsonb,
$lib$[{"ordinal":0,"section":"Common worries","header":"Source: Antonio et al. 2021, Common questions and misconceptions about creatine supplementation: what does the scientific evidence really show?. Section: Common worries.","body":"A panel of creatine researchers answered frequent questions. Water: loading at about 20 g a day usually adds 1 to 3 kg in the first days, mostly water, but longer studies mostly show no change in body water relative to muscle. Creatine is not an anabolic steroid. Kidneys: in healthy people, recommended doses have not harmed kidney function, though creatine (like meat) can raise creatinine on blood tests without meaning damage. Hair loss: the idea comes from one study of rugby players whose DHT rose within normal limits; it has not been repeated and no study has reported hair loss. Cramping and dehydration are not supported; a season-long study of college football players in hot conditions found fewer cramps in creatine users. Creatine does not increase fat mass.","token_count":236},{"ordinal":1,"section":"Dosing and forms","header":"Source: Antonio et al. 2021, Common questions and misconceptions about creatine supplementation: what does the scientific evidence really show?. Section: Dosing and forms.","body":"Loading is optional. Either 20 to 25 g a day for 5 to 7 days in servings of 10 g or less (larger servings can upset the gut), then 3 to 5 g a day, or simply 3 to 5 g a day (about 0.1 g per kg), which reaches similar muscle levels after about 4 weeks. Creatine monohydrate remains the best supported form; other forms have not proved superior. Creatine breaks down in liquids, so ready-made drinks carry little. Benefits are reported in women and, mainly when combined with resistance training, in older adults.","token_count":171},{"ordinal":2,"section":"Practical reading and limits","header":"Source: Antonio et al. 2021, Common questions and misconceptions about creatine supplementation: what does the scientific evidence really show?. Section: Practical reading and limits.","body":"Most authors have financial ties to the creatine industry, including advisory roles with a creatine manufacturer, so this should be read alongside independent sources such as the Maughan 2018 IOC entry, which also rates creatine as well supported. The sections on children and pregnancy are outside Tracend's scope and are not summarised. Tracend's reading: creatine is optional, low risk for healthy adults at 3 to 5 g a day, and anyone having blood tests can mention it to their clinician.","token_count":169}]$lib$::jsonb
);

-- library-source: kaviani_2020_creatine_vegetarians sha256:1eed910bd6856bbf97fc57dd3749a1740e9fc567a2217035c7cde94240c9eea4
select private.library_replace_source(
$lib${"slug":"kaviani_2020_creatine_vegetarians","title":"Benefits of Creatine Supplementation for Vegetarians Compared to Omnivorous Athletes: A Systematic Review","authors":["Kaviani M","Shaw K","Chilibeck PD"],"year":2020,"doi":"10.3390/ijerph17093041","url":"https://doi.org/10.3390/ijerph17093041","licence":"CC-BY-4.0","region":["global"],"topics":["nutrition","creatine","supplements","vegetarian","plant-protein","strength"],"evidence_level":"systematic review (9 studies in 11 papers)","kind":"paper"}$lib$::jsonb,
$lib$[{"ordinal":0,"section":"Why vegetarians differ","header":"Source: Kaviani et al. 2020, Benefits of Creatine Supplementation for Vegetarians Compared to Omnivorous Athletes: A Systematic Review. Section: Why vegetarians differ.","body":"The body makes about 1 g of creatine a day and meat eaters get roughly another gram from food; vegans get almost none. Studies find creatine about 50 percent lower in the plasma of vegetarians and total creatine about 10 to 15 percent lower in thigh muscle, though not lower in the brain or calf muscle. The reviewers searched two databases up to April 2020 and included 9 studies of creatine supplements in vegetarians.","token_count":148},{"ordinal":1,"section":"Findings","header":"Source: Kaviani et al. 2020, Benefits of Creatine Supplementation for Vegetarians Compared to Omnivorous Athletes: A Systematic Review. Section: Findings.","body":"Supplements raised creatine in vegetarians' muscle and blood, often to higher levels than in omnivores given the same dose. In vegetarians they improved lean tissue mass, type II fibre size, strength, muscular endurance, sprint cycling power and, in two studies, memory. Whether vegetarians gain more than omnivores was mixed: the one trial in recreational athletes, which added a resistance training programme of about two months, found greater lean mass and work gains in the vegetarians, while short sprint studies did not. In one trial of women who switched to a vegetarian diet, just 1 g a day kept muscle creatine from falling over three months, while it fell about 15 percent on placebo. Most creatine is made synthetically, so it suits vegans, though capsules may contain gelatin.","token_count":236},{"ordinal":2,"section":"Practical reading and limits","header":"Source: Kaviani et al. 2020, Benefits of Creatine Supplementation for Vegetarians Compared to Omnivorous Athletes: A Systematic Review. Section: Practical reading and limits.","body":"Most studies were small, short and in non-athletes, and most carried some or high risk of bias. Tracend's reading: for vegetarian and vegan lifters creatine has a clearer reason than most supplements, at the usual 3 to 5 g a day (see the Antonio 2021 entry), but it remains optional, not a requirement of a plant-based diet.","token_count":125}]$lib$::jsonb
);

-- library-source: trexler_2015_beta_alanine sha256:97a9692c726877698f377e56d25beb6981f11a55c44eeab3138596a2d9ed349e
select private.library_replace_source(
$lib${"slug":"trexler_2015_beta_alanine","title":"International society of sports nutrition position stand: Beta-Alanine","authors":["Trexler ET","Smith-Ryan AE","Stout JR","Hoffman JR","Wilborn CD","Sale C"],"year":2015,"doi":"10.1186/s12970-015-0090-y","url":"https://doi.org/10.1186/s12970-015-0090-y","licence":"CC-BY-4.0","region":["global"],"topics":["nutrition","supplements","beta-alanine","performance","safety"],"evidence_level":"position stand","kind":"position_stand"}$lib$::jsonb,
$lib$[{"ordinal":0,"section":"How it works and how it is taken","header":"Source: Trexler et al. 2015 (ISSN), International society of sports nutrition position stand: Beta-Alanine. Section: How it works and how it is taken.","body":"Beta-alanine raises muscle carnosine, which buffers the acid that builds up in hard efforts. It works by build-up, not on the day: 4 to 6 g a day, split into doses of 2 g or less, raises carnosine by about 20 to 30 percent after 2 weeks and about 40 to 60 percent after 4. Taking it with meals may help. Levels take about 6 to 15 weeks to fall back after stopping. A single 2 to 4 g serving in a pre-workout drink is therefore unlikely to explain any effect felt that day.","token_count":156},{"ordinal":1,"section":"What it helps","header":"Source: Trexler et al. 2015 (ISSN), International society of sports nutrition position stand: Beta-Alanine. Section: What it helps.","body":"Benefits are clearest in continuous high-intensity efforts lasting about 1 to 4 minutes, especially tests to exhaustion, with smaller effects in time trials and little or none in efforts under a minute. Modest benefits appear up to about 25 minutes, with no consistent effect beyond. In resistance training it may allow a little more volume and less fatigue, but no added strength gain has been shown. Adding it to creatine or sodium bicarbonate may give a small extra benefit.","token_count":153},{"ordinal":2,"section":"Safety","header":"Source: Trexler et al. 2015 (ISSN), International society of sports nutrition position stand: Beta-Alanine. Section: Safety.","body":"The only reported side effect is tingling of the skin, mostly on the face, neck and hands, after single doses above about 800 mg; it is harmless and fades within 60 to 90 minutes. Splitting the dose (for example 1.6 g at a time) or using a sustained-release form reduces it. It appears safe in healthy people at recommended doses, but there are no safety data beyond one year.","token_count":126},{"ordinal":3,"section":"Practical reading and limits","header":"Source: Trexler et al. 2015 (ISSN), International society of sports nutrition position stand: Beta-Alanine. Section: Practical reading and limits.","body":"Most relevant to sustained hard efforts such as high-repetition sets, intervals or a 2,000 metre row; of little use for heavy, low-repetition strength work. Tracend's reading: optional, worth it only for someone who wants a small edge in those efforts and accepts the tingle.","token_count":106}]$lib$::jsonb
);

-- library-source: senefeld_2020_nitrate sha256:344cf97e520c5f82a32c6505c7ddc773c28ba5e37e4af5b880bae2859c8d55e8
select private.library_replace_source(
$lib${"slug":"senefeld_2020_nitrate","title":"Ergogenic Effect of Nitrate Supplementation: A Systematic Review and Meta-analysis","authors":["Senefeld JW","Wiggins CC","Regimbal RJ","Dominelli PB","Baker SE","Joyner MJ"],"year":2020,"doi":"10.1249/mss.0000000000002363","url":"https://doi.org/10.1249/mss.0000000000002363","licence":"CC-BY-NC-ND-4.0","region":["global"],"topics":["nutrition","supplements","nitrate","performance","cardio","sex-differences"],"evidence_level":"systematic review and meta-analysis (80 crossover trials, about 1,300 adults)","kind":"paper"}$lib$::jsonb,
$lib$[{"ordinal":0,"section":"What the review did","header":"Source: Senefeld et al. 2020, Ergogenic Effect of Nitrate Supplementation: A Systematic Review and Meta-analysis. Section: What the review did.","body":"The authors pooled 80 placebo-controlled crossover studies of dietary nitrate (mostly beetroot juice) in healthy adults aged 18 to 40, with 1,179 men and 156 women, published from 2009 to 2019. Doses ranged widely, taken 1 to 15 days, and performance was measured in time trials, tests to exhaustion and fatigue tests, mostly in cycling and running.","token_count":124},{"ordinal":1,"section":"Findings","header":"Source: Senefeld et al. 2020, Ergogenic Effect of Nitrate Supplementation: A Systematic Review and Meta-analysis. Section: Findings.","body":"Nitrate improved performance overall, but the effect was small (effect size about 0.17), which is why about two thirds of single studies found no difference; none found harm. The benefit was seen in recreationally active and moderately fit people but not in highly fit endurance athletes (VO2max above about 65 ml per kg per minute), and was larger in tests to exhaustion than in time trials and in efforts under about 15 minutes. Studies of women alone showed no effect, but there were only six, so the question is open. No benefit was seen at 5 mmol a day or less; doses of about 5 to 25 mmol taken 2 to 3.5 hours before exercise worked best, and one day was enough.","token_count":201},{"ordinal":2,"section":"Practical reading and limits","header":"Source: Senefeld et al. 2020, Ergogenic Effect of Nitrate Supplementation: A Systematic Review and Meta-analysis. Section: Practical reading and limits.","body":"The authors put the typical gain at about 3 percent in a race-like test, meaningful for competition but easy to miss day to day. Nitrate is turned into its active form by mouth bacteria, and only about half the studies reported asking people to avoid antibacterial mouthwash and chewing gum, which may add to the variation. Little of the evidence concerns lifting. Tracend's reading: an optional food-based aid for endurance or repeated hard efforts in recreational athletes; leafy greens and beetroot supply nitrate anyway, and the NIH ODS 2024 entry covers its safety.","token_count":181}]$lib$::jsonb
);

-- library-source: wolfe_2017_bcaa sha256:b3a419a0252a527b673c425f9fa1d2c91eb72aee8165a8601c1e7c331f88b96f
select private.library_replace_source(
$lib${"slug":"wolfe_2017_bcaa","title":"Branched-chain amino acids and muscle protein synthesis in humans: myth or reality?","authors":["Wolfe RR"],"year":2017,"doi":"10.1186/s12970-017-0184-9","url":"https://doi.org/10.1186/s12970-017-0184-9","licence":"CC-BY-4.0","region":["global"],"topics":["nutrition","supplements","protein","hypertrophy"],"evidence_level":"narrative review","kind":"paper"}$lib$::jsonb,
$lib$[{"ordinal":0,"section":"The argument","header":"Source: Wolfe 2017, Branched-chain amino acids and muscle protein synthesis in humans: myth or reality?. Section: The argument.","body":"Branched-chain amino acids (leucine, isoleucine and valine) are three of the nine essential amino acids, and building new muscle protein needs all nine. Between meals, muscle breaks down protein about 30 percent faster than it builds it, and the only source of the other six essential amino acids is that breakdown. So BCAAs alone can at best help recycle amino acids more efficiently; the author estimates a ceiling of about a 15 percent rise in muscle protein building, never a net gain of muscle.","token_count":157},{"ordinal":1,"section":"The human evidence","header":"Source: Wolfe 2017, Branched-chain amino acids and muscle protein synthesis in humans: myth or reality?. Section: The human evidence.","body":"The author found no human study measuring muscle protein building after drinking BCAAs alone. Two small studies infused BCAAs into a vein, for 3 hours in 10 people and 16 hours in 8. In both, muscle protein building fell rather than rose, along with breakdown, and muscle stayed in net loss. Signals inside muscle that switch on protein building do not raise it when the other essential amino acids are missing. Things differ with protein: adding 5 g of BCAAs to a small 6.25 g serving of whey raised protein building to about the level of 25 g of whey.","token_count":172},{"ordinal":2,"section":"Practical reading and limits","header":"Source: Wolfe 2017, Branched-chain amino acids and muscle protein synthesis in humans: myth or reality?. Section: Practical reading and limits.","body":"This is one author's analysis of mostly theoretical and short-term evidence, not a trial of long-term muscle growth, and the author declares funding from food companies and shares in a nutrition company. The NIH ODS 2024 entry notes a few short studies in which 10 to 14 g a day went with greater gains, but judges the evidence inconsistent overall. Tracend's reading: for someone already eating enough protein, BCAAs add little; money is better spent on complete protein from food or a protein powder.","token_count":162}]$lib$::jsonb
);

-- library-source: nih_ods_2024_exercise_supplements sha256:7069cb31672831f77cbeefd948e1a686561d01e8b5591f1b64ef068a0929c64a
select private.library_replace_source(
$lib${"slug":"nih_ods_2024_exercise_supplements","title":"Dietary Supplements for Exercise and Athletic Performance - Health Professional Fact Sheet","authors":["NIH Office of Dietary Supplements"],"year":2024,"doi":null,"url":"https://ods.od.nih.gov/factsheets/ExerciseAndAthleticPerformance-HealthProfessional/","licence":"public-domain-us-gov","region":["global"],"topics":["nutrition","supplements","safety","performance","guidelines"],"evidence_level":"government fact sheet summarising published research","kind":"summary"}$lib$::jsonb,
$lib$[{"ordinal":0,"section":"The overall message","header":"Source: NIH ODS 2024, Dietary Supplements for Exercise and Athletic Performance - Health Professional Fact Sheet. Section: The overall message.","body":"The US National Institutes of Health fact sheet (updated April 2024) says a nutritionally adequate diet and enough fluid come first, and a few supplements might help only on top of that. Most studies are small and short, in young, mostly male, well-conditioned athletes, so benefits for recreational exercisers are often unclear. Multi-ingredient products and proprietary blends have rarely been tested as sold, and sellers rarely fund research of publishable quality.","token_count":153},{"ordinal":1,"section":"Ingredients with little or no support","header":"Source: NIH ODS 2024, Dietary Supplements for Exercise and Athletic Performance - Health Professional Fact Sheet. Section: Ingredients with little or no support.","body":"The sheet finds little or no support for arginine (2 to 20 g a day had little or no effect), citrulline, glutamine, ribose, DHEA, tribulus and deer antler velvet, and no expert consensus for HMB or tart cherry. For BCAAs, a few short studies of 10 to 14 g a day hint at extra gains, but overall they have not consistently improved performance, muscle or recovery beyond enough complete protein. DHEA and the IGF-1 in deer antler velvet are banned in tested sport, and claimed testosterone boosters carry a high contamination risk.","token_count":173},{"ordinal":2,"section":"Regulation and safety","header":"Source: NIH ODS 2024, Dietary Supplements for Exercise and Athletic Performance - Health Professional Fact Sheet. Section: Regulation and safety.","body":"In the US, supplements need no approval before sale, and makers are responsible for safety and truthful labels. Bodybuilding products are among those most often found to contain undeclared steroids, SARMs or prescription drugs, which can harm health and cause failed drug tests. Third-party certification (NSF Certified for Sport, Informed-Choice, BSCG) gives some independent assurance. Some ingredients interact with medicines, so anyone on regular medication should check with a clinician or pharmacist. Beetroot juice of about two cups a day for several weeks raised no safety concerns.","token_count":184},{"ordinal":3,"section":"Practical reading and limits","header":"Source: NIH ODS 2024, Dietary Supplements for Exercise and Athletic Performance - Health Professional Fact Sheet. Section: Practical reading and limits.","body":"A US federal work in the public domain, so short quotation with attribution is allowed. Its regulatory details are American; the science applies elsewhere. Tracend's reading: Coach can explain what an ingredient is claimed to do and what the evidence shows, but never recommends one as necessary.","token_count":113}]$lib$::jsonb
);

-- library-source: wewege_2017_hiit_body_composition sha256:54ad4d77c6ceb40ab4431db111c9c98839b32f6c1b22818823e65038a7adaf46
select private.library_replace_source(
$lib${"slug":"wewege_2017_hiit_body_composition","title":"The effects of high-intensity interval training vs. moderate-intensity continuous training on body composition in overweight and obese adults: a systematic review and meta-analysis","authors":["Wewege M","van den Berg R","Ward RE","Keech A"],"year":2017,"doi":"10.1111/obr.12532","url":"https://doi.org/10.1111/obr.12532","licence":"proprietary","region":["global"],"topics":["cardio","hiit","fat-loss","body-composition","time-efficient"],"evidence_level":"systematic review and meta-analysis (13 trials)","kind":"paper"}$lib$::jsonb,
$lib$[{"ordinal":0,"section":"What the review did","header":"Source: Wewege et al. 2017, The effects of high-intensity interval training vs. moderate-intensity continuous training on body composition in overweight and obese adults: a systematic review and meta-analysis. Section: What the review did.","body":"The authors pooled 13 trials that compared high-intensity interval training (HIIT) with moderate-intensity continuous training, such as steady jogging or cycling, in overweight or obese adults aged 18 to 45. Training lasted about 10 weeks on average, at roughly three sessions a week. They looked at direct measures of body fat, such as whole-body fat mass, and indirect ones, such as waist circumference.","token_count":162},{"ordinal":1,"section":"Findings","header":"Source: Wewege et al. 2017, The effects of high-intensity interval training vs. moderate-intensity continuous training on body composition in overweight and obese adults: a systematic review and meta-analysis. Section: Findings.","body":"Both kinds of training reduced whole-body fat mass and waist circumference, and no body-composition measure differed between them. The interval programmes needed about 40 percent less training time. When the trials were split by exercise type, running-based training produced large reductions in fat mass for both styles, while cycling-based training did not reduce fat in these studies.\n\nThe authors note that the body-composition changes were modest and happened without much change in body weight.","token_count":183},{"ordinal":2,"section":"Practical reading and limits","header":"Source: Wewege et al. 2017, The effects of high-intensity interval training vs. moderate-intensity continuous training on body composition in overweight and obese adults: a systematic review and meta-analysis. Section: Practical reading and limits.","body":"Interval and steady cardio did about the same job for fat loss here, so the choice can rest on preference, joints and time available: intervals are a time saver, not a shortcut. Fat can fall while scale weight barely moves, which is worth explaining to someone discouraged by the scale. The trials were short and in younger overweight adults, the running versus cycling split is a subgroup finding, and this summary is from the abstract only. Diet and energy balance still drive most fat loss. A later, widely shared meta-analysis claiming larger fat loss from intervals (Viana 2019) was retracted, so it is not in this library.","token_count":220}]$lib$::jsonb
);

-- library-source: milanovic_2015_hiit_vo2max sha256:20fc6f5c6992e310634dadf6fa85a192654204dfd66d893dffb9933134f86f79
select private.library_replace_source(
$lib${"slug":"milanovic_2015_hiit_vo2max","title":"Effectiveness of high-intensity interval training (HIT) and continuous endurance training for VO2max improvements: a systematic review and meta-analysis of controlled trials","authors":["Milanović Z","Sporiš G","Weston M"],"year":2015,"doi":"10.1007/s40279-015-0365-0","url":"https://doi.org/10.1007/s40279-015-0365-0","licence":"proprietary","region":["global"],"topics":["cardio","hiit","vo2max","cardio-fitness","intensity"],"evidence_level":"systematic review and meta-analysis (28 controlled trials, 723 adults)","kind":"paper"}$lib$::jsonb,
$lib$[{"ordinal":0,"section":"What the review did","header":"Source: Milanović et al. 2015, Effectiveness of high-intensity interval training (HIT) and continuous endurance training for VO2max improvements: a systematic review and meta-analysis of controlled trials. Section: What the review did.","body":"The authors pooled 28 controlled trials with 723 healthy adults aged 18 to 45 (average age about 25, average starting VO2max about 41 mL per kg per minute). Programmes lasted at least two weeks and measured VO2max, the maximum rate at which the body can use oxygen, before and after. They compared continuous endurance training and high-intensity interval training (HIT) with no exercise, and with each other.","token_count":162},{"ordinal":1,"section":"Findings","header":"Source: Milanović et al. 2015, Effectiveness of high-intensity interval training (HIT) and continuous endurance training for VO2max improvements: a systematic review and meta-analysis of controlled trials. Section: Findings.","body":"Against no exercise, continuous endurance training raised VO2max by about 4.9 mL per kg per minute and interval training by about 5.5, both large improvements. Gains tended to be bigger in people who started less fit and in longer programmes.\n\nCompared head to head, interval training came out slightly ahead, by about 1.2 mL per kg per minute, a possibly small benefit. The edge was a little larger with longer intervals, a higher work to rest ratio, longer programmes, older participants and lower starting fitness.","token_count":186},{"ordinal":2,"section":"Practical reading and limits","header":"Source: Milanović et al. 2015, Effectiveness of high-intensity interval training (HIT) and continuous endurance training for VO2max improvements: a systematic review and meta-analysis of controlled trials. Section: Practical reading and limits.","body":"Both styles build aerobic fitness well, and intervals give a modest extra lift for the time spent, so a mix that the person enjoys and can recover from is a sensible default. The studies were of young adults of about average starting fitness over short periods. The authors rated the head-to-head advantage only as possibly small, so it should be read as uncertain. This summary is from the abstract only. VO2max is one fitness marker; it does not by itself show health outcomes (see the Mandsager 2018 entry for the link between fitness and survival).","token_count":200}]$lib$::jsonb
);

-- library-source: mandsager_2018_cardiorespiratory_fitness_mortality sha256:4485061dddd66758fd00f51e031c1f766f187140ea1af4926ec168eaf48fce3b
select private.library_replace_source(
$lib${"slug":"mandsager_2018_cardiorespiratory_fitness_mortality","title":"Association of cardiorespiratory fitness with long-term mortality among adults undergoing exercise treadmill testing","authors":["Mandsager K","Harb S","Cremer P","Phelan D","Nissen SE","Jaber W"],"year":2018,"doi":"10.1001/jamanetworkopen.2018.3605","url":"https://doi.org/10.1001/jamanetworkopen.2018.3605","licence":"CC-BY-4.0","region":["global"],"topics":["cardio-fitness","vo2max","health","cardio","older-adults"],"evidence_level":"retrospective cohort study (122,007 adults; observational)","kind":"paper"}$lib$::jsonb,
$lib$[{"ordinal":0,"section":"What the study did","header":"Source: Mandsager et al. 2018, Association of cardiorespiratory fitness with long-term mortality among adults undergoing exercise treadmill testing. Section: What the study did.","body":"Researchers at one US academic medical centre looked back at 122,007 adults (average age 53, 59 percent men) who did a symptom-limited treadmill test between 1991 and 2014. Fitness was estimated from the peak workload reached and ranked against people of the same age and sex: low (bottom quarter), below average, above average, high, and elite (top 2.3 percent). Deaths from any cause were tracked for a median of 8.4 years, and 13,637 people died. The analysis adjusted for age, sex, body mass index, heart disease, diabetes, smoking, other conditions and medicines.","token_count":187},{"ordinal":1,"section":"Findings","header":"Source: Mandsager et al. 2018, Association of cardiorespiratory fitness with long-term mortality among adults undergoing exercise treadmill testing. Section: Findings.","body":"Each step up in fitness went with lower risk of death, with no point where the benefit stopped. Compared with the least fit group, the elite group had about one fifth of the adjusted risk. Being in the least fit group carried a risk similar to or larger than smoking, diabetes or known coronary disease. Elite fitness was linked with lower risk than high fitness overall, and this difference held in people aged 70 and over and in those with high blood pressure, but not in younger groups.","token_count":165},{"ordinal":2,"section":"Practical reading and limits","header":"Source: Mandsager et al. 2018, Association of cardiorespiratory fitness with long-term mortality among adults undergoing exercise treadmill testing. Section: Practical reading and limits.","body":"This is an association, not proof that getting fitter causes longer life: fitter people may differ in genes, habits and health in ways the study could not measure, as the authors say. Participants were people referred for a clinical treadmill test, not a random sample of the public, and fitness was measured once. Coach can use it to explain that aerobic fitness is a strong, changeable health marker and that moving up from low fitness is linked with the biggest change, without promising a longer life or a specific risk reduction to any individual.","token_count":185}]$lib$::jsonb
);

-- library-source: roberts_2015_cold_water_strength_adaptation sha256:f657de7f2f87f91a748ba6e329ea0a956368baf742abc106f4976a7087c196c4
select private.library_replace_source(
$lib${"slug":"roberts_2015_cold_water_strength_adaptation","title":"Post-exercise cold water immersion attenuates acute anabolic signalling and long-term adaptations in muscle to strength training","authors":["Roberts LA","Raastad T","Markworth JF","Figueiredo VC","Egner IM","Shield A"],"year":2015,"doi":"10.1113/JP270570","url":"https://doi.org/10.1113/JP270570","licence":"proprietary","region":["global"],"topics":["cold-water-immersion","recovery","hypertrophy","strength","training"],"evidence_level":"randomised controlled trial (21 men) plus a mechanistic crossover study (9 men)","kind":"paper"}$lib$::jsonb,
$lib$[{"ordinal":0,"section":"What the study did","header":"Source: Roberts et al. 2015, Post-exercise cold water immersion attenuates acute anabolic signalling and long-term adaptations in muscle to strength training. Section: What the study did.","body":"The paper reports two studies. In the training study, 21 physically active men with at least a year of strength-training experience did mainly lower-body lifting twice a week for 12 weeks and spent 10 minutes after every session either sitting waist-deep in water at about 10 °C or cycling easily. In the mechanistic study, nine active men did single-leg strength exercise on separate days followed by either cold water or active recovery, with muscle samples taken before and 2, 24 and 48 hours after.","token_count":173},{"ordinal":1,"section":"Findings","header":"Source: Roberts et al. 2015, Post-exercise cold water immersion attenuates acute anabolic signalling and long-term adaptations in muscle to strength training. Section: Findings.","body":"Strength and muscle mass rose more with active recovery than with cold water. In the active recovery group, isokinetic work rose by about 19 percent, the size of fast-twitch (type II) fibres by about 17 percent and the number of nuclei per fibre by about 26 percent; none of these rose significantly with cold water.\n\nIn the muscle samples, markers of satellite cells (the stem cells that help muscle grow and repair) and of a key growth signalling enzyme rose less after cold water than after active recovery. The authors suggest that regular cold water after lifting may blunt the processes behind long-term gains, so it may be worth dropping as an after-every-session habit.","token_count":214},{"ordinal":2,"section":"Practical reading and limits","header":"Source: Roberts et al. 2015, Post-exercise cold water immersion attenuates acute anabolic signalling and long-term adaptations in muscle to strength training. Section: Practical reading and limits.","body":"For someone whose goal is strength or muscle, plunging after every lifting session may cost some of the gains, so it is better kept for times when feeling fresh soon matters more than adaptation. The trial was small, only young men took part, the water was about 10 °C up to the waist, and training was mainly lower body. Later work found the strength cost is small and may be limited to immersing only the trained limbs (Fyfe 2019; Grgic 2022 meta-analysis). It does not say cold water is harmful in general: the Dupuy 2018 entry shows it can ease soreness for a day or two, and the Malta 2021 entry pools the training studies.","token_count":207}]$lib$::jsonb
);

-- library-source: malta_2021_cold_water_training_adaptations sha256:35388c8f8c530c395f368819ce520932e90f1ace1b31f3abffe90a83c5495a45
select private.library_replace_source(
$lib${"slug":"malta_2021_cold_water_training_adaptations","title":"The effects of regular cold-water immersion use on training-induced changes in strength and endurance performance: a systematic review with meta-analysis","authors":["Malta ES","Dutra YM","Broatch JR","Bishop DJ","Zagatto AM"],"year":2021,"doi":"10.1007/s40279-020-01362-0","url":"https://doi.org/10.1007/s40279-020-01362-0","licence":"proprietary","region":["global"],"topics":["cold-water-immersion","recovery","strength","cardio","training"],"evidence_level":"systematic review and meta-analysis (8 studies)","kind":"paper"}$lib$::jsonb,
$lib$[{"ordinal":0,"section":"What the review did","header":"Source: Malta et al. 2021, The effects of regular cold-water immersion use on training-induced changes in strength and endurance performance: a systematic review with meta-analysis. Section: What the review did.","body":"The authors searched three databases to November 2019 for controlled human studies in which people used cold-water immersion at 15 degrees C or colder regularly alongside a training programme, with performance tested before and after. Eight studies were included, covering both resistance training and endurance training.","token_count":134},{"ordinal":1,"section":"Findings","header":"Source: Malta et al. 2021, The effects of regular cold-water immersion use on training-induced changes in strength and endurance performance: a systematic review with meta-analysis. Section: Findings.","body":"With resistance training, regular cold-water immersion reduced gains in one-repetition maximum, maximal isometric strength and strength endurance (pooled standardised difference about minus 0.6, a moderate effect), and also in ballistic, explosive efforts by a similar amount.\n\nWith endurance training, it made no clear difference to maximal aerobic power in a graded test or to time-trial performance. In short, regular cold water after lifting cost some strength gains, while endurance results were unchanged.","token_count":178},{"ordinal":2,"section":"Practical reading and limits","header":"Source: Malta et al. 2021, The effects of regular cold-water immersion use on training-induced changes in strength and endurance performance: a systematic review with meta-analysis. Section: Practical reading and limits.","body":"This sits alongside the Dupuy 2018 entry, which found cold and other methods ease soreness for a day or two: both can be true. Cold water may help someone feel better between closely spaced sessions or events, but used after most lifting sessions it can cost strength. For endurance work it looks roughly neutral. Only eight studies were pooled. A later meta-analysis of ten studies (Grgic 2022) found a smaller cost to strength, and no clear cost when the whole body rather than only the trained limbs was immersed, so the size of the effect is uncertain. The summary is from the abstract only, and the paper does not test occasional use or brief cold showers. Coach should present cold water as optional and timed to the goal, not as a recovery requirement.","token_count":245}]$lib$::jsonb
);

-- library-source: craven_2022_sleep_loss_performance sha256:fe06d3f617c3510df8598d7be54fb5b7a5cd30363d58c558d4c4b4062ab42628
select private.library_replace_source(
$lib${"slug":"craven_2022_sleep_loss_performance","title":"Effects of acute sleep loss on physical performance: a systematic and meta-analytical review","authors":["Craven J","McCartney D","Desbrow B","Sabapathy S","Bellinger P","Roberts L"],"year":2022,"doi":"10.1007/s40279-022-01706-y","url":"https://doi.org/10.1007/s40279-022-01706-y","licence":"CC-BY-4.0","region":["global"],"topics":["sleep-loss","sleep","performance","recovery","strength"],"evidence_level":"systematic review and meta-analysis (69 publications, 959 participants)","kind":"paper"}$lib$::jsonb,
$lib$[{"ordinal":0,"section":"What the review did","header":"Source: Craven et al. 2022, Effects of acute sleep loss on physical performance: a systematic and meta-analytical review. Section: What the review did.","body":"The authors pooled 69 publications (959 participants, 89 percent men) that compared exercise performance after normal sleep (more than 6 hours) with performance after sleep loss (6 hours or less in 24 hours). Sleep loss was split into total deprivation (no sleep), restriction, early restriction (going to bed late) and late restriction (waking early). Tasks covered strength, power, sprints, intervals, endurance and sport skills, 227 outcomes in all.","token_count":151},{"ordinal":1,"section":"Findings","header":"Source: Craven et al. 2022, Effects of acute sleep loss on physical performance: a systematic and meta-analytical review. Section: Findings.","body":"Overall, performance fell by about 7.6 percent after sleep loss, and every exercise type was affected: skill tasks the most (about 21 percent), then anaerobic power and interval work (about 6 percent), endurance (about 5.5 percent) and strength (about 3 percent). For strength, lower-body tasks suffered while upper-body tasks did not.\n\nTotal deprivation and waking early hurt consistently; going to bed late mostly did not, except for skill and endurance tasks. Performance dropped by roughly 0.4 percent for each extra hour awake before the task. Afternoon and evening sessions were consistently affected, while morning sessions were largely spared.","token_count":198},{"ordinal":2,"section":"Practical reading and limits","header":"Source: Craven et al. 2022, Effects of acute sleep loss on physical performance: a systematic and meta-analytical review. Section: Practical reading and limits.","body":"After a short night, a guide is to train earlier in the day if possible and to expect skill, power and heavy leg work to feel harder. When a short night cannot be avoided, the authors suggest that going to bed late beats waking very early, for example travelling the night before instead of at dawn. Results varied widely between studies, almost all participants were men, sleep quality and repeated short nights were not tested, and training status was not analysed. This is about one or two bad nights, not long-term sleep habits (see the Watson 2015 and Walsh 2021 entries).","token_count":185}]$lib$::jsonb
);

-- library-source: lamon_2021_sleep_deprivation_muscle_protein sha256:8542e25011b8e9406d9a8a8b0bc8e10ed0ad55917372808f5d6cadb7a0d013dc
select private.library_replace_source(
$lib${"slug":"lamon_2021_sleep_deprivation_muscle_protein","title":"The effect of acute sleep deprivation on skeletal muscle protein synthesis and the hormonal environment","authors":["Lamon S","Morabito A","Arentson-Lantz E","Knowles O","Vincent GE","Condo D"],"year":2021,"doi":"10.14814/phy2.14660","url":"https://doi.org/10.14814/phy2.14660","licence":"CC-BY-4.0","region":["global"],"topics":["sleep-loss","sleep","recovery","hypertrophy","protein"],"evidence_level":"randomised crossover trial (13 healthy young adults)","kind":"paper"}$lib$::jsonb,
$lib$[{"ordinal":0,"section":"What the study did","header":"Source: Lamon et al. 2021, The effect of acute sleep deprivation on skeletal muscle protein synthesis and the hormonal environment. Section: What the study did.","body":"Thirteen healthy young adults (seven men, six women) who normally slept at least seven hours each did two trials in random order, at least four weeks apart: one night of normal sleep at home and one night kept fully awake in a laboratory. Meals were standardised, no strenuous exercise was done, and the next day the researchers measured the rate of muscle protein synthesis after meals (from 13:00 to 15:00), hormone levels across the day and markers of muscle protein breakdown.","token_count":161},{"ordinal":1,"section":"Findings","header":"Source: Lamon et al. 2021, The effect of acute sleep deprivation on skeletal muscle protein synthesis and the hormonal environment. Section: Findings.","body":"After the sleepless night, muscle protein synthesis after eating was about 18 percent lower. Across the day, cortisol (a hormone that favours breakdown) was about 21 percent higher and testosterone about 24 percent lower. Gene markers of muscle protein breakdown did not change.\n\nAll the men, but not all the women, showed lower protein synthesis after the sleepless night, and the fall in testosterone looked mostly like a male pattern. The study was not designed to compare the sexes, so the authors treat this as a lead for future work.","token_count":173},{"ordinal":2,"section":"Practical reading and limits","header":"Source: Lamon et al. 2021, The effect of acute sleep deprivation on skeletal muscle protein synthesis and the hormonal environment. Section: Practical reading and limits.","body":"One night without sleep made muscle less responsive to food the next day, which is one reason Coach treats sleep as part of training. The study measured short-term markers in a small group, without exercise, and did not measure muscle size, so it does not show that one bad night costs muscle. Total sleep loss is more extreme than a short night. A reasonable reading is that repeated poor sleep may hold back progress, and that protecting sleep matters more than any supplement.","token_count":163}]$lib$::jsonb
);

-- library-source: borde_2015_older_adults_dose_response sha256:acc0fe7f17ddd6c9a1b04e29ea4d1877735f2738e7317d206ce484b61c5bc54f
select private.library_replace_source(
$lib${"slug":"borde_2015_older_adults_dose_response","title":"Dose-response relationships of resistance training in healthy old adults: a systematic review and meta-analysis","authors":["Borde R","Hortobágyi T","Granacher U"],"year":2015,"doi":"10.1007/s40279-015-0385-9","url":"https://doi.org/10.1007/s40279-015-0385-9","licence":"CC-BY-4.0","region":["global"],"topics":["older-adults","strength","hypertrophy","intensity","volume","training"],"evidence_level":"systematic review and meta-analysis (25 randomised trials, 819 older adults)","kind":"paper"}$lib$::jsonb,
$lib$[{"ordinal":0,"section":"What the review did","header":"Source: Borde et al. 2015, Dose-response relationships of resistance training in healthy old adults: a systematic review and meta-analysis. Section: What the review did.","body":"The authors pooled 25 randomised trials of resistance training in 819 healthy older adults (average age about 70, range 60 to 90), mostly previously sedentary people starting to lift. They measured strength and muscle size, and used meta-regression plus separate analyses of each training variable to see which settings went with the largest gains.","token_count":130},{"ordinal":1,"section":"Findings","header":"Source: Borde et al. 2015, Dose-response relationships of resistance training in healthy old adults: a systematic review and meta-analysis. Section: Findings.","body":"Lifting produced large strength gains (standardised difference about 1.6) for both upper and lower body, but only small gains in muscle size (about 0.4, from nine studies).\n\nProgramme length, load and time under tension each predicted strength gains. Looking at one variable at a time, the largest effects came with programmes of about a year (50 to 53 weeks), loads of 70 to 79 percent of the one-repetition maximum, 2 to 3 sets per exercise, 7 to 9 repetitions per set, two sessions a week and about 6 seconds per repetition. A 60 second rest between sets looked best, but that rested on only two studies; most studies used 2 minutes.","token_count":199},{"ordinal":2,"section":"Practical reading and limits","header":"Source: Borde et al. 2015, Dose-response relationships of resistance training in healthy old adults: a systematic review and meta-analysis. Section: Practical reading and limits.","body":"Older adults gain strength readily from moderately heavy, progressive lifting a couple of times a week, and gains keep building over months, so patience pays. Muscle size responds more slowly. Study quality was low (average 4.6 of 10 on the quality scale), results varied widely, and each variable was analysed on its own, so the 'best' values are a starting guide, not a tested combined programme. Tracend's rules set the actual numbers, and anyone frail or with a medical condition should be guided by a professional.","token_count":175}]$lib$::jsonb
);

-- library-source: izquierdo_2021_icfsr_older_adults sha256:ac5040f0335ef89995d9c3612e959ab035057decaf277f9edb0352bef18631ab
select private.library_replace_source(
$lib${"slug":"izquierdo_2021_icfsr_older_adults","title":"International exercise recommendations in older adults (ICFSR): expert consensus guidelines","authors":["Izquierdo M","Merchant RA","Morley JE","Anker SD","Aprahamian I","Arai H"],"year":2021,"doi":"10.1007/s12603-021-1665-8","url":"https://doi.org/10.1007/s12603-021-1665-8","licence":"CC-BY-4.0","region":["global"],"topics":["older-adults","guidelines","strength","cardio","training","bodyweight"],"evidence_level":"international expert consensus guideline","kind":"guideline"}$lib$::jsonb,
$lib$[{"ordinal":0,"section":"What the guideline is","header":"Source: Izquierdo et al. 2021 (ICFSR), International exercise recommendations in older adults (ICFSR): expert consensus guidelines. Section: What the guideline is.","body":"An international group of 36 experts, published under the International Conference on Frailty and Sarcopenia Research (ICFSR) name, reviewed the evidence on exercise in older adults. Much of the document covers frailty, chronic disease and hospital care; this summary uses only the parts on healthy, independent older adults. Its starting points are that some exercise beats none, that advice should be individual and tied to a goal, and that a programme should combine strength, aerobic, balance and flexibility work, though a sedentary person may start with one type and add others.","token_count":187},{"ordinal":1,"section":"Strength and power","header":"Source: Izquierdo et al. 2021 (ICFSR), International exercise recommendations in older adults (ICFSR): expert consensus guidelines. Section: Strength and power.","body":"It recommends resistance training 2 to 3 times a week, starting with 1 to 2 sets and building to 2 to 3 sets of 8 to 12 repetitions, using about 6 to 10 exercises for the major muscles, both multi-joint and single-joint, with at least a day between sessions for the same muscles. Loads progressing towards 70 to 80 percent of the one-repetition maximum gave larger strength gains than light or moderate loads, with effort kept hard to very hard.\n\nPower training, lifting fast and lowering under control without going to failure, is recommended because power declines earlier than strength. Rising quickly from a chair is a simple bodyweight start, with added load once bodyweight is no longer enough.","token_count":216},{"ordinal":2,"section":"Practical reading and limits","header":"Source: Izquierdo et al. 2021 (ICFSR), International exercise recommendations in older adults (ICFSR): expert consensus guidelines. Section: Practical reading and limits.","body":"Aerobic work can start at 5 to 10 minutes and build to 15 to 30 minutes, 3 to 7 days a week, and may be split into short bouts; harder intervals give the largest fitness gains. Balance work progresses from the hardest stance that can be held safely. These are expert recommendations built on trials, often in frail or clinical groups, so for a healthy older athlete they are a guide. Frailty, falls, disease and rehabilitation are for a professional; Coach does not plan them.","token_count":162}]$lib$::jsonb
);

-- library-source: bauer_2013_prot_age_protein sha256:45ddd34e76f047ecf3063a8c2f04fdd151b133dc53e36c4f7b08fbe82a2732e4
select private.library_replace_source(
$lib${"slug":"bauer_2013_prot_age_protein","title":"Evidence-based recommendations for optimal dietary protein intake in older people: a position paper from the PROT-AGE study group","authors":["Bauer J","Biolo G","Cederholm T","Cesari M","Cruz-Jentoft AJ","Morley JE"],"year":2013,"doi":"10.1016/j.jamda.2013.05.021","url":"https://doi.org/10.1016/j.jamda.2013.05.021","licence":"CC-BY-NC-ND-4.0","region":["global"],"topics":["older-adults","protein","nutrition","guidelines"],"evidence_level":"expert position paper (international study group)","kind":"position_stand"}$lib$::jsonb,
$lib$[{"ordinal":0,"section":"What the position paper is","header":"Source: Bauer et al. 2013 (PROT-AGE), Evidence-based recommendations for optimal dietary protein intake in older people: a position paper from the PROT-AGE study group. Section: What the position paper is.","body":"The European Union Geriatric Medicine Society, with other scientific organisations, appointed an international study group (PROT-AGE) to review protein needs with ageing. It argues that older adults need more protein than younger adults because their muscles respond less to the protein they eat and more of it is taken up by the gut and liver before it reaches the muscles, and because illness, common with age, raises needs further.","token_count":160},{"ordinal":1,"section":"Recommendations for healthy older people","header":"Source: Bauer et al. 2013 (PROT-AGE), Evidence-based recommendations for optimal dietary protein intake in older people: a position paper from the PROT-AGE study group. Section: Recommendations for healthy older people.","body":"To help people over 65 keep and regain lean mass and function, the group recommends an average intake of at least 1.0 to 1.2 g of protein per kg of body weight a day. For older people who exercise or are otherwise active it advises 1.2 g per kg a day or more, alongside endurance and resistance exercise at a level that is safe and tolerated for the individual.\n\nIt found the evidence not yet strong enough for specific advice on protein quality, the timing of protein or other supplements. The paper also covers older people with acute or chronic disease, which this summary leaves out.","token_count":202},{"ordinal":2,"section":"Practical reading and limits","header":"Source: Bauer et al. 2013 (PROT-AGE), Evidence-based recommendations for optimal dietary protein intake in older people: a position paper from the PROT-AGE study group. Section: Practical reading and limits.","body":"For a healthy older lifter, 1.2 g per kg a day is best read as a floor, not a target; the protein sources for people who train elsewhere in this library (Jäger 2017, Morton 2018) support somewhat higher intakes. This is a 2013 expert position summarised from the abstract only. The paper notes that people with severe kidney disease may need to limit protein, so anyone with kidney disease or another medical condition should get protein advice from a clinician, not from Coach.","token_count":172}]$lib$::jsonb
);

-- library-source: roberts_2020_sex_differences_resistance_training sha256:6584b129d1a4a98ee11a1167a4dad857f35d9b9f82c6c6c4704d46577ed95c1a
select private.library_replace_source(
$lib${"slug":"roberts_2020_sex_differences_resistance_training","title":"Sex differences in resistance training: a systematic review and meta-analysis","authors":["Roberts BM","Nuckols G","Krieger JW"],"year":2020,"doi":"10.1519/JSC.0000000000003521","url":"https://doi.org/10.1519/JSC.0000000000003521","licence":"proprietary","region":["global"],"topics":["women","sex-differences","strength","hypertrophy","training"],"evidence_level":"systematic review and meta-analysis (up to 23 studies per outcome)","kind":"paper"}$lib$::jsonb,
$lib$[{"ordinal":0,"section":"What the review did","header":"Source: Roberts et al. 2020, Sex differences in resistance training: a systematic review and meta-analysis. Section: What the review did.","body":"The authors pooled studies in which young to middle-aged men and women followed the same resistance training programme, to see whether relative gains in muscle size and strength differed by sex. The protocol was registered in advance, and the analysis used methods suited to studies reporting several outcomes.","token_count":112},{"ordinal":1,"section":"Findings","header":"Source: Roberts et al. 2020, Sex differences in resistance training: a systematic review and meta-analysis. Section: Findings.","body":"For muscle growth, men and women came out the same (12 outcomes from 10 studies, effect size about 0.07, with no variation between studies).\n\nLower-body strength showed no significant sex difference either (23 studies). Relative to where they started, women improved upper-body strength more, by a moderate amount (17 studies). The authors float the idea that untrained women have more room to improve there, while admitting the cause is unclear: it could be the nervous system, the muscle, picking up the movement skill, or just the short studies.","token_count":169},{"ordinal":2,"section":"Practical reading and limits","header":"Source: Roberts et al. 2020, Sex differences in resistance training: a systematic review and meta-analysis. Section: Practical reading and limits.","body":"Men and women gain muscle and strength at similar relative rates on the same programme, so women do not need a separate kind of training; the same principles of effort, volume and progression apply, adjusted to the person. The findings are relative, not absolute, changes; the authors note the studies were short and the upper-body result may apply mainly to untrained women, and the strength results varied a lot between studies. This summary is from the abstract only. For cycle and contraceptive questions see the Colenso-Semple 2023, McNulty 2020 and Elliott-Sale 2020 entries.","token_count":182}]$lib$::jsonb
);

-- library-source: colenso_semple_2023_menstrual_cycle_resistance sha256:10b240b9e0bcfff2cb7f900ca62e41c3b07354a3ba42ef7ea5fad052a9189377
select private.library_replace_source(
$lib${"slug":"colenso_semple_2023_menstrual_cycle_resistance","title":"Current evidence shows no influence of women's menstrual cycle phase on acute strength performance or adaptations to resistance exercise training","authors":["Colenso-Semple LM","D'Souza AC","Elliott-Sale KJ","Phillips SM"],"year":2023,"doi":"10.3389/fspor.2023.1054542","url":"https://doi.org/10.3389/fspor.2023.1054542","licence":"CC-BY-4.0","region":["global"],"topics":["women","menstrual-cycle","strength","hypertrophy","training"],"evidence_level":"umbrella review (5 systematic reviews)","kind":"paper"}$lib$::jsonb,
$lib$[{"ordinal":0,"section":"What the review did","header":"Source: Colenso-Semple et al. 2023, Current evidence shows no influence of women's menstrual cycle phase on acute strength performance or adaptations to resistance exercise training. Section: What the review did.","body":"This umbrella review searched four databases in January 2022 for systematic reviews and meta-analyses on menstrual cycle phase and resistance training in healthy, naturally cycling women not using hormonal contraception. Five reviews qualified, three with meta-analyses, and each was rated for quality.","token_count":129},{"ordinal":1,"section":"Findings","header":"Source: Colenso-Semple et al. 2023, Current evidence shows no influence of women's menstrual cycle phase on acute strength performance or adaptations to resistance exercise training. Section: Findings.","body":"The reviews disagreed. Three of the five, including the McNulty 2020 network analysis in this library, found trivial or no effects of cycle phase on strength. The two reviews suggesting phase effects relied on few, very mixed studies, and one combined women on and off the pill. The two training trials behind 'train harder in the first half of the cycle' had design problems: their schedules assumed every woman ovulated mid-cycle with equal-length halves (one was built only for a 28-day cycle), and neither confirmed ovulation with a reliable test.\n\nThe authors stress that cycle length and the timing of ovulation vary widely between women, and between cycles in the same woman, so counting days is a poor guide to hormone levels.","token_count":234},{"ordinal":2,"section":"Practical reading and limits","header":"Source: Colenso-Semple et al. 2023, Current evidence shows no influence of women's menstrual cycle phase on acute strength performance or adaptations to resistance exercise training. Section: Practical reading and limits.","body":"The authors conclude that there is no good evidence for building strength programmes around cycle phase, and that the plan should fit the individual. Symptoms do affect some women, so logging how training feels across the cycle is useful for spotting a personal pattern. This is an umbrella review whose authors state their opinion; the underlying studies are small and often poorly controlled, so a small effect cannot be ruled out. It does not cover hormonal contraception, irregular cycles or menopause, and Coach gives no medical advice on these.","token_count":193}]$lib$::jsonb
);

-- library-source: elliott_sale_2020_oral_contraceptives_performance sha256:375f303d62075d451ba9bef0d4f67971c433a1c0b89cf591e5865d6e5bef0a2d
select private.library_replace_source(
$lib${"slug":"elliott_sale_2020_oral_contraceptives_performance","title":"The effects of oral contraceptives on exercise performance in women: a systematic review and meta-analysis","authors":["Elliott-Sale KJ","McNulty KL","Ansdell P","Goodall S","Hicks KM","Thomas K"],"year":2020,"doi":"10.1007/s40279-020-01317-5","url":"https://doi.org/10.1007/s40279-020-01317-5","licence":"CC-BY-4.0","region":["global"],"topics":["women","oral-contraceptives","performance","menstrual-cycle"],"evidence_level":"systematic review and meta-analysis (42 studies, 590 women)","kind":"paper"}$lib$::jsonb,
$lib$[{"ordinal":0,"section":"What the review did","header":"Source: Elliott-Sale et al. 2020, The effects of oral contraceptives on exercise performance in women: a systematic review and meta-analysis. Section: What the review did.","body":"The authors pooled 42 studies with 590 women. They compared women taking oral contraceptive pills with naturally menstruating women, matching the pill-free days with the early part of the cycle and the pill-taking days with the rest of it. They also compared performance on pill-taking days with the pill-free days in the same women. Strength and endurance outcomes were analysed together, and 83 percent of studies were rated moderate, low or very low quality.","token_count":159},{"ordinal":1,"section":"Findings","header":"Source: Elliott-Sale et al. 2020, The effects of oral contraceptives on exercise performance in women: a systematic review and meta-analysis. Section: Findings.","body":"On average, women taking the pill may perform slightly worse than naturally menstruating women, but the difference was most likely trivial and varied a lot between studies. There was effectively no chance that pill users performed even slightly better (by a small effect or more).\n\nWithin pill users, performance was steady across the pill cycle: taking the pill or being on the pill-free days made almost no difference. Restricting the analysis to better-quality studies did not change these conclusions.","token_count":167},{"ordinal":2,"section":"Practical reading and limits","header":"Source: Elliott-Sale et al. 2020, The effects of oral contraceptives on exercise performance in women: a systematic review and meta-analysis. Section: Practical reading and limits.","body":"The authors say the evidence does not justify general advice to use or avoid the pill for performance, and suggest an individual approach when performance matters most. For Coach this means a woman on the pill can train as normal, with no need to plan around pill days, and any pattern she notices herself is worth tracking. Most studies were small (about 10 per group) and observational. Choosing or changing contraception is a medical decision for the woman and her clinician; Coach does not advise on it.","token_count":172}]$lib$::jsonb
);

-- library-source: kikuchi_2017_push_up_bench_press sha256:c9f588ba08d5f575ecfa05eff5dae3af48ee87fe3c531c80e72fadc5eabeea41
select private.library_replace_source(
$lib${"slug":"kikuchi_2017_push_up_bench_press","title":"Low-load bench press and push-up induce similar muscle hypertrophy and strength gain","authors":["Kikuchi N","Nakazato K"],"year":2017,"doi":"10.1016/j.jesf.2017.06.003","url":"https://doi.org/10.1016/j.jesf.2017.06.003","licence":"CC-BY-NC-ND-4.0","region":["global"],"topics":["bodyweight","home-training","minimal-equipment","hypertrophy","strength"],"evidence_level":"randomised trial comparing two training groups (18 young men)","kind":"paper"}$lib$::jsonb,
$lib$[{"ordinal":0,"section":"What the study did","header":"Source: Kikuchi and Nakazato 2017, Low-load bench press and push-up induce similar muscle hypertrophy and strength gain. Section: What the study did.","body":"Eighteen male university students with at least a year of recreational resistance training (the paper also calls them untrained) were randomly split into two groups for 8 weeks. One did bench press at 40 percent of their one-repetition maximum; the other did push-ups with the body position adjusted (for example on the knees) so the load roughly matched that same 40 percent, based on published estimates. Both did 3 sets to failure with 2 minutes' rest, twice a week, with supervision. Muscle thickness was measured by ultrasound at the chest, triceps and biceps.","token_count":179},{"ordinal":1,"section":"Findings","header":"Source: Kikuchi and Nakazato 2017, Low-load bench press and push-up induce similar muscle hypertrophy and strength gain. Section: Findings.","body":"Chest and triceps thickness rose in both groups by similar amounts (chest by about 18 to 19 percent), with no difference between groups. Biceps thickness rose only in the bench press group. Bench press one-repetition maximum rose in both groups, from about 60 to 65 kg with bench press and from about 61 to 64 kg with push-ups, again with no significant difference between groups. Neither group improved upper-body power in a medicine ball throw.","token_count":147},{"ordinal":2,"section":"Practical reading and limits","header":"Source: Kikuchi and Nakazato 2017, Low-load bench press and push-up induce similar muscle hypertrophy and strength gain. Section: Practical reading and limits.","body":"Push-ups taken close to failure can build the chest and triceps much like light bench pressing, so a person without equipment is not stuck. Difficulty can be adjusted by kneeling, raising the hands or feet, or adding a band or a weight on the back. The trial was small, only young men took part, it lasted 8 weeks, and diet was not controlled. Push-ups were matched to a light load, so this does not show bodyweight work equals heavy lifting for maximal strength.","token_count":156}]$lib$::jsonb
);

-- library-source: wiedenmann_2025_older_adults_training_modalities sha256:2ed7357311c251f85a56c9306d944443abbece6077aabd24b3b827f5ca264aa3
select private.library_replace_source(
$lib${"slug":"wiedenmann_2025_older_adults_training_modalities","title":"The effects of different resistance training modalities on muscle strength in community-dwelling older adults: a network meta-analysis","authors":["Wiedenmann T","Held S","Morat T","Rappelt L","Isenmann E","Berndsen E"],"year":2025,"doi":"10.1159/000546346","url":"https://doi.org/10.1159/000546346","licence":"proprietary","region":["global"],"topics":["older-adults","bodyweight","equipment","machines","free-weights","strength"],"evidence_level":"network meta-analysis (102 trials, 4,754 older adults)","kind":"paper"}$lib$::jsonb,
$lib$[{"ordinal":0,"section":"What the review did","header":"Source: Wiedenmann et al. 2025, The effects of different resistance training modalities on muscle strength in community-dwelling older adults: a network meta-analysis. Section: What the review did.","body":"The authors searched three databases for controlled trials in community-dwelling older adults that compared types of resistance training with each other or with no training, on maximal strength. They included 102 trials with 4,754 people (average age about 70, range 63 to 87) and used a network meta-analysis, which ranks options even when they were not tested head to head.","token_count":144},{"ordinal":1,"section":"Findings","header":"Source: Wiedenmann et al. 2025, The effects of different resistance training modalities on muscle strength in community-dwelling older adults: a network meta-analysis. Section: Findings.","body":"Compared with not training, all five approaches raised strength by a moderate to large amount. Machine training had the largest effect (standardised difference about 1.3) and the most consistent results, followed by free weights (about 1.2, with a wide range of uncertainty), elastic bands (about 0.9), mixed programmes (about 0.9) and bodyweight training (about 0.7, also with a wide range).\n\nThe authors suggest that, provided the training is hard enough, frequent enough and long enough, which type to use may come down to what the person likes and can actually do.","token_count":189},{"ordinal":2,"section":"Practical reading and limits","header":"Source: Wiedenmann et al. 2025, The effects of different resistance training modalities on muscle strength in community-dwelling older adults: a network meta-analysis. Section: Practical reading and limits.","body":"Bodyweight and band training clearly work for older adults, so home training is a real option, but bodyweight alone gave the smallest estimated gain of the five types. Tracend's reading is that adding load or harder variations as exercises get easy keeps the work hard enough, in line with the authors' point that intensity and volume must be adequate. The ranking is uncertain because some estimates had wide ranges and different trials used different programmes. Only strength was analysed, not muscle size or daily function, and this summary is from the abstract only.","token_count":195}]$lib$::jsonb
);

-- library-source: spiering_2021_minimal_dose_maintenance sha256:2b6eab90af342e3cd29e57de931bfec35a17fccae5e9447296478bebfdf8ab1f
select private.library_replace_source(
$lib${"slug":"spiering_2021_minimal_dose_maintenance","title":"Maintaining physical performance: the minimal dose of exercise needed to preserve endurance and strength over time","authors":["Spiering BA","Mujika I","Sharp MA","Foulis SA"],"year":2021,"doi":"10.1519/JSC.0000000000003964","url":"https://doi.org/10.1519/JSC.0000000000003964","licence":"proprietary","region":["global"],"topics":["minimal-dose","time-efficient","detraining","intensity","travel","older-adults"],"evidence_level":"narrative review","kind":"paper"}$lib$::jsonb,
$lib$[{"ordinal":0,"section":"What the review did","header":"Source: Spiering et al. 2021, Maintaining physical performance: the minimal dose of exercise needed to preserve endurance and strength over time. Section: What the review did.","body":"Most active people hit periods when time for exercise is short, and the goal becomes keeping what they have rather than improving. This brief narrative review gathered studies on the smallest frequency, volume and intensity of exercise that preserve endurance and strength in general populations, with notes on athletes and military personnel.","token_count":130},{"ordinal":1,"section":"Findings","header":"Source: Spiering et al. 2021, Maintaining physical performance: the minimal dose of exercise needed to preserve endurance and strength over time. Section: Findings.","body":"In general populations, endurance was maintained for up to 15 weeks when training dropped to as few as two sessions a week, or when volume was cut by a third to two thirds (as little as 13 to 26 minutes a session), provided intensity, judged by exercising heart rate, stayed the same.\n\nStrength and muscle size, at least in younger people, were maintained for up to 32 weeks with as little as one strength session a week and one set per exercise, provided the relative load stayed the same. Older people may need about two sessions a week and two to three sets per exercise to keep muscle size. There were too few data to give specific advice for athletes or military personnel.","token_count":211},{"ordinal":2,"section":"Practical reading and limits","header":"Source: Spiering et al. 2021, Maintaining physical performance: the minimal dose of exercise needed to preserve endurance and strength over time. Section: Practical reading and limits.","body":"The authors' main message is that intensity is the variable to protect: during a busy spell, fewer and shorter sessions can hold fitness if they stay hard. That makes a short, intense maintenance week a reasonable option during travel or a crunch at work. This is a narrative review, not a pooled analysis, and the summary is from the abstract only. It fits the Mujika 2001 and Bosquet 2013 detraining entries: doing a little keeps far more than doing nothing.","token_count":162}]$lib$::jsonb
);

-- library-source: janse_van_rensburg_2021_travel_jet_lag sha256:7bd4cf1cc56b4414b2568864f269fa0e849c06e48b82c9c2075edeff4aae868a
select private.library_replace_source(
$lib${"slug":"janse_van_rensburg_2021_travel_jet_lag","title":"Managing travel fatigue and jet lag in athletes: a review and consensus statement","authors":["Janse van Rensburg DC","Jansen van Rensburg A","Fowler PM","Bender AM","Stevens D","Sullivan KO"],"year":2021,"doi":"10.1007/s40279-021-01502-0","url":"https://doi.org/10.1007/s40279-021-01502-0","licence":"proprietary","region":["global"],"topics":["travel","jet-lag","sleep","recovery","performance"],"evidence_level":"review and expert consensus statement (26 experts)","kind":"position_stand"}$lib$::jsonb,
$lib$[{"ordinal":0,"section":"What the statement is","header":"Source: Janse van Rensburg et al. 2021, Managing travel fatigue and jet lag in athletes: a review and consensus statement. Section: What the statement is.","body":"Twenty-six researchers and clinicians from 11 countries reviewed the evidence and voted on recommendations for athletes who travel. They separate two problems. Travel fatigue follows any long journey, whatever the direction, can build up with repeated trips, and comes from the journey itself: cramped seats, mild lack of oxygen in the cabin and sitting still. Jet lag follows fast travel across three or more time zones, when the body clock stays on home time; it is temporary and ends once the clock catches up.","token_count":167},{"ordinal":1,"section":"What it says","header":"Source: Janse van Rensburg et al. 2021, Managing travel fatigue and jet lag in athletes: a review and consensus statement. Section: What it says.","body":"As a rule of thumb, the body clock adjusts by about half a day per time zone crossed when flying west and about a day per time zone when flying east. Common symptoms are daytime sleepiness, poor sleep, gut upset and poorer mental and physical performance, worse with more time zones. Air travel without crossing time zones did not measurably reduce performance in team athletes but did worsen mood, alertness and fatigue.\n\nFor travel fatigue the statement points to allowing a recovery window before hard training, protecting sleep, and using naps and caffeine after arrival. For jet lag, light is the main tool: timed exposure to and avoidance of bright light helps the clock shift, while badly timed light can make it worse.","token_count":218},{"ordinal":2,"section":"Practical reading and limits","header":"Source: Janse van Rensburg et al. 2021, Managing travel fatigue and jet lag in athletes: a review and consensus statement. Section: Practical reading and limits.","body":"The evidence is thin: no trials exist for travel fatigue remedies and the jet lag evidence is low quality, so these are expert recommendations. A guide for a travelling user is to keep the first days lighter, train at times that feel good locally and protect sleep. The panel cautions that jet lag apps are unvalidated. Melatonin and sleep medicines are discussed in the statement, but whether to use them is for a doctor.","token_count":146}]$lib$::jsonb
);

-- library-source: hhs_2018_physical_activity_guidelines sha256:dd1912adb8013dc84e28ca23ce83698396e1f676b9708e13d47e93e205abd9bd
select private.library_replace_source(
$lib${"slug":"hhs_2018_physical_activity_guidelines","title":"Physical Activity Guidelines for Americans, 2nd edition","authors":["US Department of Health and Human Services"],"year":2018,"doi":null,"url":"https://odphp.health.gov/sites/default/files/2019-09/Physical_Activity_Guidelines_2nd_edition.pdf","licence":"public-domain-us-gov","region":["US"],"topics":["activity","cardio","strength","guidelines","progression","older-adults","safety","sedentary"],"evidence_level":"national public health guideline (2018 Advisory Committee evidence review)","kind":"guideline"}$lib$::jsonb,
$lib$[{"ordinal":0,"section":"How much adults need","header":"Source: HHS 2018 (Physical Activity Guidelines for Americans), Physical Activity Guidelines for Americans, 2nd edition. Section: How much adults need.","body":"For substantial health benefit, adults are advised to get 150 to 300 minutes a week of moderate aerobic activity, or 75 to 150 minutes of vigorous activity, or a mix of the two, ideally spread across the week. Going beyond the equivalent of 300 moderate minutes brings further benefit. On top of that, adults should do muscle-strengthening work of at least moderate intensity that covers all the major muscle groups on two or more days a week.\n\nThe guideline also tells adults to move more and sit less, because any amount of moderate or vigorous activity helps. The 2008 rule that activity only counted in bouts of at least 10 minutes was dropped: bouts of any length now count towards the weekly total.","token_count":214},{"ordinal":1,"section":"Strength work and building up","header":"Source: HHS 2018 (Physical Activity Guidelines for Americans), Physical Activity Guidelines for Americans, 2nd edition. Section: Strength work and building up.","body":"No set time is given for strength work. Each exercise should be taken to the point where another repetition would be hard. For strength, one set of 8 to 12 repetitions per exercise works, and 2 or 3 sets may work better.\n\nThe guideline's phrase for beginners is \"start low and go slow\". An inactive person starts with light or moderate activity in short sessions spread over the week (its example is walking 5 minutes several times a day, building towards 10 minutes three times a day) and strength work on one day a week, rising to two or more. It notes that injury risk grows with the gap between a person's usual activity and the new level, and that healthy adults planning gradual increases do not need to see a clinician first. The largest health gain comes from going from no activity to about 60 minutes a week.","token_count":245},{"ordinal":2,"section":"Older adults and safety","header":"Source: HHS 2018 (Physical Activity Guidelines for Americans), Physical Activity Guidelines for Americans, 2nd edition. Section: Older adults and safety.","body":"Older adults follow the adult guidelines and add multicomponent activity: balance training together with aerobic and strength work. They should judge effort relative to their own fitness, understand how any chronic condition affects safe activity, and stay as active as they can when 150 minutes is out of reach. Stretching improves flexibility, but its health benefits are unknown and it does not count towards the aerobic or strength targets.","token_count":150},{"ordinal":3,"section":"Practical reading and limits","header":"Source: HHS 2018 (Physical Activity Guidelines for Americans), Physical Activity Guidelines for Americans, 2nd edition. Section: Practical reading and limits.","body":"This is a public health floor for health, not a programme for maximum muscle or performance, so a lifter's plan usually goes well beyond it. It agrees closely with the WHO 2020 entry; the Piercy 2018 entry is its journal summary. The document is a US federal work in the public domain, so a short quotation with attribution (as above) is allowed. Its pregnancy guidance is outside Tracend's scope.","token_count":139}]$lib$::jsonb
);

-- library-source: usda_hhs_2026_dietary_guidelines sha256:d81e0d8c6941d639bb1ce8aaab9dbf2815b3d6bb4754a1bc6b3f95aa01834e08
select private.library_replace_source(
$lib${"slug":"usda_hhs_2026_dietary_guidelines","title":"Dietary Guidelines for Americans, 2025-2030","authors":["US Department of Agriculture","US Department of Health and Human Services"],"year":2026,"doi":null,"url":"https://cdn.realfood.gov/DGA.pdf","licence":"public-domain-us-gov","region":["US"],"topics":["nutrition","protein","guidelines","energy-balance","vegetarian","alcohol","hydration","older-adults"],"evidence_level":"national dietary guideline","kind":"guideline"}$lib$::jsonb,
$lib$[{"ordinal":0,"section":"What this edition says","header":"Source: USDA and HHS 2026 (Dietary Guidelines for Americans), Dietary Guidelines for Americans, 2025-2030. Section: What this edition says.","body":"The 10th edition, from the US Departments of Agriculture and of Health and Human Services, is a short document built around eating whole, nutrient-dense food and sharply cutting highly processed food, added sugars and refined carbohydrate. The two secretaries describe it as a major reset of federal nutrition advice.\n\nCalorie needs depend on age, sex, height, weight and activity, and portion size deserves attention. Protein foods, animal and plant, should come first at every meal, with a goal of 1.2 to 1.6 g of protein per kg of body weight a day, adjusted to calorie needs. For a 2,000-calorie pattern it suggests 3 servings of dairy (including full-fat dairy with no added sugars), 3 of vegetables, 2 of fruit and 2 to 4 of whole grains.","token_count":221},{"ordinal":1,"section":"Limits, drinks and salt","header":"Source: USDA and HHS 2026 (Dietary Guidelines for Americans), Dietary Guidelines for Americans, 2025-2030. Section: Limits, drinks and salt.","body":"Saturated fat should generally stay at or below 10 percent of daily calories. No amount of added sugar is recommended, and a single meal should carry no more than 10 g of it. Water and unsweetened drinks are the default. Sodium should stay under 2,300 mg a day from age 14, though the document notes that very active people may benefit from more to cover sweat losses. On alcohol, drinking less is better for health.","token_count":140},{"ordinal":2,"section":"Vegetarians and older adults","header":"Source: USDA and HHS 2026 (Dietary Guidelines for Americans), Dietary Guidelines for Americans, 2025-2030. Section: Vegetarians and older adults.","body":"Vegetarian diets often fall short on vitamins D and E, choline and iron, and vegan diets on a wider list that includes vitamin B12, calcium, zinc and protein. The advice is to vary plant protein sources, limit highly processed vegetarian foods, and check iron, vitamin B12, vitamin D, calcium and iodine status from time to time. Older adults may need fewer calories but the same or more protein, vitamin B12, vitamin D and calcium.","token_count":145},{"ordinal":3,"section":"Practical reading and limits","header":"Source: USDA and HHS 2026 (Dietary Guidelines for Americans), Dietary Guidelines for Americans, 2025-2030. Section: Practical reading and limits.","body":"The protein goal sits close to the sports-nutrition range in the Jäger 2017 entry and well above India's allowance of 0.83 g per kg (the ICMR-NIN 2020 entry). They answer different questions: an allowance is the least that covers nearly every healthy person, while these goals aim higher. The plan's rules set the athlete's number. This summary covers the guideline document only, not the evidence review behind it; it is a US federal work in the public domain, so short quotation with attribution is allowed. That covers the text only: the PDF also contains Shutterstock images, which that public-domain status does not cover.","token_count":194}]$lib$::jsonb
);

-- library-source: uk_cmo_2026_activity_guidelines sha256:2c76d69e4e4e45869500db35af50aada65d779a8a21d69863f4a9a86a321960d
select private.library_replace_source(
$lib${"slug":"uk_cmo_2026_activity_guidelines","title":"UK Chief Medical Officers' physical activity guidelines","authors":["UK Chief Medical Officers","Department of Health and Social Care"],"year":2026,"doi":null,"url":"https://www.gov.uk/government/publications/physical-activity-guidelines-uk-chief-medical-officers-report/uk-chief-medical-officers-physical-activity-guidelines","licence":"OGL-UK-3.0","region":["GB"],"topics":["activity","cardio","strength","guidelines","older-adults","sedentary","minimal-dose"],"evidence_level":"national public health guideline (first issued 2011, revised 2019, evidence updated 2026)","kind":"guideline"}$lib$::jsonb,
$lib$[{"ordinal":0,"section":"What adults are advised to do","header":"Source: UK CMOs 2026, UK Chief Medical Officers' physical activity guidelines. Section: What adults are advised to do.","body":"Adults aged 19 to 64 should aim to be active every day, and any activity is better than none. They should do activities that build or keep strength in the major muscle groups on at least two days a week. Each week they should accumulate at least 150 minutes of moderate activity such as brisk walking or cycling, or 75 minutes of vigorous activity such as running, or even shorter spells of very vigorous activity such as sprinting or stair climbing, or a mix. Long spells of sitting should be broken up with at least light activity. In the guidelines' own words, \"some is good, more is better\".","token_count":179},{"ordinal":1,"section":"What the evidence behind it says","header":"Source: UK CMOs 2026, UK Chief Medical Officers' physical activity guidelines. Section: What the evidence behind it says.","body":"The 150 minutes can come in bouts of any length, or in one or two sessions a week, and still bring benefit. Benefit rises steeply up to about 150 minutes and more slowly after that, and the largest gain comes from moving from inactive to fairly active, even below the target.\n\nStrength work is described as being as important as the aerobic minutes. The evidence supports sessions once or twice a week, with measurable health benefit from more than 30 and up to 120 minutes a week, but not enough evidence to set a duration. Bodyweight, free weights, machines, bands and daily lifting and carrying all count. For weight loss, more than 150 minutes together with eating less may be needed, and no exact amount can be given. Total sitting above 6 to 8 hours a day was linked with higher mortality, but no sitting limit is set.","token_count":237},{"ordinal":2,"section":"Older adults","header":"Source: UK CMOs 2026, UK Chief Medical Officers' physical activity guidelines. Section: Older adults.","body":"People aged 65 and over should be active daily, work on strength, balance and flexibility on at least two days a week, and build up gradually towards 150 minutes of moderate activity (or 75 vigorous minutes if already active). They should break up sitting with light activity or at least standing. The evidence on high-intensity interval training in older people is described as very limited.","token_count":124},{"ordinal":3,"section":"Practical reading and limits","header":"Source: UK CMOs 2026, UK Chief Medical Officers' physical activity guidelines. Section: Practical reading and limits.","body":"The UK advice matches the WHO 2020 and US 2018 entries on aerobic minutes and twice-weekly strength work, and it is the clearest of the three that a little strength training already helps. These are health minimums, not targets for muscle growth, and the plan's rules set the actual work. The page is under the Open Government Licence v3.0, so short quotation with attribution is allowed. The next update is planned with the World Health Organization for 2030.","token_count":145}]$lib$::jsonb
);

-- library-source: icmr_nin_2020_nutrient_requirements sha256:45a5295fbb061b3daabce484a2b154ede456d515cca6600c1de5b6746e26217d
select private.library_replace_source(
$lib${"slug":"icmr_nin_2020_nutrient_requirements","title":"Nutrient requirements for Indians: Recommended Dietary Allowances (RDA) and Estimated Average Requirements (EAR), 2020","authors":["ICMR-NIN Expert Group on Nutrient Requirement for Indians"],"year":2020,"doi":null,"url":"https://www.nin.res.in/rdabook/brief_note.pdf","licence":"proprietary","region":["IN"],"topics":["nutrition","protein","energy-balance","guidelines","india","vegetarian"],"evidence_level":"national nutrient requirements (expert committee)","kind":"guideline"}$lib$::jsonb,
$lib$[{"ordinal":0,"section":"What the 2020 report changed","header":"Source: ICMR-NIN 2020 (RDA and EAR), Nutrient requirements for Indians: Recommended Dietary Allowances (RDA) and Estimated Average Requirements (EAR), 2020. Section: What the 2020 report changed.","body":"The 2020 expert group gives two values for each nutrient instead of one. The estimated average requirement (EAR) is the middle of the range of healthy people's needs; the recommended dietary allowance (RDA) sits near the top of that range, so it covers almost everyone. The group recommends using the EAR for planning diets, for individuals as well as populations, and keeping the RDA for addressing deficiency; EARs are typically about 80 percent of RDAs. Upper limits were added because more foods are now fortified.","token_count":179},{"ordinal":1,"section":"Energy","header":"Source: ICMR-NIN 2020 (RDA and EAR), Nutrient requirements for Indians: Recommended Dietary Allowances (RDA) and Estimated Average Requirements (EAR), 2020. Section: Energy.","body":"Energy need is worked out as basal metabolic rate multiplied by a physical activity level. Indian studies showed activities cost less energy than the Western figures assumed, so the activity factor for sedentary people was lowered from 1.53 to 1.40, and the basal rate predicted by international equations was cut by a further 5 percent for adults (this adds to the 2010 cut, so the total is 10 percent below the international equations). Adult energy needs therefore fell by about 3 to 8 kcal per kg a day compared with 2010. The reference adults weigh 65 kg (men) and 55 kg (women); for sedentary work the reference man needs about 2,110 kcal a day and the reference woman about 1,660. Visible fat such as cooking oil is advised at 20 to 50 g a day, depending on energy needs.","token_count":238},{"ordinal":2,"section":"Protein","header":"Source: ICMR-NIN 2020 (RDA and EAR), Nutrient requirements for Indians: Recommended Dietary Allowances (RDA) and Estimated Average Requirements (EAR), 2020. Section: Protein.","body":"For healthy adults (the same per-kg figure is given for sedentary, moderate and heavy work) the average requirement is 0.66 g of protein per kg a day and the allowance is 0.83 g per kg (lowered from 1 g per kg in 2010). For people whose diet is mostly cereal with low-quality protein, the requirement is given as 1 g per kg. The report adopts a newer protein-quality score based on digestibility of individual amino acids (DIAAS), and for good protein quality it suggests a cereal to legume to milk ratio of about 3 to 1 to 2.5 in the diet.","token_count":179},{"ordinal":3,"section":"Practical reading and limits","header":"Source: ICMR-NIN 2020 (RDA and EAR), Nutrient requirements for Indians: Recommended Dietary Allowances (RDA) and Estimated Average Requirements (EAR), 2020. Section: Practical reading and limits.","body":"These figures are the amounts that prevent deficiency in healthy, mostly sedentary adults, not targets for building muscle. People who train are given 1.4 to 2.0 g per kg in the Jäger 2017 entry, and the 2026 US guidelines give 1.2 to 1.6 g per kg for the general public; the plan's rules set the athlete's number. For an Indian vegetarian diet the report's point about quality matters: combining cereals with dal and milk or curd improves protein quality. This summary is from NIN's official brief note, not the full book.","token_count":180}]$lib$::jsonb
);

-- library-source: longvah_2017_ifct sha256:22775336d0c25754be4cfd46840005bb87e7368088540571d62c8499815aa8b4
select private.library_replace_source(
$lib${"slug":"longvah_2017_ifct","title":"Indian Food Composition Tables 2017","authors":["Longvah T","Ananthan R","Bhaskarachary K","Venkaiah K"],"year":2017,"doi":null,"url":"https://nin.res.in/ebooks/IFCT2017.pdf","licence":"proprietary","region":["IN"],"topics":["nutrition","food-composition","protein","india","vegetarian"],"evidence_level":"national food composition database (laboratory analysis)","kind":"summary"}$lib$::jsonb,
$lib$[{"ordinal":0,"section":"What the tables are","header":"Source: Longvah et al. 2017 (IFCT), Indian Food Composition Tables 2017. Section: What the tables are.","body":"The National Institute of Nutrition's 2017 tables give values for 151 food components in 528 key foods. Key foods were chosen from a national rural diet survey as the foods supplying most of the population's nutrients. Samples were bought in 107 of India's then 630 districts, pooled within six regions, and analysed in the laboratory; for most foods the national value is the mean of the six regions (some foods were sampled in fewer), and no figures were borrowed from other databases. India's first food composition table dates from 1937.","token_count":161},{"ordinal":1,"section":"How to read the values","header":"Source: Longvah et al. 2017 (IFCT), Indian Food Composition Tables 2017. Section: How to read the values.","body":"Values are per 100 g as analysed (raw, except the egg, which is boiled), for the edible portion. Energy is calculated with standard Atwater factors and reported in kilojoules. The authors warn that vitamins vary with processing and cooking, and that the tables are not a complete list of foods eaten in India: many regional and community dishes are missing.\n\nA few single values show the scale. Per 100 g raw, red gram (toor) dal has about 22 g of protein, lentil (masoor) dal about 24 g and whole Bengal gram (chana) about 19 g; paneer has about 19 g, and a whole boiled egg about 13 g.","token_count":174},{"ordinal":2,"section":"Practical reading and limits","header":"Source: Longvah et al. 2017 (IFCT), Indian Food Composition Tables 2017. Section: Practical reading and limits.","body":"Because the values are for raw food, a cooked portion must be matched to its raw weight: weighing cooked dal, which has absorbed water, against the raw-dal figure would greatly overstate its protein and energy. Values are national averages, and a given batch or brand can differ. NIN's terms do not allow the tables to be reproduced in an electronic product without written permission, so Tracend stores only these individual facts with the citation.","token_count":141}]$lib$::jsonb
);

-- library-source: who_2004_asian_bmi sha256:0b8b381fd24c47bcb3fab68b3777449466d8c0bf8d7e6998cc4600fba87fc535
select private.library_replace_source(
$lib${"slug":"who_2004_asian_bmi","title":"Appropriate body-mass index for Asian populations and its implications for policy and intervention strategies","authors":["WHO Expert Consultation"],"year":2004,"doi":"10.1016/S0140-6736(03)15268-3","url":"https://doi.org/10.1016/S0140-6736(03)15268-3","licence":"proprietary","region":["IN"],"topics":["bmi","body-composition","health","guidelines","india"],"evidence_level":"expert consultation (evidence review)","kind":"guideline"}$lib$::jsonb,
$lib$[{"ordinal":0,"section":"What the consultation did","header":"Source: WHO expert consultation 2004, Appropriate body-mass index for Asian populations and its implications for policy and intervention strategies. Section: What the consultation did.","body":"WHO convened experts to settle whether the standard BMI cut-offs suit Asian people, who tend to carry more body fat, and more disease risk, at a given BMI than people of European origin.","token_count":93},{"ordinal":1,"section":"Conclusions","header":"Source: WHO expert consultation 2004, Appropriate body-mass index for Asian populations and its implications for policy and intervention strategies. Section: Conclusions.","body":"Many Asian adults already face raised diabetes and heart-disease risk below a BMI of 25. Where that risk starts differs between Asian groups (from about 22 to 25, with high risk from 26 to 31), so the experts set no single Asian cut-off. They kept the international categories and added extra points for public-health action at 23, 27.5, 32.5 and 37.5, leaving each country to decide where its own increased-risk range begins.","token_count":150},{"ordinal":2,"section":"Practical reading and limits","header":"Source: WHO expert consultation 2004, Appropriate body-mass index for Asian populations and its implications for policy and intervention strategies. Section: Practical reading and limits.","body":"For Indian adults, a BMI of 23 to 25 can already be a reason to look at waist size, activity and diet rather than a sign that all is well (the Misra 2025 entry gives India's current clinical criteria). BMI cannot tell muscle from fat, so a muscular lifter can sit above these points with little body fat. These are population screening points; Coach never diagnoses. This summary is from the abstract only, so the evidence behind each figure is not described here.","token_count":163}]$lib$::jsonb
);

-- library-source: misra_2025_obesity_asian_indians sha256:2908bdb1bc1e2fbfd7ebeeb2cd083cfbfdfcda5d7ca76dec524e3b36865fd446
select private.library_replace_source(
$lib${"slug":"misra_2025_obesity_asian_indians","title":"Revised definition of obesity in Asian Indians living in India","authors":["Misra A","Vikram NK","Ghosh A","Ranjan P","Gulati S","India Obesity Commission Members"],"year":2025,"doi":"10.1016/j.dsx.2024.102989","url":"https://doi.org/10.1016/j.dsx.2024.102989","licence":"proprietary","region":["IN"],"topics":["bmi","body-composition","fat-loss","activity","guidelines","india"],"evidence_level":"expert consensus (Delphi, five rounds, 118 experts invited)","kind":"guideline"}$lib$::jsonb,
$lib$[{"ordinal":0,"section":"What the consensus did","header":"Source: Misra et al. 2025, Revised definition of obesity in Asian Indians living in India. Section: What the consensus did.","body":"The 2009 Indian consensus had defined overweight as a BMI of 23 to 24.9, obesity as 25 or more, and abdominal obesity as a waist of 90 cm or more in men and 80 cm or more in women. This update, by an Indian obesity commission, used a five-round Delphi survey of experts (118 were invited) to move from BMI alone to a definition that also counts fat distribution, physical function and related disease. A statement needed agreement from at least two thirds of respondents.","token_count":149},{"ordinal":1,"section":"The new definition","header":"Source: Misra et al. 2025, Revised definition of obesity in Asian Indians living in India. Section: The new definition.","body":"Stage 1 obesity is a BMI of 23 or more with no effect on organ function or daily activities and no obesity-related disease. Stage 2 obesity needs a BMI of 23 or more plus excess waist size or waist-to-height ratio, together with limits in daily activities or an obesity-related disease. Body fat is named the gold standard where it can be measured (above 25.5 percent in men and 38 percent in women). The waist cut-offs remain 90 cm for men and 80 cm for women, a waist-to-height ratio above 0.5 counts as excess, and a normal BMI is 18.5 to just under 23.","token_count":169},{"ordinal":2,"section":"Diet and activity advice","header":"Source: Misra et al. 2025, Revised definition of obesity in Asian Indians living in India. Section: Diet and activity advice.","body":"For weight loss the paper suggests a daily deficit of roughly 500 kcal, and calls a loss of 0.5 to 1 kg a week safe (which needs a deficit of about 500 to 1,000 kcal a day), kept up long term. It recommends at least 60 minutes of activity a day for weight loss, notes that 45 to 60 minutes of moderate activity a day is linked with moving out of the overweight range, and asks for muscle-strengthening work on at least three days a week, increased gradually. People with heart, lung or nerve and muscle conditions should be assessed by a professional before starting.","token_count":174},{"ordinal":3,"section":"Practical reading and limits","header":"Source: Misra et al. 2025, Revised definition of obesity in Asian Indians living in India. Section: Practical reading and limits.","body":"This is a clinical definition for diagnosis by doctors; Coach never stages or diagnoses obesity. Its lower cut-offs fit the WHO 2004 entry. The paper calls measured body fat the gold standard but treats it as optional, and its rules let body fat override BMI only when BMI is below 23; it makes no exception for muscular people. A lifter can reach a BMI of 23 or more with little fat, so for people who train, a BMI of 23 or more alone is not evidence of excess fat. Its rate of loss in kilograms is a general figure; for people who train, the library's fat-loss sources prefer about 0.5 to 1 percent of body weight a week. The drug and surgery sections are outside Tracend's scope and are not summarised.","token_count":209}]$lib$::jsonb
);

-- library-source: anjana_2014_indiab_activity sha256:27b40a32357f2fb8a39cc871a1cab1fdbec1d874dbdf9ee2413e4daf198582a5
select private.library_replace_source(
$lib${"slug":"anjana_2014_indiab_activity","title":"Physical activity and inactivity patterns in India: results from the ICMR-INDIAB study (Phase-1) [ICMR-INDIAB-5]","authors":["Anjana RM","Pradeepa R","Das AK","Deepa M","Bhansali A","Joshi SR"],"year":2014,"doi":"10.1186/1479-5868-11-26","url":"https://doi.org/10.1186/1479-5868-11-26","licence":"CC-BY-2.0","region":["IN"],"topics":["activity","india","sedentary","health","behaviour-change"],"evidence_level":"cross-sectional survey (14,227 adults, four regions)","kind":"paper"}$lib$::jsonb,
$lib$[{"ordinal":0,"section":"What the study did","header":"Source: Anjana et al. 2014 (ICMR-INDIAB), Physical activity and inactivity patterns in India: results from the ICMR-INDIAB study (Phase-1) [ICMR-INDIAB-5]. Section: What the study did.","body":"As part of the Indian Council of Medical Research's diabetes study, researchers surveyed 14,227 adults aged 20 and over (about 4,200 urban and 10,000 rural) in Tamil Nadu, Maharashtra, Jharkhand and Chandigarh, chosen to represent the south, west, east and north of India. Activity was self-reported with the WHO Global Physical Activity Questionnaire, which covers work, travel and recreation.","token_count":145},{"ordinal":1,"section":"Findings","header":"Source: Anjana et al. 2014 (ICMR-INDIAB), Physical activity and inactivity patterns in India: results from the ICMR-INDIAB study (Phase-1) [ICMR-INDIAB-5]. Section: Findings.","body":"Just over half (54.4 percent) were inactive by the questionnaire's standard, 31.9 percent were active and 13.7 percent highly active. Inactivity was more common in towns than villages (65 against 50 percent) and in women than men (63 against 46 percent), and was highest in Chandigarh. Most moderate or vigorous activity came from work: those who had any active work averaged about 46 minutes a day (about a third of the sample), and those who reported active travel averaged about 14 minutes. More than 90 percent did no recreational activity at all, and the share with none rose with age.","token_count":192},{"ordinal":2,"section":"Practical reading and limits","header":"Source: Anjana et al. 2014 (ICMR-INDIAB), Physical activity and inactivity patterns in India: results from the ICMR-INDIAB study (Phase-1) [ICMR-INDIAB-5]. Section: Practical reading and limits.","body":"For many Indian adults, activity has come from work and getting around rather than from exercise, so as jobs and travel become less physical, deliberate exercise and steps have to fill the gap. Women and city dwellers were the least active groups. The data are self-reported, from four regions surveyed before 2014, and the questionnaire may not fit every local activity, so current national levels may differ.","token_count":152}]$lib$::jsonb
);

